pub(super) fn fresh_launch_preamble_parts(kind: SessionKind) -> Vec<String> {
    let mut parts = Vec::new();
    if let Some(router) = super::preamble::load_orchestration_router() {
        parts.push(router);
    }
    if let Some(preamble) = super::preamble::load(kind) {
        parts.push(preamble);
    }
    parts
}
