fn sandbox_filesystem_stats(path: &std::path::Path) -> Result<SandboxFilesystemStats> {
    #[cfg(test)]
    if let Some(stats) = sandbox_filesystem_stats_overrides_for_test()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .get(path)
        .copied()
    {
        return Ok(stats);
    }

    let stats = nix::sys::statvfs::statvfs(path)
        .map_err(|error| DaemonError::Process(format!("sandbox statvfs failed: {error}")))?;
    let fragment_size = stats.fragment_size() as u64;
    let total_bytes = (stats.blocks() as u64).saturating_mul(fragment_size);
    let available_bytes = (stats.blocks_available() as u64).saturating_mul(fragment_size);
    if total_bytes == 0 {
        return Err(DaemonError::Process(
            "sandbox statvfs reported zero total bytes".to_string(),
        ));
    }
    let used_bytes = total_bytes.saturating_sub(available_bytes);
    let used_percent = ((u128::from(used_bytes) * 100) / u128::from(total_bytes)) as u8;
    Ok(SandboxFilesystemStats {
        total_bytes,
        available_bytes,
        used_bytes,
        used_percent,
    })
}

