#[cfg(test)]
fn install_sandbox_filesystem_stats_override_for_test(
    path: &std::path::Path,
    stats: SandboxFilesystemStats,
) -> SandboxFilesystemStatsOverrideGuard {
    let path = path.to_path_buf();
    let mut overrides = sandbox_filesystem_stats_overrides_for_test()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    match overrides.entry(path.clone()) {
        std::collections::hash_map::Entry::Vacant(entry) => {
            entry.insert(stats);
        }
        std::collections::hash_map::Entry::Occupied(_) => {
            panic!("sandbox filesystem stats override already installed for {path:?}");
        }
    }
    SandboxFilesystemStatsOverrideGuard { path }
}

fn increment_reclaim_skip(report: &mut SandboxBuildCacheReclaimReport, reason: ReclaimSkipReason) {
    *report.skip_counts.entry(reason).or_insert(0) += 1;
}

fn reclaim_budget_stop_reason(reason: ReclaimSkipReason) -> Option<ReclaimStopReason> {
    match reason {
        ReclaimSkipReason::RecoveryEntryBudget => Some(ReclaimStopReason::RecoveryEntryBudget),
        ReclaimSkipReason::FilesystemEntryBudget => Some(ReclaimStopReason::FilesystemEntryBudget),
        ReclaimSkipReason::ByteBudget => Some(ReclaimStopReason::ByteBudget),
        ReclaimSkipReason::DurationBudget => Some(ReclaimStopReason::DurationBudget),
        ReclaimSkipReason::DepthBudget => Some(ReclaimStopReason::DepthBudget),
        _ => None,
    }
}

fn is_reclaim_budget_stop(reason: ReclaimStopReason) -> bool {
    matches!(
        reason,
        ReclaimStopReason::RecoveryEntryBudget
            | ReclaimStopReason::FilesystemEntryBudget
            | ReclaimStopReason::ByteBudget
            | ReclaimStopReason::DurationBudget
            | ReclaimStopReason::DepthBudget
    )
}

fn checkpoint_reclaim_report(
    report: &mut SandboxBuildCacheReclaimReport,
    pass: &crate::sandbox::target_reclaim::ReclaimPassState,
) -> bool {
    let Err(reason) = pass.checkpoint(0) else {
        return false;
    };
    let stop =
        reclaim_budget_stop_reason(reason).expect("pass checkpoint can only return a budget stop");
    if report.stop_reason != stop {
        increment_reclaim_skip(report, reason);
        report.stop_reason = stop;
    }
    true
}

fn refresh_reclaimable_claims(
    report: &mut SandboxBuildCacheReclaimReport,
    pass: &crate::sandbox::target_reclaim::ReclaimPassState,
) {
    // Keep calculating the revalidated pass-wide point-in-time estimate for
    // hard-link deduplication and hostile tests, but never publish it as
    // definite future capacity.  Another namespace actor can add a retaining
    // link after the final observation.  Only an actual post-delete statvfs
    // delta is a capacity claim.
    let _point_in_time_estimate = pass.reclaimable_summary();
    report.would_reclaim_bytes = 0;
    report.would_reclaim_count = 0;
}

