fn try_submit_reclaim_job(
    sender: &std::sync::mpsc::SyncSender<SandboxReclaimJob>,
    state: &SandboxReclaimWorkerState,
    job: SandboxReclaimJob,
) -> Result<()> {
    state.queued.fetch_add(1, Ordering::AcqRel);
    match sender.try_send(job) {
        Ok(()) => Ok(()),
        Err(std::sync::mpsc::TrySendError::Full(_)) => {
            state.queued.fetch_sub(1, Ordering::AcqRel);
            Err(DaemonError::Process(format!(
                "sandbox target-cache reclaim queue is full ({MAX_QUEUED_RECLAIM_REQUESTS})"
            )))
        }
        Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
            state.queued.fetch_sub(1, Ordering::AcqRel);
            Err(DaemonError::Process(
                "sandbox reclaim coordinator worker unavailable".to_string(),
            ))
        }
    }
}

fn run_sandbox_reclaim_worker(
    receiver: std::sync::mpsc::Receiver<SandboxReclaimJob>,
    state: Arc<SandboxReclaimWorkerState>,
    runtime: tokio::runtime::Runtime,
) {
    while let Ok(job) = receiver.recv() {
        state.queued.fetch_sub(1, Ordering::AcqRel);
        let previous = state.active.fetch_add(1, Ordering::AcqRel);
        debug_assert_eq!(
            previous, 0,
            "reclaim worker must run one lifecycle at a time"
        );
        run_sandbox_reclaim_job(&runtime, job, &state);
        state.active.fetch_sub(1, Ordering::AcqRel);
    }
}

fn run_sandbox_reclaim_job(
    runtime: &tokio::runtime::Runtime,
    job: SandboxReclaimJob,
    state: &SandboxReclaimWorkerState,
) {
    let SandboxReclaimJob {
        context,
        dry_run,
        prepared_only,
        trigger,
        manager_key,
        enqueued_at,
        dispatch,
        result_tx,
    } = job;
    let immediate_recovery_context = (!dry_run && !prepared_only).then(|| context.clone());
    let run_started_at = Instant::now();
    let queue_wait_ms = bounded_elapsed_ms(enqueued_at);
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        tracing::dispatcher::with_default(&dispatch, || {
            log_sandbox_build_cache_reclaim_started(trigger, dry_run, queue_wait_ms);
            runtime.block_on(SessionManager::run_sandbox_build_cache_reclaim_owned(
                context,
                dry_run,
                prepared_only,
                manager_key,
                state,
            ))
        })
    }))
    .unwrap_or_else(|_| {
        Err(DaemonError::Process(
            "sandbox reclaim coordinator job panicked".to_string(),
        ))
    });
    let request_cancelled = result_tx.is_closed();
    let run_duration_ms = bounded_elapsed_ms(run_started_at);
    let total_elapsed_ms = bounded_elapsed_ms(enqueued_at);
    tracing::dispatcher::with_default(&dispatch, || match &result {
        Ok(run) => {
            log_reclaim_pressure_health(trigger, run, state);
            log_sandbox_build_cache_reclaim_terminal(
                trigger,
                run,
                request_cancelled,
                run_duration_ms,
                total_elapsed_ms,
            );
        }
        Err(error) => log_sandbox_build_cache_reclaim_error(
            trigger,
            dry_run,
            error,
            request_cancelled,
            Some(run_duration_ms),
            Some(total_elapsed_ms),
        ),
    });
    let _ = result_tx.send(result);
    if let Some(context) = immediate_recovery_context {
        let prepared_pending = context.store.try_lock().is_ok_and(|store| {
            store
                .target_reclaim_intent_counts()
                .is_ok_and(|counts| counts.prepared > 0)
        });
        if prepared_pending {
            let immediate = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                runtime.block_on(SessionManager::run_sandbox_build_cache_reclaim_owned(
                    context,
                    false,
                    true,
                    manager_key,
                    state,
                ))
            }));
            if !matches!(immediate, Ok(Ok(_))) {
                tracing::warn!("Immediate Prepared reclaim recovery deferred to one-second retry");
            }
        }
    }
}

fn log_reclaim_pressure_health(
    trigger: &'static str,
    run: &SandboxReclaimRun,
    state: &SandboxReclaimWorkerState,
) {
    if run.report.dry_run {
        return;
    }
    let store_busy_skips = run
        .report
        .skip_counts
        .get(&ReclaimSkipReason::StoreBusy)
        .copied()
        .unwrap_or(0);
    if run.report.pressure_active_after && run.report.reclaimed_bytes == 0 && store_busy_skips > 0 {
        let consecutive = state
            .consecutive_store_busy_pressure_passes
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |count| {
                Some(count.saturating_add(1))
            })
            .unwrap_or(usize::MAX)
            .saturating_add(1);
        tracing::warn!(
            trigger,
            consecutive_store_busy_pressure_passes = consecutive,
            store_busy_skips,
            "Sandbox build-cache reclaim is degraded under disk pressure"
        );
    } else {
        state
            .consecutive_store_busy_pressure_passes
            .store(0, Ordering::Release);
    }
}

fn bounded_elapsed_ms(started_at: Instant) -> u64 {
    started_at.elapsed().as_millis().min(u128::from(u64::MAX)) as u64
}

fn log_authority_restore_phase(
    phase: &'static str,
    phase_started_at: Instant,
    restore_started_at: Instant,
) {
    tracing::info!(
        startup_milestone = "authority_restore_phase_complete",
        phase,
        phase_duration_ms = bounded_elapsed_ms(phase_started_at),
        total_elapsed_ms = bounded_elapsed_ms(restore_started_at),
        "Daemon authority restore phase completed"
    );
}

