#[cfg(test)]
async fn pause_reclaim_after_single_flight_for_test(
    manager_key: usize,
    _sandbox_base: &std::path::Path,
) {
    let hook = reclaim_single_flight_hook()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone();
    if let Some(hook) = hook.filter(|hook| hook.manager_key == manager_key) {
        hook.entered.add_permits(1);
        hook.release
            .acquire()
            .await
            .expect("single-flight test release")
            .forget();
    }
}

