async fn pause_reclaim_after_single_flight_for_test(
    _manager_key: usize,
    sandbox_base: &std::path::Path,
) {
    let Some(entered_path) =
        std::env::var_os("RSI_SR2_TEST_RECLAIM_ENTERED").map(std::path::PathBuf::from)
    else {
        return;
    };
    let Some(release_path) =
        std::env::var_os("RSI_SR2_TEST_RECLAIM_RELEASE").map(std::path::PathBuf::from)
    else {
        return;
    };
    let Ok(authenticated_base) = sandbox_base.canonicalize() else {
        return;
    };
    let paths_are_fixture_local = [&entered_path, &release_path].iter().all(|path| {
        path.parent()
            .and_then(|parent| parent.canonicalize().ok())
            .is_some_and(|parent| parent == authenticated_base)
    });
    if !paths_are_fixture_local {
        tracing::warn!(
            "Ignoring SR-2 reclaim hold because its barriers are outside the sandbox base"
        );
        return;
    }
    if std::fs::write(&entered_path, b"entered\n").is_err() {
        return;
    }
    let deadline = Instant::now() + Duration::from_secs(10);
    while !release_path.exists() && Instant::now() < deadline {
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
}

