#[cfg(test)]
fn take_final_scratch_revalidation_failure_for_test(control_key: &str, app_server: bool) -> bool {
    let mut controls = direct_launch_custody_test_controls()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(control) = controls.get_mut(control_key) else {
        return false;
    };
    let failure = if app_server {
        &mut control.fail_app_server_final_scratch_revalidation
    } else {
        &mut control.fail_cli_final_scratch_revalidation
    };
    std::mem::take(failure)
}

#[cfg(test)]
fn inject_final_scratch_drift_for_test(control_key: &str, app_server: bool, config: &LaunchConfig) {
    if !take_final_scratch_revalidation_failure_for_test(control_key, app_server) {
        return;
    }
    use std::os::unix::fs::PermissionsExt;
    let scratch = config
        .execution_scratch
        .as_ref()
        .expect("final scratch drift injection requires a prepared descriptor");
    std::fs::set_permissions(scratch.temp(), std::fs::Permissions::from_mode(0o755))
        .expect("inject final scratch mode drift");
}

