#[cfg(test)]
fn install_successor_task_provider_test_process(
    session_id: Uuid,
    provider: SessionProvider,
) -> SuccessorTaskProviderTestProcess {
    assert!(matches!(
        provider,
        SessionProvider::Local | SessionProvider::Harness
    ));
    let process = SuccessorTaskProviderTestProcess {
        provider,
        productive_start_count: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
        cancel: tokio_util::sync::CancellationToken::new(),
    };
    successor_task_provider_test_processes()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert(session_id, process.clone());
    process
}

#[cfg(test)]
fn take_successor_task_provider_test_process(
    session_id: Uuid,
    provider: SessionProvider,
) -> Option<(ProviderProcess, mpsc::Receiver<crate::claude::StreamEvent>)> {
    let process = successor_task_provider_test_processes()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .remove(&session_id)?;
    assert_eq!(process.provider, provider);
    process
        .productive_start_count
        .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let task_cancel = process.cancel.clone();
    let task_handle = tokio::spawn(async move {
        task_cancel.cancelled().await;
    });
    let provider_process = match provider {
        SessionProvider::Local => {
            ProviderProcess::Local(crate::openai::OpenAiProcess::test_task(task_handle))
        }
        SessionProvider::Harness => ProviderProcess::Harness(super::types::HarnessProcess {
            task_handle,
            cancel: process.cancel,
        }),
        _ => unreachable!("test task process only supports Local and Harness"),
    };
    let (stream_tx, stream_rx) = mpsc::channel(1);
    controller_candidate_test_streams()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert(session_id, stream_tx);
    Some((provider_process, stream_rx))
}

