/// RAII cleanup for a sandbox allocated mid-launch.
///
/// Sandbox allocation runs before the session becomes visible in `active`
/// (fail-closed: see the allocation call site), but everything between those
/// two points — project resolution, context-pipeline assembly, admission
/// control, provider process spawn — can fail, time out, or (if the
/// connection task is ever aborted) unwind without any of those call sites
/// running. D00 classifies an armed drop as blocked and deliberately retains
/// the allocation for recovery; the next startup path-only pass classifies and
/// retains it again. `disarm()` must be called only after a direct launch has
/// durably bound its custody ownership; non-direct launches retain the older
/// active-map boundary until their own custody path is converted.
struct SandboxLaunchGuard {
    session_id: Uuid,
    allocation: Option<SandboxAllocation>,
}

impl SandboxLaunchGuard {
    fn disarm(&mut self) {
        self.allocation = None;
    }
}

impl Drop for SandboxLaunchGuard {
    fn drop(&mut self) {
        let Some(allocation) = self.allocation.take() else {
            return;
        };
        let candidate = CleanupCandidate::LaunchAbort {
            session_id: self.session_id,
            root: allocation.root.clone(),
            branch: allocation.branch.clone(),
            origin: allocation.origin.clone(),
        };
        match cleanup::classify_candidate(
            &candidate,
            OwnershipObservation::Exclusive,
            OwnershipObservation::Exclusive,
        ) {
            CleanupDecision::Blocked(reason) => tracing::warn!(
                session_id = %self.session_id,
                sandbox_root = %allocation.root.display(),
                cleanup_reason = reason.as_str(),
                "Launch aborted after sandbox allocation; retained sandbox for recovery"
            ),
            CleanupDecision::NoCleanupRequired => tracing::warn!(
                session_id = %self.session_id,
                "Launch-abort guard found no sandbox target"
            ),
        }
    }
}

fn provider_uses_launch_system_prompt(provider: SessionProvider) -> bool {
    matches!(
        provider,
        SessionProvider::Claude
            | SessionProvider::Local
            | SessionProvider::Antigravity
            | SessionProvider::Harness
            | SessionProvider::CodexAppServer
    )
}

pub(super) fn launch_provider_label(provider: SessionProvider) -> String {
    format!("{provider:?}")
}

fn apply_provider_model_default(provider: SessionProvider, model: &mut Option<String>) {
    if provider == SessionProvider::Pioneer {
        *model = Some(crate::pioneer::pioneer_launch_model(model.as_deref()).to_string());
    } else if provider == SessionProvider::Bedrock && model.is_none() {
        *model = Some(crate::bedrock::BEDROCK_DEFAULT_MODEL.to_string());
    } else if provider == SessionProvider::OpenRouter && model.is_none() {
        *model = Some(crate::openrouter::OPENROUTER_DEFAULT_MODEL.to_string());
    }
}

/// The `ModelTier` a launch of `provider`/`model` will be classified as by
/// `admit_invocation`.
///
/// This co-locates the label pairing with the admission request that defines
/// it: `ModelAdmissionRequest` below sets BOTH `provider` and `backend` to
/// `launch_provider_label(provider)` (see the `admission_request` literal in
/// `launch_session_with_retry_admission`), and `admit_invocation`
/// (`model_control/mod.rs:602-606`) feeds exactly that pair plus the model
/// string into `classify_model_tier`. Any pre-check that wants to predict the
/// admission verdict MUST classify through this function — if the pairing
/// above ever changes, change it here in the same edit.
pub(super) fn admission_model_tier(
    provider: SessionProvider,
    model: Option<&str>,
) -> rsi_common::model_control::ModelTier {
    let label = launch_provider_label(provider);
    crate::model_control::classify_model_tier(Some(&label), Some(&label), model)
}

/// Initialize the only rotation state that may cross the scheduled-Fresh
/// boundary, then construct the coordinator from that exact persisted state.
/// Callers must pass their state explicitly; no ambient task-local launch
/// context is allowed here because nested launches must retain their own input.
fn initialize_session_rotation(
    session: &mut Session,
    initial_rotation_disabled: bool,
    context_rotation_enabled: bool,
) -> super::rotation_coordinator::RotationCoordinator {
    if initial_rotation_disabled {
        session
            .rotation_disabled_at
            .get_or_insert_with(chrono::Utc::now);
    } else if context_rotation_enabled {
        session.rotation_disabled_at = None;
    }
    super::rotation_coordinator::RotationCoordinator::new(
        session.id,
        0,
        context_rotation_enabled && session.rotation_disabled_at.is_none(),
    )
}

fn build_starting_session(
    config: &LaunchConfig,
    session_id: Uuid,
    provider: SessionProvider,
    working_dir: &std::path::Path,
    resolved_project_id: Option<Uuid>,
    session_kind: SessionKind,
    configured_max_retries: Option<u8>,
    default_max_retries: u8,
    allocation: Option<&SandboxAllocation>,
    git_branch: Option<String>,
    harness_version_hash: Option<String>,
    context_rotation_enabled: bool,
) -> Session {
    let resolved_context_budget = crate::provider_capabilities::resolve_fresh_context_budget(
        provider,
        config.model.as_deref().unwrap_or("unknown"),
        config.configured_context_window,
    );
    Session {
        context_fill_pct: None,
        id: session_id,
        provider,
        claude_session_id: None,
        query: config.query.clone(),
        title: config.title.clone(),
        agent_role: config.agent_role.clone(),
        epic_spawn_ordinal: config.epic_spawn_ordinal,
        description: None,
        short_summary: None,
        working_dir: working_dir.to_path_buf(),
        git_branch,
        status: SessionStatus::Starting,
        project_id: resolved_project_id,
        pinned_at: None,
        testing_needed_at: None,
        rotation_disabled_at: (!context_rotation_enabled).then(chrono::Utc::now),
        created_at: chrono::Utc::now(),
        updated_at: chrono::Utc::now(),
        cost_usd: None,
        duration_ms: None,
        num_turns: None,
        model: config.model.clone(),
        input_tokens: None,
        output_tokens: None,
        context_window: Some(resolved_context_budget.active_tokens),
        resolved_context_budget: Some(resolved_context_budget),
        total_input_tokens: None,
        total_output_tokens: None,
        session_kind,
        total_cache_creation_tokens: None,
        total_cache_read_tokens: None,
        stop_reason: None,
        continued_from: config.continued_from,
        context_usage_confidence: ContextUsageConfidence::Missing,
        daemon_input_tokens: None,
        daemon_output_tokens: None,
        handoff_filepath: None,
        active_task: None,
        group_id: config.group_id,
        pipeline_artifact: None,
        workflow_id: config.workflow_id,
        workflow_id_override: config.workflow_id_override,
        pending_question: None,
        pending_archive: false,
        rotation_depth: 0,
        retry_attempt: if configured_max_retries.is_some() || default_max_retries > 0 {
            Some(0)
        } else {
            None
        },
        max_retries: configured_max_retries.or(if default_max_retries > 0 {
            Some(default_max_retries)
        } else {
            None
        }),
        effort: config.effort.clone(),
        issue_identifier: config.issue_identifier.clone(),
        issue_url: config.issue_url.clone(),
        issue_tracker_id: config.issue_tracker_id.clone(),
        scheduled_job_id: config.scheduled_job_id,
        rating: None,
        harness_version_hash,
        test_passed: None,
        clippy_passed: None,
        turn_count: None,
        retry_count: None,
        approval_wait_ms: Some(0),
        approval_started_at: None,
        work_time_ms: Some(0),
        sandbox_kind: allocation.map(|a| a.kind),
        sandbox_root: allocation.map(|a| a.root.clone()),
        sandbox_branch: allocation.and_then(|a| a.branch.clone()),
        sandbox_cleanup_state: allocation.map(|_| SandboxCleanupState::Live),
        tag: String::new(),
        tags: Vec::new(),
        parent_id: config.parent_id,
        lead_session_id: None,
        is_eval: config.is_eval,
        capability_class: config.capability_class,
        topology_node_id: config.topology_node_id.clone(),
        topology_iteration: config.topology_iteration,
        // V99: populated from the provider handshake / result event, not at
        // construction. A session that never reaches those has none of these facts.
        provider_cli_version: None,
        provider_capabilities: Vec::new(),
        thinking_tokens: None,
        service_tier: None,
        cache_creation_1h_tokens: None,
        cache_creation_5m_tokens: None,
        permission_denial_count: None,
        subagent_stats_json: None,
        queued_turn_count: None,
        terminal_reason: None,
    }
}

/// Construct the generation-1 `New` custody binding for a freshly allocated
/// worktree. Shared by the direct-interactive launch boundary
/// (`CustodyCause::FreshLaunch`) and the agent-child fork admission
/// (`CustodyCause::AgentSpawnChild`, H1-04 / F-011).
pub(super) fn new_root_binding_from_allocation(
    allocation: &SandboxAllocation,
    working_dir: &std::path::Path,
    allocation_source_commit: Option<&str>,
    cause: CustodyCause,
    reserved_custody_id: Option<Uuid>,
) -> Result<SessionCustodyBinding> {
    let branch = allocation
        .branch
        .clone()
        .ok_or_else(|| DaemonError::Store("GitWorktree allocation omitted its branch".into()))?;
    let source_commit = allocation_source_commit
        .map(str::to_owned)
        .ok_or_else(|| DaemonError::Store("sandbox allocation omitted its source commit".into()))?;
    let common_dir = std::process::Command::new("git")
        .args(["rev-parse", "--path-format=absolute", "--git-common-dir"])
        // The allocator-selected worktree is the provenance
        // boundary. Resolve repository identity from that exact
        // allocation, never from the caller's configured path.
        .current_dir(&allocation.root)
        .output()
        .map_err(|error| {
            DaemonError::Process(format!(
                "failed to resolve sandbox repository identity: {error}"
            ))
        })?;
    if !common_dir.status.success() {
        return Err(DaemonError::Store(
            "sandbox repository identity is unavailable".into(),
        ));
    }
    let repository_identity =
        std::fs::canonicalize(String::from_utf8_lossy(&common_dir.stdout).trim())
            .map_err(|error| {
                DaemonError::Store(format!(
                    "failed to canonicalize sandbox repository identity: {error}"
                ))
            })?
            .to_string_lossy()
            .to_string();
    Ok(SessionCustodyBinding::New(NewCustodyRoot {
        custody_id: reserved_custody_id.unwrap_or_else(Uuid::new_v4),
        canonical_repo_dir: working_dir.to_string_lossy().to_string(),
        sandbox_root: allocation.root.to_string_lossy().to_string(),
        sandbox_branch: branch,
        repository_identity,
        source_commit,
        cause,
    }))
}

/// H1-04 (F-011): the durably Failed, non-executable child row recorded when
/// an AgentSpawnChild custody transition refuses or fails. Always an ordinary
/// (all-null) sandbox tuple: a refused fork owns no root, and a
/// custody-classified post-allocation failure leaves its allocation to the
/// launch guard's retained-for-recovery path rather than adopting it here.
fn failed_agent_spawn_child_session(
    config: &LaunchConfig,
    child_session_id: Uuid,
    code: rsi_common::types::SandboxCustodyErrorCodeV1,
) -> Session {
    let provider = config.provider.unwrap_or_default();
    let working_dir = config
        .working_dir
        .clone()
        .unwrap_or_else(|| std::path::PathBuf::from("/tmp"));
    let mut session = build_starting_session(
        config,
        child_session_id,
        provider,
        &working_dir,
        config.project_id,
        config.session_kind.unwrap_or_default(),
        config.max_retries,
        0,
        None,
        None,
        None,
        true,
    );
    session.status = SessionStatus::Failed;
    session.stop_reason = Some(format!("sandbox_custody:{}", code.as_str()));
    session
}

/// Persist the scheduled-Fresh disabled child before it can become active.
///
/// The savepoint keeps the row, its model-invocation binding, and the
/// rotation-disabled stamp all-or-nothing. It is deliberately transaction-only:
/// a caller with an already-spawned provider must stop that backend before
/// terminally settling its admission.
async fn persist_scheduled_fresh_disabled_row_before_active(
    store: &Arc<tokio::sync::Mutex<crate::store::Store>>,
    session: &Session,
    admission_permit: &crate::model_control::AdmissionPermit,
) -> Result<()> {
    const SAVEPOINT: &str = "scheduled_fresh_disabled_before_active";

    let persistence_error = {
        let store = store.lock().await;
        let result = (|| -> Result<()> {
            store
                .conn
                .execute_batch(&format!("SAVEPOINT {SAVEPOINT}"))?;
            match (|| -> Result<()> {
                store.insert_session_with_model_invocation(
                    session,
                    admission_permit.invocation_id(),
                )?;
                // `insert_session` persists the inherited timestamp. Reapply
                // it with SET semantics at this compound-write seam; toggling
                // would invert the freshly inserted value back to NULL.
                store.set_session_rotation_disabled_at(session.id, session.rotation_disabled_at)?;
                Ok(())
            })() {
                Ok(()) => store
                    .conn
                    .execute_batch(&format!("RELEASE SAVEPOINT {SAVEPOINT}"))?,
                Err(error) => {
                    if let Err(rollback_error) = store.conn.execute_batch(&format!(
                        "ROLLBACK TO SAVEPOINT {SAVEPOINT}; RELEASE SAVEPOINT {SAVEPOINT}"
                    )) {
                        return Err(DaemonError::Store(format!(
                            "failed to persist scheduled Fresh session {session_id}: {error}; rollback failed: {rollback_error}",
                            session_id = session.id,
                        )));
                    }
                    return Err(error);
                }
            }
            Ok(())
        })();
        result.err()
    };

    persistence_error.map_or(Ok(()), Err)
}

/// Clean up a scheduled-Fresh launch whose pre-active persistence failed.
///
/// CLI providers are already live by this point. Their process must be stopped
/// before the admission is settled, or the released reservation could admit
/// another backend while this one still consumes resources. App-server launch
/// is deferred and reaches this seam with no process, so it can settle directly.
async fn cleanup_failed_scheduled_fresh_before_active(
    store: &Arc<tokio::sync::Mutex<crate::store::Store>>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    session_id: Uuid,
    admission_permit: &crate::model_control::AdmissionPermit,
    event_bus: &Arc<crate::bus::EventBus>,
    initial_process: &mut Option<ProviderProcess>,
    persistence_error: DaemonError,
) -> Result<DaemonError> {
    if let Some(process) = initial_process.as_mut() {
        if let Err(kill_error) = process.kill().await {
            return Err(DaemonError::Process(format!(
                "failed to persist scheduled Fresh session {session_id}: {persistence_error}; failed to stop spawned provider before settling model admission: {kill_error}; admission remains running",
            )));
        }

        // Task-backed providers abort asynchronously. Yield once, then retain
        // the admission if the provider can still be live rather than claiming
        // a terminal invocation ahead of a backend that may consume resources.
        tokio::task::yield_now().await;
        if process.is_alive() {
            return Err(DaemonError::Process(format!(
                "failed to persist scheduled Fresh session {session_id}: {persistence_error}; spawned provider remained live after stop request; admission remains running",
            )));
        }
    }

    // The provider is confirmed absent (or has not yet been spawned for the
    // deferred app-server path), so this prospective authority can no longer
    // name a live session. Keep it when termination is unconfirmed above.
    super::revoke_agent_tokens_for_session(agent_tokens, session_id).await;

    if let Err(settlement_error) = complete_invocation(
        store,
        admission_permit,
        InvocationCompletion {
            error_class: Some("session_persistence_failed".to_string()),
            confidence: Some(ModelUsageConfidence::Unavailable),
            ..InvocationCompletion::default()
        },
        event_bus,
    )
    .await
    {
        return Err(DaemonError::Store(format!(
            "failed to persist scheduled Fresh session {session_id}: {persistence_error}; provider stopped before settlement but failed to settle model admission: {settlement_error}",
        )));
    }

    Ok(persistence_error)
}

fn launch_owner_from_config(
    session_id: Uuid,
    project_id: Option<Uuid>,
    config: &LaunchConfig,
) -> InvocationOwner {
    let mut owner = config.model_invocation_owner.clone().unwrap_or_default();
    owner.session_id = Some(session_id);
    if owner.project_id.is_none() {
        owner.project_id = project_id;
    }
    if owner.workflow_id.is_none() {
        owner.workflow_id = config.workflow_id;
    }
    if owner.scheduled_job_id.is_none() {
        owner.scheduled_job_id = config.scheduled_job_id;
    }
    if owner.issue_tracker_id.is_none() {
        owner.issue_tracker_id = config.issue_tracker_id.clone();
    }
    if owner.issue_identifier.is_none() {
        owner.issue_identifier = config.issue_identifier.clone();
    }
    if owner.topology_node_id.is_none() {
        owner.topology_node_id = config.topology_node_id.clone();
    }
    owner
}

async fn load_session_invocation_id(
    store: &Arc<tokio::sync::Mutex<crate::store::Store>>,
    session_id: Uuid,
) -> Result<Option<Uuid>> {
    let store_ref = Arc::clone(store);
    tokio::task::spawn_blocking(move || {
        let store = store_ref.blocking_lock();
        store.session_model_invocation_id(session_id)
    })
    .await
    .map_err(|e| DaemonError::Process(format!("failed to join model invocation lookup: {e}")))?
}

async fn resolve_parent_invocation_id_for_launch(
    store: &Arc<tokio::sync::Mutex<crate::store::Store>>,
    config: &LaunchConfig,
) -> Result<Option<Uuid>> {
    let Some(parent_id) = config.parent_id else {
        return Ok(None);
    };
    let purpose = config.model_invocation_purpose;
    let store_ref = Arc::clone(store);
    tokio::task::spawn_blocking(move || {
        let store = store_ref.blocking_lock();
        let target_session_id = if matches!(
            purpose,
            rsi_common::model_control::ModelInvocationPurpose::AgentSpawnChild
                | rsi_common::model_control::ModelInvocationPurpose::AgentReserveSuccessor
        ) {
            store.get_session(parent_id)?.map(|session| {
                if session.session_kind == rsi_common::types::SessionKind::Epic {
                    session.lead_session_id.unwrap_or(parent_id)
                } else {
                    parent_id
                }
            })
        } else {
            Some(parent_id)
        };
        target_session_id
            .map(|session_id| store.session_model_invocation_id(session_id))
            .transpose()
            .map(|value| value.flatten())
    })
    .await
    .map_err(|e| DaemonError::Process(format!("failed to join parent invocation lookup: {e}")))?
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DurableSessionRowCheck {
    Present,
    Missing,
    StoreBusy,
}

async fn signal_controller_candidate_confirmation(
    context: &mut ControllerTransferLaunchContext,
    store: &Arc<tokio::sync::Mutex<crate::store::Store>>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    provider: SessionProvider,
    admission_invocation_id: Uuid,
    confirmation_kind: ControllerConfirmationKindV1,
) -> bool {
    let Some(token) = context.prospective_a6.current_token().await else {
        context.confirmation_tx.take();
        return false;
    };
    let now = chrono::Utc::now();
    let store = store.lock().await;
    let durable = match store.get_session(context.reservation.candidate_session_id) {
        Ok(Some(session))
            if session.id == context.reservation.candidate_session_id
                && session.project_id == Some(context.project_id)
                && session.provider == provider
                && matches!(
                    session.status,
                    SessionStatus::Starting
                        | SessionStatus::Running
                        | SessionStatus::WaitingApproval
                ) =>
        {
            session
        }
        _ => {
            context.confirmation_tx.take();
            return false;
        }
    };
    if store
        .confirm_controller_candidate_reservation_v1(
            context.project_id,
            context.idea_id,
            &context.reservation,
            now,
        )
        .is_err()
    {
        context.confirmation_tx.take();
        return false;
    }
    let a6 = agent_tokens.read().await;
    if a6.get(&token).copied() != Some(context.reservation.candidate_session_id) {
        context.confirmation_tx.take();
        return false;
    }
    let confirmation = IdeaControllerLaunchConfirmationV1 {
        candidate_session_id: context.reservation.candidate_session_id,
        project_id: context.project_id,
        provider,
        admission_invocation_id,
        confirmation_kind,
        durable_session_id: durable.id,
        durable_project_id: durable.project_id.unwrap_or(context.project_id),
        durable_provider: durable.provider,
        a6_bound_session_id: context.reservation.candidate_session_id,
        confirmed_at: now,
    };
    let sent = context
        .confirmation_tx
        .take()
        .is_some_and(|sender| sender.send(confirmation).is_ok());
    drop(a6);
    drop(store);
    sent
}

async fn signal_agent_successor_confirmation(
    context: &mut AgentSuccessorLaunchContext,
    store: &Arc<tokio::sync::Mutex<crate::store::Store>>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    provider: SessionProvider,
    admission_invocation_id: Uuid,
    confirmation_kind: ControllerConfirmationKindV1,
) -> bool {
    let Some(token) = context.prospective_a6.current_token().await else {
        context.confirmation_tx.take();
        return false;
    };
    let store = store.lock().await;
    let durable_matches = store
        .get_session(context.reservation.candidate_session_id)
        .ok()
        .flatten()
        .is_some_and(|session| {
            session.id == context.reservation.candidate_session_id
                && session.parent_id == Some(context.reservation.epic_id)
                && session.continued_from == Some(context.reservation.predecessor_session_id)
                && session.provider == provider
                && matches!(
                    session.status,
                    SessionStatus::Starting
                        | SessionStatus::Running
                        | SessionStatus::WaitingApproval
                )
        })
        && store
            .session_model_invocation_id(context.reservation.candidate_session_id)
            .is_ok_and(|bound| bound == Some(admission_invocation_id));
    if !durable_matches {
        context.confirmation_tx.take();
        return false;
    }
    let a6 = agent_tokens.read().await;
    if a6.get(&token).copied() != Some(context.reservation.candidate_session_id) {
        context.confirmation_tx.take();
        return false;
    }
    let confirmation = AgentSuccessorLaunchConfirmation {
        candidate_session_id: context.reservation.candidate_session_id,
        provider,
        admission_invocation_id,
        confirmation_kind,
    };
    context
        .confirmation_tx
        .take()
        .is_some_and(|sender| sender.send(confirmation).is_ok())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeferredSuccessorStartRejection {
    Cancelled,
    IncarnationChanged,
}

impl DeferredSuccessorStartRejection {
    const fn reason(self) -> &'static str {
        match self {
            Self::Cancelled => "deferred successor provider start cancelled before provider effect",
            Self::IncarnationChanged => {
                "deferred successor live incarnation changed before provider effect"
            }
        }
    }

    const fn safe_error_class(self) -> &'static str {
        match self {
            Self::Cancelled => "agent_successor_deferred_provider_start_cancelled",
            Self::IncarnationChanged => "agent_successor_deferred_provider_incarnation_changed",
        }
    }
}

struct DeferredSuccessorStartPermit {
    gate: Arc<tokio::sync::Mutex<()>>,
    _guard: tokio::sync::OwnedMutexGuard<()>,
}

/// Acquire the exact live-incarnation witness for a deferred successor effect.
///
/// Lock order is gate -> Active, followed by gate -> Store at the durable
/// effect fence. The interrupt path snapshots the gate under Active but drops
/// Active before awaiting it, then uses the same gate -> Active order. This
/// permits holding the per-session gate across the slow app-server launch
/// without holding the global Active map or creating an inversion.
async fn acquire_deferred_successor_start_permit(
    active: &Arc<tokio::sync::RwLock<HashMap<Uuid, TrackedSession>>>,
    session_id: Uuid,
    spawn_generation: u64,
) -> std::result::Result<DeferredSuccessorStartPermit, DeferredSuccessorStartRejection> {
    let gate = {
        let active = active.read().await;
        let tracked = active
            .get(&session_id)
            .filter(|tracked| tracked.spawn_generation == spawn_generation)
            .ok_or(DeferredSuccessorStartRejection::IncarnationChanged)?;
        tracked
            .deferred_successor_start_gate
            .as_ref()
            .cloned()
            .ok_or(DeferredSuccessorStartRejection::IncarnationChanged)?
    };
    let guard = Arc::clone(&gate).lock_owned().await;
    let rejection = {
        let active = active.read().await;
        match active.get(&session_id) {
            Some(tracked)
                if tracked.spawn_generation == spawn_generation
                    && tracked
                        .deferred_successor_start_gate
                        .as_ref()
                        .is_some_and(|current| Arc::ptr_eq(current, &gate)) =>
            {
                tracked
                    .interrupt_requested
                    .then_some(DeferredSuccessorStartRejection::Cancelled)
            }
            _ => Some(DeferredSuccessorStartRejection::IncarnationChanged),
        }
    };
    if let Some(rejection) = rejection {
        return Err(rejection);
    }
    Ok(DeferredSuccessorStartPermit {
        gate,
        _guard: guard,
    })
}

// Manager candidates use their own journal/claim. No successor reservation or
// predecessor identity is synthesized to reuse the strong-successor API.
async fn settle_failed_deferred_manager_action(
    context: &super::types::ManagerActionLaunchContext,
    active: &Arc<tokio::sync::RwLock<HashMap<Uuid, TrackedSession>>>,
    store: &Arc<tokio::sync::Mutex<Store>>,
    event_bus: &Arc<crate::bus::EventBus>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    permit: &crate::model_control::AdmissionPermit,
    generation: u64,
    code: &str,
) {
    let target = context
        .claim
        .operation
        .context
        .target_session_id
        .expect("manager candidate");
    let settled: Result<Option<SessionStatus>> = async {
        let mut active = active.write().await;
        let mut store = store.lock().await;
        if active
            .get(&target)
            .is_some_and(|s| s.spawn_generation != generation)
            || store.session_model_invocation_id(target)? != Some(permit.invocation_id())
        {
            return Ok(None);
        }
        let old = active
            .remove(&target)
            .map(|s| s.session.status)
            .unwrap_or(SessionStatus::Starting);
        store.fail_bound_direct_launch(target, code)?;
        if let Some(op) = store.manager_action_operation(context.claim.id())? {
            if op.receipt.state == rsi_common::harness_manager_v2::ManagerActionStateV2::Running {
                use rsi_common::harness_manager_v2::ManagerActionStateV2;
                let state = if op.effect_started {
                    ManagerActionStateV2::Uncertain
                } else if matches!(
                    code,
                    "manager_v2_policy_changed"
                        | "manager_v2_scope_changed"
                        | "manager_v2_capability_denied"
                ) {
                    ManagerActionStateV2::Revoked
                } else {
                    ManagerActionStateV2::Blocked
                };
                store.finish_manager_action(&context.claim, state, code)?;
            }
        }
        super::revoke_agent_tokens_for_session(agent_tokens, target).await;
        Ok(Some(old))
    }
    .await;
    match settled {
        Ok(Some(old_status)) => {
            if let Err(error) = complete_invocation(
                store,
                permit,
                InvocationCompletion {
                    error_class: Some(code.into()),
                    confidence: Some(ModelUsageConfidence::Unavailable),
                    ..InvocationCompletion::default()
                },
                event_bus,
            )
            .await
            {
                tracing::warn!(session_id=%target,error=%error,"manager deferred admission settlement failed");
            }
            event_bus.publish(DaemonEvent::SessionStatusChanged {
                session_id: target,
                old_status,
                new_status: SessionStatus::Failed,
            });
        }
        Ok(None) => {}
        Err(error) => {
            tracing::warn!(session_id=%target,error=%error,"manager deferred custody settlement failed")
        }
    }
}

async fn settle_failed_deferred_agent_successor(
    context: &mut AgentSuccessorLaunchContext,
    active: &Arc<tokio::sync::RwLock<HashMap<Uuid, TrackedSession>>>,
    store: &Arc<tokio::sync::Mutex<Store>>,
    event_bus: &Arc<crate::bus::EventBus>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    permit: &crate::model_control::AdmissionPermit,
    spawn_generation: u64,
    reason: &str,
    safe_error_class: &str,
) {
    let candidate_id = context.reservation.candidate_session_id;
    let exact_incarnation = active
        .read()
        .await
        .get(&candidate_id)
        .is_some_and(|tracked| tracked.spawn_generation == spawn_generation);
    let exact_invocation = store
        .lock()
        .await
        .session_model_invocation_id(candidate_id)
        .is_ok_and(|bound| bound == Some(permit.invocation_id()));
    if !exact_incarnation || !exact_invocation {
        return;
    }
    let exact_token = context.prospective_a6.current_token().await;
    let old_status = {
        let mut active = active.write().await;
        if !active
            .get(&candidate_id)
            .is_some_and(|tracked| tracked.spawn_generation == spawn_generation)
        {
            return;
        }
        active
            .remove(&candidate_id)
            .map(|tracked| tracked.session.status)
            .unwrap_or(SessionStatus::Starting)
    };
    if let Some(token) = exact_token.as_deref() {
        agent_tokens
            .write()
            .await
            .revoke_session_if_token(candidate_id, token);
    }
    context.prospective_a6.clear().await;

    if let Err(error) = complete_invocation(
        store,
        permit,
        InvocationCompletion {
            error_class: Some(safe_error_class.to_string()),
            confidence: Some(ModelUsageConfidence::Unavailable),
            ..InvocationCompletion::default()
        },
        event_bus,
    )
    .await
    {
        tracing::warn!(
            session_id = %candidate_id,
            error = %error,
            "Failed to settle deferred successor model invocation"
        );
    }

    let reservation = &context.reservation;
    if let Some(attempt_id) = reservation.launch_attempt_id
        && let Err(error) = store
            .lock()
            .await
            .settle_agent_successor_establishment_failed(
                reservation.reservation_id,
                reservation.state_version,
                attempt_id,
                Uuid::new_v4(),
                reason,
                safe_error_class,
            )
    {
        tracing::warn!(
            reservation_id = %reservation.reservation_id,
            session_id = %candidate_id,
            error = %error,
            "Failed to terminally settle deferred successor establishment"
        );
    }
    context.confirmation_tx.take();
    event_bus.publish(DaemonEvent::SessionStatusChanged {
        session_id: candidate_id,
        old_status,
        new_status: SessionStatus::Failed,
    });
}

async fn settle_rejected_agent_successor_provider_effect(
    context: &AgentSuccessorLaunchContext,
    store: &Arc<tokio::sync::Mutex<Store>>,
    event_bus: &Arc<crate::bus::EventBus>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    permit: &crate::model_control::AdmissionPermit,
) {
    const REASON: &str = "durable successor provider-effect fence rejected";
    const SAFE_ERROR_CLASS: &str = "agent_successor_provider_effect_fence_rejected";

    let reservation = &context.reservation;
    let candidate_id = reservation.candidate_session_id;
    super::revoke_agent_tokens_for_session(agent_tokens, candidate_id).await;
    context.prospective_a6.clear().await;
    if let Some(attempt_id) = reservation.launch_attempt_id
        && let Err(error) = store
            .lock()
            .await
            .settle_agent_successor_establishment_failed(
                reservation.reservation_id,
                reservation.state_version,
                attempt_id,
                Uuid::new_v4(),
                REASON,
                SAFE_ERROR_CLASS,
            )
    {
        tracing::warn!(
            reservation_id = %reservation.reservation_id,
            session_id = %candidate_id,
            error = %error,
            "Failed to terminally settle rejected successor provider effect"
        );
    }
    if let Err(error) = complete_invocation(
        store,
        permit,
        InvocationCompletion {
            error_class: Some(SAFE_ERROR_CLASS.to_string()),
            confidence: Some(ModelUsageConfidence::Unavailable),
            ..InvocationCompletion::default()
        },
        event_bus,
    )
    .await
    {
        tracing::warn!(
            reservation_id = %reservation.reservation_id,
            session_id = %candidate_id,
            error = %error,
            "Failed to settle rejected successor provider-effect invocation"
        );
    }
}

async fn settle_failed_pre_provider_agent_successor(
    context: &mut AgentSuccessorLaunchContext,
    store: &Arc<tokio::sync::Mutex<Store>>,
    event_bus: &Arc<crate::bus::EventBus>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    permit: &crate::model_control::AdmissionPermit,
    reason: &str,
    safe_error_class: &str,
) -> Result<()> {
    let reservation = &context.reservation;
    let attempt_id = reservation.launch_attempt_id.ok_or_else(|| {
        DaemonError::Store(
            "agent successor pre-provider failure omitted launch attempt identity".into(),
        )
    })?;
    store
        .lock()
        .await
        .settle_agent_successor_establishment_failed(
            reservation.reservation_id,
            reservation.state_version,
            attempt_id,
            Uuid::new_v4(),
            reason,
            safe_error_class,
        )?;
    complete_invocation(
        store,
        permit,
        InvocationCompletion {
            error_class: Some(safe_error_class.to_string()),
            confidence: Some(ModelUsageConfidence::Unavailable),
            ..InvocationCompletion::default()
        },
        event_bus,
    )
    .await?;
    super::revoke_agent_tokens_for_session(agent_tokens, reservation.candidate_session_id).await;
    context.prospective_a6.clear().await;
    context.confirmation_tx.take();
    Ok(())
}

/// Terminally settle one failure after a fresh launch has committed its
/// Starting Session/invocation/custody boundary but before any provider may be
/// live.  Reservation-owned paths retain their own exact settlement contract;
/// generic direct launches use the common bound-launch failure transaction.
async fn settle_failed_bound_fresh_pre_provider(
    launch_purpose: &mut LaunchPurpose,
    store: &Arc<tokio::sync::Mutex<Store>>,
    event_bus: &Arc<crate::bus::EventBus>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    session_id: Uuid,
    permit: &crate::model_control::AdmissionPermit,
    reason: &str,
    safe_error_class: &str,
) -> Result<()> {
    match launch_purpose {
        LaunchPurpose::AgentSuccessor(context) => {
            return settle_failed_pre_provider_agent_successor(
                context,
                store,
                event_bus,
                agent_tokens,
                permit,
                reason,
                safe_error_class,
            )
            .await;
        }
        LaunchPurpose::AgentChild(context) => {
            store.lock().await.settle_post_bind_agent_child_failure(
                context.spawn_request_id,
                session_id,
                permit.invocation_id(),
                safe_error_class,
            )?;
        }
        LaunchPurpose::Interactive
        | LaunchPurpose::ManagerSuccessor(_)
        | LaunchPurpose::ManagerAction(_)
        | LaunchPurpose::TopologyNode(_)
        | LaunchPurpose::ControllerCandidate(_)
        | LaunchPurpose::ClosureSource(_) => {
            store
                .lock()
                .await
                .fail_bound_direct_launch(session_id, safe_error_class)?;
        }
    }
    complete_invocation(
        store,
        permit,
        InvocationCompletion {
            error_class: Some(safe_error_class.to_string()),
            confidence: Some(ModelUsageConfidence::Unavailable),
            ..InvocationCompletion::default()
        },
        event_bus,
    )
    .await?;
    Ok(())
}

/// Settle a final scratch revalidation failure after an AppServer launch has
/// published its exact in-memory incarnation but before any provider process
/// exists. The generation, invocation, and token fences prevent stale cleanup
/// from touching a replacement incarnation of the same logical Session.
async fn settle_failed_deferred_execution_scratch(
    active: &Arc<tokio::sync::RwLock<HashMap<Uuid, TrackedSession>>>,
    store: &Arc<tokio::sync::Mutex<Store>>,
    event_bus: &Arc<crate::bus::EventBus>,
    agent_tokens: &Arc<tokio::sync::RwLock<super::AgentTokenRegistry>>,
    custody_runtime: &crate::sandbox::custody::CustodyExecutionRuntime,
    session_id: Uuid,
    permit: &crate::model_control::AdmissionPermit,
    spawn_generation: u64,
    exact_token: &str,
    retry_bound: Option<&BoundRetryCustody>,
    agent_child: Option<&AgentChildLaunchContext>,
    mut controller: Option<&mut ControllerTransferLaunchContext>,
) {
    const SAFE_ERROR_CLASS: &str = "execution_scratch_unavailable";

    let old_status = {
        let mut active = active.write().await;
        let exact_incarnation = active
            .get(&session_id)
            .is_some_and(|tracked| tracked.spawn_generation == spawn_generation);
        let exact_invocation = store
            .lock()
            .await
            .session_model_invocation_id(session_id)
            .is_ok_and(|bound| bound == Some(permit.invocation_id()));
        if !exact_incarnation || !exact_invocation {
            return;
        }

        let settlement = if let Some(context) = agent_child {
            store.lock().await.settle_post_bind_agent_child_failure(
                context.spawn_request_id,
                session_id,
                permit.invocation_id(),
                SAFE_ERROR_CLASS,
            )
        } else if let Some(bound) = retry_bound {
            custody_runtime
                .settle_bound_retry_failure(
                    session_id,
                    bound,
                    SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                )
                .await
        } else {
            store
                .lock()
                .await
                .fail_bound_direct_launch(session_id, SAFE_ERROR_CLASS)
        };
        if let Err(error) = settlement {
            tracing::warn!(
                session_id = %session_id,
                error = %error,
                "failed exact deferred execution-scratch settlement"
            );
            return;
        }
        active
            .remove(&session_id)
            .map(|tracked| tracked.session.status)
            .unwrap_or(SessionStatus::Starting)
    };

    agent_tokens
        .write()
        .await
        .revoke_session_if_token(session_id, exact_token);
    if let Some(context) = controller.as_mut() {
        context.confirmation_tx.take();
        context.prospective_a6.clear().await;
    }
    if let Err(error) = complete_invocation(
        store,
        permit,
        InvocationCompletion {
            error_class: Some(SAFE_ERROR_CLASS.to_string()),
            confidence: Some(ModelUsageConfidence::Unavailable),
            ..InvocationCompletion::default()
        },
        event_bus,
    )
    .await
    {
        tracing::warn!(
            session_id = %session_id,
            error = %error,
            "failed deferred execution-scratch invocation settlement"
        );
    }
    event_bus.publish(DaemonEvent::SessionStatusChanged {
        session_id,
        old_status,
        new_status: SessionStatus::Failed,
    });
}

const fn controller_launch_error_reason(error: &DaemonError) -> ControllerReleaseReasonV1 {
    match error {
        DaemonError::PolicyDenied(_) => ControllerReleaseReasonV1::LaunchAdmissionFailed,
        DaemonError::Store(_) | DaemonError::Database(_) => {
            ControllerReleaseReasonV1::DurableRowFailed
        }
        DaemonError::ChannelClosed | DaemonError::CancellationCleanup(_) => {
            ControllerReleaseReasonV1::Cancelled
        }
        DaemonError::ClaudeBinaryNotFound
        | DaemonError::CodexBinaryNotFound
        | DaemonError::AgyBinaryNotFound
        | DaemonError::OpenAiApiError(_)
        | DaemonError::Process(_)
        | DaemonError::ExecutionScratchUnavailable(_)
        | DaemonError::StreamFallbackRequired(_) => ControllerReleaseReasonV1::ProviderSpawnFailed,
        _ => ControllerReleaseReasonV1::ConfirmationFailed,
    }
}

impl SessionManager {
    #[cfg(test)]
    pub(crate) fn fail_next_agent_successor_projection_for_test(&self, reservation_id: Uuid) {
        fail_next_agent_successor_projection(reservation_id);
    }

    #[cfg(test)]
    pub(crate) async fn preload_completed_session_for_test(&self, session_id: Uuid) -> Result<()> {
        let session = self
            .store
            .lock()
            .await
            .get_session(session_id)?
            .ok_or(DaemonError::SessionNotFound(session_id))?;
        self.completed.write().await.insert(
            session_id,
            CompletedSession {
                session,
                events: Vec::new(),
                turn_metrics: Vec::new(),
                retry_cancel: None,
                retry_fired_at: None,
                superseded_by_retry: None,
                events_hydrated: false,
            },
        );
        Ok(())
    }

    pub fn log_sandbox_build_cache_reclaim(
        _trigger: &'static str,
        _report: &SandboxBuildCacheReclaimReport,
    ) {
        // Compatibility shim for the periodic caller in `main.rs`.  Lifecycle
        // logging now occurs inside the coordinator-owned transition so this
        // post-return hook must not emit a second out-of-lease completion.
    }

    /// Launch, confirm, and assign one deterministic controller candidate.
    /// Ordinary interactive launch never enters this path or awaits its
    /// provider/durable-row confirmation.
    pub(super) async fn launch_confirmed_controller_candidate(
        &self,
        mut config: LaunchConfig,
        transfer: &crate::idea_control::IdeaControllerTransferHandle,
        reservation: IdeaControllerReservationV1,
        retry_admission: Option<super::types::RetryAdmission>,
        preheld_cwd_admission: Option<super::spawn_single_flight::ProviderCwdAdmissionGuard>,
    ) -> Result<IdeaControllerControlResultV1> {
        let prospective_a6 = ProspectiveAgentTokenWitness::default();
        let (confirmation_tx, confirmation_rx) = tokio::sync::oneshot::channel();
        config.project_id = Some(transfer.project_id());
        let purpose =
            LaunchPurpose::ControllerCandidate(Box::new(ControllerTransferLaunchContext {
                project_id: transfer.project_id(),
                idea_id: transfer.idea_id(),
                reservation: reservation.clone(),
                prospective_a6: prospective_a6.clone(),
                confirmation_tx: Some(confirmation_tx),
            }));
        if let Err(error) = self
            .launch_session_with_retry_admission(
                config,
                retry_admission,
                false,
                purpose,
                preheld_cwd_admission,
            )
            .await
        {
            self.cleanup_failed_controller_candidate(
                transfer,
                &reservation,
                &prospective_a6,
                controller_launch_error_reason(&error),
            )
            .await;
            return Err(error);
        }

        let remaining = (reservation.expires_at - chrono::Utc::now())
            .to_std()
            .unwrap_or_default();
        let Ok(Ok(confirmation)) = tokio::time::timeout(remaining, confirmation_rx).await else {
            let reason = if self
                .active
                .read()
                .await
                .get(&reservation.candidate_session_id)
                .is_some_and(|tracked| tracked.interrupt_requested)
            {
                ControllerReleaseReasonV1::Cancelled
            } else {
                ControllerReleaseReasonV1::ConfirmationFailed
            };
            self.cleanup_failed_controller_candidate(
                transfer,
                &reservation,
                &prospective_a6,
                reason,
            )
            .await;
            return Err(DaemonError::Process(
                "controller candidate confirmation failed".to_string(),
            ));
        };
        #[cfg(test)]
        pause_controller_candidate_test(
            reservation.candidate_session_id,
            ControllerCandidateTestPhase::AfterConfirmation,
        )
        .await;
        let Some(token) = prospective_a6.current_token().await else {
            self.cleanup_failed_controller_candidate(
                transfer,
                &reservation,
                &prospective_a6,
                ControllerReleaseReasonV1::TokenMintFailed,
            )
            .await;
            return Err(DaemonError::Process(
                "controller candidate A6 witness is unavailable".to_string(),
            ));
        };
        #[cfg(test)]
        pause_controller_candidate_test(
            reservation.candidate_session_id,
            ControllerCandidateTestPhase::BeforeAssignment,
        )
        .await;
        let assigned = match Self::assign_live_controller_candidate(
            &self.active,
            transfer,
            &reservation,
            &confirmation,
            &token,
            &self.agent_tokens,
        )
        .await
        {
            Ok(result) => result,
            Err(super::ControllerCandidateCommitError::Cancelled) => {
                self.cleanup_failed_controller_candidate(
                    transfer,
                    &reservation,
                    &prospective_a6,
                    ControllerReleaseReasonV1::Cancelled,
                )
                .await;
                return Err(DaemonError::Process(
                    "controller candidate was interrupted before assignment".to_string(),
                ));
            }
            Err(super::ControllerCandidateCommitError::Confirmation(error)) => {
                self.cleanup_failed_controller_candidate(
                    transfer,
                    &reservation,
                    &prospective_a6,
                    ControllerReleaseReasonV1::ConfirmationFailed,
                )
                .await;
                return Err(DaemonError::Store(error.to_string()));
            }
        };
        self.event_bus.publish(DaemonEvent::SystemMessage {
            level: "info".to_string(),
            message: format!("idea_controller_assigned:{}", assigned.event.id),
        });
        if let Some(former) = reservation.base_controller_session_id {
            self.revoke_agent_token_for_session(former).await;
        }
        prospective_a6.clear().await;
        Ok(assigned)
    }

    async fn cleanup_failed_controller_candidate(
        &self,
        transfer: &crate::idea_control::IdeaControllerTransferHandle,
        reservation: &IdeaControllerReservationV1,
        prospective_a6: &ProspectiveAgentTokenWitness,
        reason: ControllerReleaseReasonV1,
    ) {
        let retry_bound = self
            .store
            .lock()
            .await
            .bound_retry_successor_custody(reservation.candidate_session_id)
            .ok()
            .flatten();
        let mut terminal_events = retry_bound.map(|_| self.event_bus.subscribe());
        let _ = self
            .interrupt_session(reservation.candidate_session_id)
            .await;
        #[cfg(test)]
        if retry_bound.is_some() {
            drop_controller_candidate_test_stream(reservation.candidate_session_id);
        }
        if let Some(events) = terminal_events.as_mut()
            && self
                .active
                .read()
                .await
                .contains_key(&reservation.candidate_session_id)
        {
            let candidate_id = reservation.candidate_session_id;
            let _ = tokio::time::timeout(super::SessionManager::CONTINUE_INTERRUPT_WAIT, async {
                loop {
                    match events.recv().await {
                        Ok(event)
                            if matches!(
                                event.as_ref(),
                                DaemonEvent::SessionStatusChanged { session_id, new_status, .. }
                                    if *session_id == candidate_id
                                        && matches!(new_status, SessionStatus::Completed | SessionStatus::Interrupted | SessionStatus::Failed)
                            ) => break,
                        Ok(_) => {}
                        Err(_) => break,
                    }
                }
            })
            .await;
        }
        if terminal_events.is_some() {
            self.event_bus.unsubscribe();
        }
        if let Some(bound) = retry_bound {
            if let Err(error) = self.persistence.barrier().await {
                tracing::warn!(
                    session_id = %reservation.candidate_session_id,
                    error = %error,
                    "retry controller cleanup persistence barrier failed"
                );
            }
            if let Err(error) = self.store.lock().await.fail_established_retry_successor(
                reservation.candidate_session_id,
                bound,
                SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
            ) {
                tracing::warn!(
                    session_id = %reservation.candidate_session_id,
                    error = %error,
                    "retry controller cleanup failed to settle bound successor"
                );
            }
        }
        self.revoke_agent_token_for_session(reservation.candidate_session_id)
            .await;
        self.store
            .lock()
            .await
            .remove_controller_grant_v1(reservation.candidate_session_id);
        prospective_a6.clear().await;
        let _ = transfer
            .release_reservation(&ReleaseIdeaControllerReservationRequestV1 {
                transfer_intent_key: reservation.transfer_intent_key.clone(),
                reason,
            })
            .await;
    }

    /// Launch a session for recursive DAG live execution and return only after
    /// the session row is durably present and loadable through the store path.
    ///
    /// Direct interactive launches persist before any provider effect. This
    /// adapter retains its stricter attach contract for the separate
    /// recursive-live producer: a successful return means the session id is
    /// safe to store in `recursive_live_attempts`.
    pub(crate) async fn launch_session_with_durable_store_row(
        &self,
        config: LaunchConfig,
    ) -> Result<Uuid> {
        let session_id = self.launch_session(config).await?;
        self.wait_for_durable_session_row(session_id).await?;
        Ok(session_id)
    }

    /// Return the daemon store handle for the disabled recursive DAG live
    /// binding. This is not a reachability gate; it only lets the internal
    /// factory build a driver that shares the same store as `SessionManager`.
    pub(crate) fn recursive_dag_live_store_handle(
        &self,
    ) -> Arc<tokio::sync::Mutex<crate::store::Store>> {
        Arc::clone(&self.store)
    }

    pub async fn commit_recoverable_recursive_live_outputs_after_restart(
        &self,
        budget: RecursiveRecoveryBudget,
    ) -> Result<(usize, usize, usize)> {
        crate::recursive_dag::live::commit_recoverable_completed_live_attempt_outputs_after_restart(
            self.recursive_dag_live_store_handle(),
            self,
            budget,
        )
        .await
    }

    async fn wait_for_durable_session_row(&self, session_id: Uuid) -> Result<()> {
        self.wait_for_durable_session_row_with_budget(
            session_id,
            RECURSIVE_DAG_LIVE_SESSION_PERSISTENCE_TIMEOUT,
            RECURSIVE_DAG_LIVE_SESSION_PERSISTENCE_POLL_INTERVAL,
        )
        .await
    }

    async fn wait_for_durable_session_row_with_budget(
        &self,
        session_id: Uuid,
        timeout: Duration,
        poll_interval: Duration,
    ) -> Result<()> {
        let started_at = Instant::now();
        loop {
            let check = self.check_durable_session_row(session_id).await?;
            if check == DurableSessionRowCheck::Present {
                return Ok(());
            }

            let elapsed = started_at.elapsed();
            if elapsed >= timeout {
                let last_check = match check {
                    DurableSessionRowCheck::Present => "present",
                    DurableSessionRowCheck::Missing => "session row missing",
                    DurableSessionRowCheck::StoreBusy => "store busy",
                };
                return Err(DaemonError::Store(format!(
                    "recursive DAG live launch contract violated: session {session_id} did not become durably persisted and loadable before attach within {timeout:?}; last check: {last_check}"
                )));
            }

            let sleep_for = std::cmp::min(poll_interval, timeout.saturating_sub(elapsed));
            if sleep_for.is_zero() {
                tokio::task::yield_now().await;
            } else {
                tokio::time::sleep(sleep_for).await;
            }
        }
    }

    async fn check_durable_session_row(&self, session_id: Uuid) -> Result<DurableSessionRowCheck> {
        let store = Arc::clone(&self.store);
        tokio::task::spawn_blocking(move || {
            let Ok(store) = store.try_lock() else {
                return Ok(DurableSessionRowCheck::StoreBusy);
            };
            store
                .get_session(session_id)
                .map(|session| {
                    if session.is_some() {
                        DurableSessionRowCheck::Present
                    } else {
                        DurableSessionRowCheck::Missing
                    }
                })
                .map_err(|error| {
                    DaemonError::Store(format!(
                        "failed to load session {session_id} while verifying recursive DAG live launch persistence: {error}"
                    ))
                })
        })
        .await
        .map_err(|error| {
            DaemonError::Store(format!(
                "session persistence verification task failed for {session_id}: {error}"
            ))
        })?
    }

    /// Launch a new Claude session.
    ///
    /// Returns immediately after spawning the Claude process and inserting into
    /// the active map. DB persistence, project resolution, user event creation,
    /// and session monitoring run in a background task to avoid blocking the
    /// RPC response (and thus the TUI's event loop).
    pub async fn launch_session(&self, config: LaunchConfig) -> Result<Uuid> {
        self.launch_session_with_retry_admission(
            config,
            None,
            false,
            LaunchPurpose::Interactive,
            None,
        )
        .await
    }

    pub(crate) async fn launch_reserved_closure_source(
        &self,
        config: LaunchConfig,
        session_id: Uuid,
        custody_id: Uuid,
    ) -> Result<Uuid> {
        self.launch_session_with_retry_admission(
            config,
            None,
            false,
            LaunchPurpose::ClosureSource(super::types::ClosureSourceLaunchContext {
                session_id,
                custody_id,
            }),
            None,
        )
        .await
    }

    /// Launch one preallocated, durably identified agent child.
    pub async fn launch_agent_child(
        &self,
        request: super::spawn_coordinator::SpawnRequest,
    ) -> Result<Uuid> {
        // Exact durable replay: a request that already settled `launched`
        // with its durable child row returns the original ids and performs
        // no re-authentication, no second allocation, and no state change.
        {
            let store = self.store.lock().await;
            if store
                .get_agent_spawn_request(request.spawn_request_id)?
                .is_some_and(|record| {
                    record.state == rsi_common::agent_coordination::AgentSpawnStateV1::Launched
                        && record.child_session_id == request.child_session_id
                })
                && store.get_session(request.child_session_id)?.is_some()
            {
                return Ok(request.child_session_id);
            }
        }
        let cwd_admission_guard =
            super::spawn_single_flight::acquire_provider_cwd_admission().await;
        if self
            .store
            .lock()
            .await
            .session_or_custody_has_settlement_fence(request.owner_session_id)?
        {
            self.settle_agent_spawn_custody_refusal(
                &request,
                SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
            )
            .await;
            return Err(DaemonError::PolicyDenied(
                "source-worktree settlement journal fences this agent child spawn".into(),
            ));
        }
        // H1-04 (F-011): authenticate the emitter's custody and capture its
        // exact clean HEAD OID BEFORE any child-side effect (no spawn-state
        // transition, no allocation, no session row, no provider/context/
        // config/target work). A refusal settles the reserved spawn row and
        // the reserved child session id before returning.
        let fork = if request.config.sandbox.is_some() {
            let emitter_result = {
                let store = self.store.lock().await;
                store.get_session(request.owner_session_id)
            };
            let emitter = match emitter_result {
                Ok(Some(emitter)) => Some(emitter),
                Ok(None) => None,
                Err(error) => {
                    self.settle_agent_spawn_custody_refusal(
                        &request,
                        SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                    )
                    .await;
                    return Err(error);
                }
            };
            let Some(emitter) = emitter else {
                let refusal = CustodyService::refusal(
                    SandboxCustodyErrorCodeV1::OwnershipMissing,
                    Some(request.owner_session_id),
                    rsi_common::types::SandboxCustodyTransitionV1::AgentSpawnChild,
                );
                self.settle_agent_spawn_custody_refusal(
                    &request,
                    SandboxCustodyErrorCodeV1::OwnershipMissing,
                )
                .await;
                return Err(refusal);
            };
            match self
                .custody_execution_runtime()
                .prepare_spawn_fork(&emitter)
                .await
            {
                Ok(candidate) => Some(candidate),
                Err(error) => {
                    let code = crate::sandbox::custody::custody_error_code(&error)
                        .unwrap_or(SandboxCustodyErrorCodeV1::PersistenceTransitionFailed);
                    self.settle_agent_spawn_custody_refusal(&request, code)
                        .await;
                    return Err(error);
                }
            }
        } else {
            None
        };
        let context = AgentChildLaunchContext {
            spawn_request_id: request.spawn_request_id,
            child_session_id: request.child_session_id,
            owner_session_id: request.owner_session_id,
            fork,
        };
        self.store
            .lock()
            .await
            .mark_agent_spawn_launching(request.spawn_request_id)?;
        let config_for_settlement = request.config.clone();
        let result = self
            .launch_session_with_retry_admission(
                request.config,
                None,
                false,
                LaunchPurpose::AgentChild(context),
                Some(cwd_admission_guard),
            )
            .await;
        match result {
            Ok(child_session_id) => {
                tracing::info!(
                    target: "agent_coordination",
                    spawn_request_id = %request.spawn_request_id,
                    child_session_id = %child_session_id,
                    settlement = "launched",
                    "agent child spawn settled"
                );
                if let Err(error) = self
                    .agent_control()
                    .arm_automatic_child_watch(request.owner_session_id, child_session_id)
                    .await
                {
                    tracing::warn!(target: "agent_coordination", spawn_request_id = %request.spawn_request_id, child_session_id = %child_session_id, error = %error, "automatic terminal watch arm deferred to reconciliation");
                }
                Ok(child_session_id)
            }
            Err(error) => {
                if let Some(failed) = self
                    .store
                    .lock()
                    .await
                    .get_agent_spawn_request(request.spawn_request_id)?
                    .filter(|record| {
                        record.state == rsi_common::agent_coordination::AgentSpawnStateV1::Failed
                    })
                {
                    tracing::warn!(
                        target: "agent_coordination",
                        spawn_request_id = %request.spawn_request_id,
                        child_session_id = %request.child_session_id,
                        settlement = "failed",
                        safe_error_class = ?failed.safe_error_class,
                        "agent child spawn already received exact post-bind settlement"
                    );
                    return Err(error);
                }
                // H1-04 (F-011): a custody-classified launch failure
                // (allocation, custody bind/persistence) settles with its
                // bounded sandbox_custody code and a durable Failed child
                // row; every other launch failure keeps the accepted generic
                // spawn settlement.
                if let Some(code) = crate::sandbox::custody::custody_error_code(&error) {
                    let child = failed_agent_spawn_child_session(
                        &config_for_settlement,
                        request.child_session_id,
                        code,
                    );
                    tracing::warn!(
                        target: "agent_coordination",
                        spawn_request_id = %request.spawn_request_id,
                        child_session_id = %request.child_session_id,
                        settlement = "failed",
                        safe_error_class = %format!("sandbox_custody.{}", code.as_str()),
                        "agent child spawn settled"
                    );
                    if let Err(settle_error) = self
                        .custody_execution_runtime()
                        .settle_agent_spawn_custody_failure(request.spawn_request_id, &child, code)
                        .await
                    {
                        tracing::error!(target: "agent_coordination", spawn_request_id = %request.spawn_request_id, error = %settle_error, "failed to settle agent child custody launch failure");
                        if let Err(fallback_error) = self
                            .store
                            .lock()
                            .await
                            .mark_agent_spawn_failed(request.spawn_request_id, "launch_failed")
                        {
                            tracing::error!(target: "agent_coordination", spawn_request_id = %request.spawn_request_id, error = %fallback_error, "failed to settle agent child launch failure");
                        }
                    }
                    return Err(error);
                }
                tracing::warn!(
                    target: "agent_coordination",
                    spawn_request_id = %request.spawn_request_id,
                    child_session_id = %request.child_session_id,
                    settlement = "failed",
                    safe_error_class = "launch_failed",
                    "agent child spawn settled"
                );
                if let Err(settle_error) = self
                    .store
                    .lock()
                    .await
                    .mark_agent_spawn_failed(request.spawn_request_id, "launch_failed")
                {
                    tracing::error!(target: "agent_coordination", spawn_request_id = %request.spawn_request_id, error = %settle_error, "failed to settle agent child launch failure");
                }
                Err(error)
            }
        }
    }

    fn agent_successor_launch_config(
        reservation: &crate::store::successor_reservations::AgentSuccessorReservation,
    ) -> Result<LaunchConfig> {
        let frozen = reservation.inherited_launch()?;
        let provider = frozen.provider()?;
        let invocation_id = reservation.model_invocation_id.ok_or_else(|| {
            DaemonError::Store("launching successor lacks invocation identity".into())
        })?;
        let sandbox_kind = match frozen.sandbox_kind.as_deref() {
            Some("GitWorktree") | Some("None") | None => SandboxKind::GitWorktree,
            Some(other) => {
                return Err(DaemonError::Store(format!(
                    "agent successor frozen sandbox kind is invalid: {other}"
                )));
            }
        };
        let sandbox = Some(rsi_common::types::SandboxSpec {
            kind: Some(sandbox_kind),
            branch: None,
        });
        Ok(LaunchConfig {
            query: reservation.request.query.clone(),
            title: None,
            agent_role: frozen.agent_role.clone(),
            epic_spawn_ordinal: frozen.epic_spawn_ordinal,
            working_dir: Some(std::path::PathBuf::from(frozen.working_dir)),
            provider: Some(provider),
            model: reservation.request.model.clone().or(frozen.model),
            configured_context_window: None,
            max_turns: None,
            system_prompt: None,
            resume_session_id: None,
            session_kind: Some(reservation.candidate_kind),
            project_id: frozen.project_id,
            rsi_session_id: Some(reservation.candidate_session_id),
            rsi_socket: None,
            rsi_session_token: None,
            continued_from: Some(reservation.predecessor_session_id),
            openai_base_url: None,
            openai_api_key: None,
            conversation_history: None,
            workflow_id: frozen.workflow_id,
            workflow_id_override: None,
            max_retries: None,
            group_id: None,
            parent_id: Some(reservation.epic_id),
            effort: reservation.request.effort.clone().or(frozen.effort),
            issue_identifier: None,
            issue_url: None,
            issue_tracker_id: None,
            scheduled_job_id: None,
            model_invocation_owner: None,
            model_invocation_dedup_key: Some(format!(
                "agent:reserve:successor:{}:{invocation_id}",
                reservation.reservation_id
            )),
            model_invocation_request_fingerprint: Some(reservation.request_fingerprint.clone()),
            // The reservation freezes the effective provider/model witness.
            // A later project-default edit must not rewrite an exact replay.
            skip_project_model_default: true,
            model_invocation_purpose:
                rsi_common::model_control::ModelInvocationPurpose::AgentReserveSuccessor,
            sandbox,
            cargo_target_dir: None,
            execution_scratch: None,
            is_eval: frozen.is_eval,
            skip_context_pipeline: frozen.is_eval,
            capability_class: None,
            tags: reservation.request.tags.clone().unwrap_or(frozen.tags),
            topology_node_id: reservation.request.topology_node.clone(),
            topology_iteration: reservation.request.iteration.unwrap_or(0),
            closure_selector: None,
        })
    }

    async fn launch_confirmed_agent_successor_candidate(
        &self,
        reservation: crate::store::successor_reservations::AgentSuccessorReservation,
    ) -> Result<AgentSuccessorLaunchConfirmation> {
        let config = Self::agent_successor_launch_config(&reservation)?;
        let prospective_a6 = ProspectiveAgentTokenWitness::default();
        let (confirmation_tx, confirmation_rx) = tokio::sync::oneshot::channel();
        let purpose = LaunchPurpose::AgentSuccessor(Box::new(AgentSuccessorLaunchContext {
            reservation,
            prospective_a6,
            confirmation_tx: Some(confirmation_tx),
        }));
        self.launch_session_with_retry_admission(config, None, false, purpose, None)
            .await?;
        tokio::time::timeout(Duration::from_secs(60), confirmation_rx)
            .await
            .map_err(|_| DaemonError::Process("successor provider establishment timed out".into()))?
            .map_err(|_| {
                DaemonError::Process("successor provider establishment was not confirmed".into())
            })
    }

    async fn current_agent_successor_confirmation(
        &self,
        reservation: &crate::store::successor_reservations::AgentSuccessorReservation,
    ) -> Result<AgentSuccessorLaunchConfirmation> {
        let provider = reservation.inherited_launch()?.provider()?;
        let invocation_id = reservation.model_invocation_id.ok_or_else(|| {
            DaemonError::Store("launching successor lacks invocation identity".into())
        })?;
        let mut active = self.active.write().await;
        let tracked = active
            .get_mut(&reservation.candidate_session_id)
            .ok_or_else(|| DaemonError::Process("successor candidate is not active".into()))?;
        let confirmation_kind = tracked
            .process
            .as_mut()
            .and_then(|process| {
                super::provider_spawn::installed_provider_confirmation(provider, process)
            })
            .ok_or_else(|| DaemonError::Process("successor provider is not established".into()))?;
        Ok(AgentSuccessorLaunchConfirmation {
            candidate_session_id: reservation.candidate_session_id,
            provider,
            admission_invocation_id: invocation_id,
            confirmation_kind,
        })
    }

    async fn commit_live_agent_successor(
        &self,
        reservation: &crate::store::successor_reservations::AgentSuccessorReservation,
        confirmation: AgentSuccessorLaunchConfirmation,
        attempt_id: Uuid,
    ) -> Result<crate::store::successor_reservations::AgentSuccessorReservation> {
        #[cfg(test)]
        pause_controller_candidate_test(
            reservation.candidate_session_id,
            ControllerCandidateTestPhase::BeforeAssignment,
        )
        .await;
        // K2 authority gate: the commit moves the Epic lead from the
        // predecessor to the candidate, so it holds both spawn guards in the
        // global order before the active map and store locks. A fenced
        // continuation of the predecessor either completed before this commit
        // or observes the new lead generation under its guard.
        let _lead_guards = super::hierarchy_ops::lead_mutation_guards(
            &[
                reservation.predecessor_session_id,
                reservation.candidate_session_id,
            ],
            super::hierarchy_ops::LeadGuardMode::Acquire,
        )
        .await?;
        let mut active = self.active.write().await;
        let tracked = active
            .get_mut(&reservation.candidate_session_id)
            .ok_or_else(|| DaemonError::Process("successor candidate is not active".into()))?;
        let exact_provider = tracked.process.as_mut().is_some_and(|process| {
            super::provider_spawn::matches_live_controller_confirmation(
                confirmation.provider,
                confirmation.confirmation_kind,
                process,
            )
        });
        if tracked.interrupt_requested
            || tracked.session.id != confirmation.candidate_session_id
            || tracked.session.provider != confirmation.provider
            || tracked.session.parent_id != Some(reservation.epic_id)
            || tracked.session.continued_from != Some(reservation.predecessor_session_id)
            || !matches!(
                tracked.session.status,
                SessionStatus::Starting | SessionStatus::Running | SessionStatus::WaitingApproval
            )
            || confirmation.admission_invocation_id
                != reservation.model_invocation_id.unwrap_or_default()
            || !exact_provider
        {
            return Err(DaemonError::Process(
                "successor live provider witness changed before commit".into(),
            ));
        }
        let store = self.store.lock().await;
        let a6 = self.agent_tokens.read().await;
        if a6
            .token_for_session(reservation.candidate_session_id)
            .is_none()
        {
            return Err(DaemonError::Process(
                "successor A6 witness changed before commit".into(),
            ));
        }
        let evidence = serde_json::json!({
            "provider": format!("{:?}", confirmation.provider),
            "confirmation": confirmation.confirmation_kind,
            "candidate_session_id": confirmation.candidate_session_id,
            "model_invocation_id": confirmation.admission_invocation_id,
        });
        let committed = store.commit_agent_successor_authority(
            reservation.reservation_id,
            reservation.state_version,
            attempt_id,
            Uuid::new_v4(),
            &evidence,
        )?;
        drop(a6);
        drop(store);
        drop(active);
        Ok(committed)
    }

    /// Acknowledge one successful durable baton transfer in the runtime
    /// authority projection. The Store commit is irreversible here: if its
    /// exact Epic row cannot be projected, the predecessor token remains live
    /// and the process-local retry set lets the bounded reconciler converge.
    async fn acknowledge_committed_agent_successor(
        &self,
        committed: &crate::store::successor_reservations::AgentSuccessorReservation,
    ) -> Result<()> {
        self.successor_projection_pending
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(committed.reservation_id);

        #[cfg(test)]
        if take_agent_successor_projection_failure(committed.reservation_id) {
            return Err(DaemonError::Store(format!(
                "injected agent successor projection publication failure:{}",
                committed.reservation_id
            )));
        }

        let persisted_epic = self
            .store
            .lock()
            .await
            .get_session(committed.epic_id)?
            .ok_or(DaemonError::SessionNotFound(committed.epic_id))?;
        if persisted_epic.session_kind != SessionKind::Epic {
            return Err(DaemonError::Store(format!(
                "committed agent successor Epic projection is not an Epic:{}",
                committed.epic_id
            )));
        }

        // Replace every resident copy, not just its lead field. `active` wins
        // map-first reads today, but updating both prevents a later active-map
        // removal from revealing an older completed snapshot.
        if let Some(tracked) = self.active.write().await.get_mut(&committed.epic_id) {
            tracked.session = persisted_epic.clone();
        }
        if let Some(completed) = self.completed.write().await.get_mut(&committed.epic_id) {
            completed.session = persisted_epic.clone();
        }

        self.publish_lead_delta(committed.epic_id, persisted_epic.lead_session_id);
        self.revoke_agent_token_for_session(committed.predecessor_session_id)
            .await;
        self.event_bus.publish(DaemonEvent::SystemMessage {
            level: "info".to_string(),
            message: format!(
                "agent_successor_committed:{}:{}",
                committed.reservation_id, committed.candidate_session_id
            ),
        });
        self.successor_projection_pending
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&committed.reservation_id);

        // The durable commit made the candidate this Epic's lead, so it earns
        // the same marks an ordinary promotion applies. The condition reads the
        // PERSISTED row, never the reservation, so a raced or repaired lead
        // pointer cannot mark a session the Store does not name. Last in the
        // function on purpose: the authority sequence above — projection, lead
        // delta, predecessor revocation — must not be delayed by cosmetics.
        if persisted_epic.lead_session_id == Some(committed.candidate_session_id) {
            self.mark_lead_session(committed.candidate_session_id).await;
        }
        Ok(())
    }

    async fn cleanup_failed_agent_successor(&self, candidate_session_id: Uuid) {
        let mut events = self.event_bus.subscribe();
        let _ = self.interrupt_session(candidate_session_id).await;
        if self.active.read().await.contains_key(&candidate_session_id) {
            let _ = tokio::time::timeout(Self::CONTINUE_INTERRUPT_WAIT, async {
                loop {
                    match events.recv().await {
                        Ok(event)
                            if matches!(
                                event.as_ref(),
                                DaemonEvent::SessionStatusChanged { session_id, new_status, .. }
                                    if *session_id == candidate_session_id
                                        && matches!(
                                            new_status,
                                            SessionStatus::Completed
                                                | SessionStatus::Interrupted
                                                | SessionStatus::Failed
                                        )
                            ) =>
                        {
                            break;
                        }
                        Ok(_) => {}
                        Err(_) => break,
                    }
                }
            })
            .await;
        }
        self.event_bus.unsubscribe();
        self.revoke_agent_token_for_session(candidate_session_id)
            .await;
    }

    /// Reconcile one durable master-successor reservation. Every entry reads
    /// the row again; the bounded channel and startup scan are hints only.
    pub async fn reconcile_agent_successor(&self, reservation_id: Uuid) -> Result<()> {
        use crate::store::successor_reservations::{
            AgentSuccessorLaunchIds, ClaimAgentSuccessorOutcome,
        };
        use rsi_common::agent_coordination::AgentSuccessorStateV1;

        let mut reservation = self
            .store
            .lock()
            .await
            .get_agent_successor(reservation_id)?
            .ok_or_else(|| {
                DaemonError::InvalidParam(format!("agent_successor_unknown:{reservation_id}"))
            })?;
        if reservation.state == AgentSuccessorStateV1::Committed {
            return self
                .acknowledge_committed_agent_successor(&reservation)
                .await;
        }
        if reservation.state.is_terminal() {
            return Ok(());
        }
        if reservation.state == AgentSuccessorStateV1::Reserved {
            let claimed = self.store.lock().await.claim_agent_successor_launch(
                reservation_id,
                reservation.state_version,
                AgentSuccessorLaunchIds {
                    launch_attempt_id: Uuid::new_v4(),
                    model_invocation_id: Uuid::new_v4(),
                    transition_id: Uuid::new_v4(),
                },
            )?;
            reservation = match claimed {
                ClaimAgentSuccessorOutcome::Claimed(record) => record,
                ClaimAgentSuccessorOutcome::NotReady(_) | ClaimAgentSuccessorOutcome::Stale(_) => {
                    return Ok(());
                }
            };
        }

        let attempt_id = reservation.launch_attempt_id.ok_or_else(|| {
            DaemonError::Store("launching successor lacks attempt identity".into())
        })?;
        let invocation_id = reservation.model_invocation_id.ok_or_else(|| {
            DaemonError::Store("launching successor lacks invocation identity".into())
        })?;
        let candidate_is_active = self
            .active
            .read()
            .await
            .contains_key(&reservation.candidate_session_id);
        if !candidate_is_active {
            // A durable candidate with no installed provider handle is a
            // definite post-restart loss, not permission to allocate a second
            // session or invocation. `restore_sessions` settles pre-crash
            // Starting/Running rows before startup successor reconciliation.
            // Fail the reservation and leave the predecessor lead untouched.
            if self
                .store
                .lock()
                .await
                .get_session(reservation.candidate_session_id)?
                .is_some()
            {
                self.store
                    .lock()
                    .await
                    .settle_agent_successor_establishment_failed(
                        reservation_id,
                        reservation.state_version,
                        attempt_id,
                        Uuid::new_v4(),
                        "durable successor candidate has no live provider after reconciliation",
                        "agent_successor_provider_not_restorable",
                    )?;
                self.revoke_agent_token_for_session(reservation.candidate_session_id)
                    .await;
                if let Err(error) = complete_invocation_by_id(
                    &self.store,
                    invocation_id,
                    InvocationCompletion {
                        error_class: Some("agent_successor_provider_not_restorable".into()),
                        confidence: Some(ModelUsageConfidence::Unavailable),
                        ..InvocationCompletion::default()
                    },
                    self.event_bus(),
                )
                .await
                {
                    tracing::warn!(
                        reservation_id = %reservation_id,
                        candidate_session_id = %reservation.candidate_session_id,
                        invocation_id = %invocation_id,
                        error = %error,
                        "Failed to settle non-restorable successor model invocation"
                    );
                }
                return Ok(());
            }

            let confirmation = match self
                .launch_confirmed_agent_successor_candidate(reservation.clone())
                .await
            {
                Ok(confirmation) => confirmation,
                Err(error) => {
                    return Err(Box::pin(self.settle_agent_successor_launch_failure(
                        reservation_id,
                        attempt_id,
                        error,
                    ))
                    .await);
                }
            };
            let committed = match self
                .commit_live_agent_successor(&reservation, confirmation, attempt_id)
                .await
            {
                Ok(committed) => committed,
                Err(error) => {
                    if error
                        .to_string()
                        .contains("agent_successor_authority_stale")
                    {
                        self.cleanup_failed_agent_successor(reservation.candidate_session_id)
                            .await;
                    }
                    return Err(error);
                }
            };
            return self.acknowledge_committed_agent_successor(&committed).await;
        }
        let confirmation = self
            .current_agent_successor_confirmation(&reservation)
            .await?;
        let committed = match self
            .commit_live_agent_successor(&reservation, confirmation, attempt_id)
            .await
        {
            Ok(committed) => committed,
            Err(error) => {
                if error
                    .to_string()
                    .contains("agent_successor_authority_stale")
                {
                    self.cleanup_failed_agent_successor(reservation.candidate_session_id)
                        .await;
                }
                return Err(error);
            }
        };
        self.acknowledge_committed_agent_successor(&committed).await
    }

    pub async fn reconcile_incomplete_agent_successors(
        &self,
    ) -> Result<AgentSuccessorReconcilePass> {
        self.reconcile_incomplete_agent_successors_with_budget(
            AGENT_SUCCESSOR_PERIODIC_RECONCILE_BUDGET,
        )
        .await
    }

    pub async fn reconcile_incomplete_agent_successors_at_startup(
        &self,
    ) -> Result<AgentSuccessorReconcilePass> {
        self.reconcile_incomplete_agent_successors_with_budget(
            AGENT_SUCCESSOR_STARTUP_RECONCILE_BUDGET,
        )
        .await
    }

    async fn reconcile_incomplete_agent_successors_with_budget(
        &self,
        budget: AgentSuccessorReconcileBudget,
    ) -> Result<AgentSuccessorReconcilePass> {
        use super::spawn_coordinator::SuccessorDispatchOutcome;
        use crate::store::successor_reservations::AgentSuccessorCursor;

        let started = Instant::now();
        let mut outcome = AgentSuccessorReconcilePass::default();
        let mut cursor = self.successor_reconcile_cursor.lock().await;

        let projection_pending: Vec<_> = self
            .successor_projection_pending
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .iter()
            .copied()
            .take(budget.row_limit)
            .collect();
        for reservation_id in projection_pending {
            if outcome.rows_scanned >= budget.row_limit || started.elapsed() >= budget.time_limit {
                return Ok(outcome);
            }
            outcome.rows_scanned += 1;
            match self
                .spawn_coordinator
                .dispatch_successor(reservation_id)
                .await
            {
                Ok(SuccessorDispatchOutcome::Queued) => outcome.queued += 1,
                Ok(SuccessorDispatchOutcome::AlreadyPending) => {
                    outcome.already_pending += 1;
                }
                Err(_) => {
                    outcome.dispatch_saturated = true;
                    return Ok(outcome);
                }
            }
        }

        'pages: while outcome.rows_scanned < budget.row_limit
            && outcome.pages_scanned < budget.page_limit
            && started.elapsed() < budget.time_limit
        {
            let remaining_rows = budget.row_limit - outcome.rows_scanned;
            let fetch_limit = budget.page_size.min(remaining_rows);
            if fetch_limit == 0 {
                break;
            }
            let page = self
                .store
                .lock()
                .await
                .list_reconcilable_agent_successors(*cursor, fetch_limit)?;
            outcome.pages_scanned += 1;
            if page.reservations.is_empty() {
                *cursor = None;
                outcome.ledger_exhausted = true;
                break;
            }
            for reservation in page.reservations {
                if outcome.rows_scanned >= budget.row_limit
                    || started.elapsed() >= budget.time_limit
                {
                    break 'pages;
                }
                *cursor = Some(AgentSuccessorCursor {
                    updated_at: reservation.updated_at,
                    reservation_id: reservation.reservation_id,
                });
                outcome.rows_scanned += 1;
                match self
                    .spawn_coordinator
                    .dispatch_successor(reservation.reservation_id)
                    .await
                {
                    Ok(SuccessorDispatchOutcome::Queued) => outcome.queued += 1,
                    Ok(SuccessorDispatchOutcome::AlreadyPending) => {
                        outcome.already_pending += 1;
                    }
                    Err(_) => {
                        outcome.dispatch_saturated = true;
                        break 'pages;
                    }
                }
            }
            if page.next_cursor.is_none() {
                *cursor = None;
                outcome.ledger_exhausted = true;
                break;
            }
        }
        Ok(outcome)
    }

    pub async fn reconcile_agent_successors_for_predecessor(
        &self,
        predecessor_session_id: Uuid,
    ) -> Result<()> {
        let reservations = self
            .store
            .lock()
            .await
            .find_agent_successors_by_predecessor(predecessor_session_id)?;
        for reservation in reservations {
            if !reservation.state.is_terminal() {
                self.spawn_coordinator
                    .dispatch_successor(reservation.reservation_id)
                    .await
                    .map_err(DaemonError::Store)?;
            }
        }
        Ok(())
    }

    /// H1-04 (F-011): settle a pre-launch AgentSpawnChild custody refusal.
    /// Best-effort by construction — the refusal error itself is what the
    /// caller returns; a settlement failure is logged, never masked.
    async fn settle_agent_spawn_custody_refusal(
        &self,
        request: &super::spawn_coordinator::SpawnRequest,
        code: SandboxCustodyErrorCodeV1,
    ) {
        let child =
            failed_agent_spawn_child_session(&request.config, request.child_session_id, code);
        tracing::warn!(
            target: "agent_coordination",
            spawn_request_id = %request.spawn_request_id,
            child_session_id = %request.child_session_id,
            settlement = "failed",
            safe_error_class = %format!("sandbox_custody.{}", code.as_str()),
            "agent child spawn settled"
        );
        if let Err(error) = self
            .custody_execution_runtime()
            .settle_agent_spawn_custody_failure(request.spawn_request_id, &child, code)
            .await
        {
            tracing::error!(target: "agent_coordination", spawn_request_id = %request.spawn_request_id, error = %error, "failed to settle agent child custody refusal");
        }
    }

    /// Scheduled Fresh launches can inherit only the already-resolved origin
    /// rotation-disable state. This is private to the scheduler seam so normal
    /// public and retry launches cannot accidentally alter it.
    pub(super) async fn launch_scheduled_fresh(
        &self,
        config: LaunchConfig,
        initial_rotation_disabled: bool,
    ) -> Result<Uuid> {
        self.launch_session_with_retry_admission(
            config,
            None,
            initial_rotation_disabled,
            LaunchPurpose::Interactive,
            None,
        )
        .await
    }

    /// Retry children carry a private admission witness.  This keeps the
    /// public launch surface unchanged while ensuring the child can only enter
    /// `active` after its lineage, retry state, and parent marker settlement
    /// commit together.
    pub(super) async fn launch_retry_successor(
        &self,
        config: LaunchConfig,
        admission: super::types::RetryAdmission,
    ) -> Result<Uuid> {
        self.launch_session_with_retry_admission(
            config,
            Some(admission),
            false,
            LaunchPurpose::Interactive,
            None,
        )
        .await
    }

    pub(super) async fn launch_manager_action_candidate(
        &self,
        config: LaunchConfig,
        context: super::types::ManagerActionLaunchContext,
    ) -> Result<Uuid> {
        let target = context
            .claim
            .operation
            .context
            .target_session_id
            .expect("reserved manager candidate");
        let result = self
            .launch_session_with_retry_admission(
                config,
                None,
                false,
                LaunchPurpose::ManagerAction(Box::new(context)),
                None,
            )
            .await;
        if result.is_err() && !self.active.read().await.contains_key(&target) {
            let invocation = {
                let mut store = self.store.lock().await;
                if store.get_session(target)?.is_some() {
                    store.fail_bound_direct_launch(target, "manager_action_launch_unconfirmed")?;
                }
                store.session_model_invocation_id(target)?
            };
            if let Some(invocation) = invocation {
                complete_invocation_by_id(
                    &self.store,
                    invocation,
                    InvocationCompletion {
                        error_class: Some("manager_action_launch_unconfirmed".into()),
                        confidence: Some(ModelUsageConfidence::Unavailable),
                        ..InvocationCompletion::default()
                    },
                    self.event_bus(),
                )
                .await?;
            }
            self.revoke_agent_token_for_session(target).await;
        }
        result
    }

    pub(super) async fn launch_session_with_retry_admission(
        &self,
        mut config: LaunchConfig,
        retry_admission: Option<super::types::RetryAdmission>,
        initial_rotation_disabled: bool,
        mut launch_purpose: LaunchPurpose,
        preheld_cwd_admission: Option<super::spawn_single_flight::ProviderCwdAdmissionGuard>,
    ) -> Result<Uuid> {
        let authenticated_retry = retry_admission.is_some();
        if authenticated_retry && (config.sandbox.is_some() || config.cargo_target_dir.is_some()) {
            return Err(DaemonError::InvalidParam(
                "authenticated retry cannot request sandbox allocation or a raw cargo target"
                    .into(),
            ));
        }
        // Spawn gate: container kinds (Group, Epic) are organizational nodes
        // only — the daemon does not spawn a provider subprocess for them.
        // Leaf kinds (Standard, TaskRabbit, Bug, Story, Task) proceed.
        let kind = config.session_kind.unwrap_or_default();
        if !rsi_common::is_leaf_kind(kind) {
            return Err(DaemonError::InvalidParam(
                "Cannot spawn a container-kind session".into(),
            ));
        }
        // Freeze the live daemon setting for this launch. Later launches observe
        // UpdateDaemonConfig, while this row and its monitor use one value.
        let context_rotation_enabled = self
            .runtime_config
            .context_rotation_enabled
            .load(Ordering::Relaxed);

        // Acquire settlement-producer ownership before sandbox allocation,
        // persistence, admission, or provider spawn. Once shutdown seals new
        // producers, launches fail here without creating unsettled work.
        let model_call_settlements = self.model_call_settlements.handle()?;
        #[cfg(test)]
        let session_id = retry_admission
            .as_ref()
            .filter(|_| matches!(&launch_purpose, LaunchPurpose::Interactive))
            .and_then(|admission| take_retry_successor_id_for_test(admission.parent_session_id))
            .unwrap_or_else(|| launch_purpose.session_id());
        #[cfg(not(test))]
        let session_id = launch_purpose.session_id();

        #[cfg(test)]
        let session_id = fresh_manager_test_ids()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&config.query)
            .unwrap_or(session_id);

        // Single-flight spawn guard (structural). `session_id` is a brand-new
        // UUID, so no concurrent same-id spawn can exist and the adopt branch is
        // skipped; the guard keeps the check -> launch -> active.insert invariant
        // uniform across every provider-spawn entry point. Held (local) through
        // the synchronous `active.insert`; not extended into the spawned monitor
        // / deferred app-server task (fresh UUID => no same-id contention).
        let spawn_guard = super::spawn_single_flight::acquire_spawn_guard(session_id).await;
        let cwd_admission_guard = match preheld_cwd_admission {
            Some(guard) => guard,
            None => super::spawn_single_flight::acquire_provider_cwd_admission().await,
        };

        // Reconciliation can revisit the same UUID after admission but before
        // publication. Resolve that exact obligation under single-flight,
        // before either the retained-root allocator or fresh capacity preflight.
        if let LaunchPurpose::AgentSuccessor(context) = &launch_purpose {
            if self
                .settle_unpublished_agent_successor(&context.reservation)
                .await?
            {
                return Err(DaemonError::Process(
                    crate::store::successor_reservations::UNPUBLISHED_SUCCESSOR_CLEANUP.into(),
                ));
            }
            // No admission exists: a root at the candidate path is at most the
            // allocation a pre-admission refusal retained (Issue #620).
            // Boxed: keeps this rare recovery step out of every launch
            // future's inline size.
            Box::pin(self.reclaim_retained_agent_successor_root(&context.reservation)).await?;
        }

        if let Some(context) = launch_purpose.manager_action() {
            self.check_manager_action_runtime(&context.claim, false)
                .await?;
            if self.store.lock().await.get_session(session_id)?.is_some() {
                return Err(DaemonError::InvalidParam(
                    "manager_v2_candidate_already_exists".into(),
                ));
            }
        }

        if let Some(context) = launch_purpose.closure_source() {
            let existing = {
                let store = self.store.lock().await;
                store.get_session(session_id)?
            };
            if let Some(existing) = existing {
                let custody = self
                    .store
                    .lock()
                    .await
                    .live_custody_for_session(session_id)?;
                if existing.id != context.session_id || custody.custody_id != context.custody_id {
                    return Err(DaemonError::Store(
                        "reserved Closure session identity conflicts with durable launch state"
                            .into(),
                    ));
                }
                return Ok(session_id);
            }
        }

        if let Some(context) = launch_purpose.agent_child() {
            let store = self.store.lock().await;
            if store
                .get_agent_spawn_request(context.spawn_request_id)?
                .is_some_and(|request| {
                    request.state == rsi_common::agent_coordination::AgentSpawnStateV1::Launched
                        && request.child_session_id == session_id
                })
                && store.get_session(session_id)?.is_some()
            {
                return Ok(session_id);
            }
        }

        // working_dir is REQUIRED in Session - provide fallback
        let raw_working_dir = config.working_dir.clone().unwrap_or_else(|| {
            std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/tmp"))
        });

        // Defense-in-depth: canonicalize working_dir even if the RPC layer already did.
        // Direct callers (rotation, retry) may bypass RPC validation. If canonicalize
        // fails here (directory deleted between RPC call and launch), fall back to the
        // original path and let cmd.current_dir() produce the Io error downstream.
        let working_dir = if let Some(admission) = retry_admission.as_ref() {
            if raw_working_dir != admission.source().working_dir {
                return Err(DaemonError::InvalidParam(
                    "retry raw working directory does not match durable source".into(),
                ));
            }
            raw_working_dir.clone()
        } else {
            raw_working_dir
                .canonicalize()
                .unwrap_or_else(|_| raw_working_dir.clone())
        };
        let launch_path_fenced = {
            let store = self.store.lock().await;
            store.path_is_inside_settlement_root(&raw_working_dir)?
                || store.path_is_inside_settlement_root(&working_dir)?
                || (!authenticated_retry
                    && config.sandbox.is_none()
                    && (store.path_is_inside_live_custody_root(&raw_working_dir)?
                        || store.path_is_inside_live_custody_root(&working_dir)?))
        };
        if launch_path_fenced {
            return Err(DaemonError::PolicyDenied(
                "provider launch cwd is fenced by live or settling sandbox custody".into(),
            ));
        }

        // Sandbox allocation (fail-closed). Runs BEFORE Session insertion so a
        // sandbox-requested launch that cannot allocate produces an RPC error
        // rather than a silent security downgrade.
        let mut allocation_source_commit = None;
        let allocation: Option<SandboxAllocation> = match config.sandbox.as_ref() {
            Some(spec) => {
                let kind = spec.kind.unwrap_or(SandboxKind::GitWorktree);
                // H1-04 (F-011): an agent child forks exclusively from the
                // authenticated emitter HEAD captured by `launch_agent_child`.
                // The canonical selector resolution below is structurally
                // unreachable for LaunchPurpose::AgentChild — a missing
                // candidate refuses instead of falling back. Non-agent
                // launches resolve the closure selector's base SHA (default
                // HEAD) in the caller's tree.
                let mut rolling_selection = None;
                let (source_origin, source_commit) =
                    if let Some(context) = launch_purpose.agent_child() {
                        let fork = context.fork.as_ref().ok_or_else(|| {
                            CustodyService::refusal(
                                rsi_common::types::SandboxCustodyErrorCodeV1::TupleIncomplete,
                                Some(session_id),
                                rsi_common::types::SandboxCustodyTransitionV1::AgentSpawnChild,
                            )
                        })?;
                        (
                            fork.fork_origin().to_path_buf(),
                            fork.fork_commit().to_string(),
                        )
                    } else if let Some(context) = launch_purpose.manager_successor() {
                        let claim = context.claim().await;
                        context.source_gate().await?;
                        (
                            claim
                                .reservation
                                .frozen
                                .predecessor
                                .sandbox_root
                                .clone()
                                .unwrap_or_else(|| working_dir.clone()),
                            claim.reservation.frozen.handoff.source_commit.clone(),
                        )
                    } else if let Some(context) = launch_purpose.manager_action() {
                        (
                            context.fork.fork_origin().to_path_buf(),
                            context.fork.fork_commit().to_owned(),
                        )
                    } else if let Some(context) = launch_purpose.topology_node() {
                        (
                            context.fork.origin().to_path_buf(),
                            context.fork.commit().to_owned(),
                        )
                    } else if matches!(launch_purpose, LaunchPurpose::AgentSuccessor(_)) {
                        // A master successor continues the Epic from the
                        // freshest fetched upstream when it fast-forwards the
                        // shared checkout's lagging local branch (#620).
                        let origin = working_dir.clone();
                        let source = Box::pin(tokio::task::spawn_blocking(move || {
                            crate::sandbox::git_worktree::freshest_successor_source(&origin)
                        }))
                        .await
                        .map_err(|error| {
                            DaemonError::Process(format!(
                                "successor source resolution join failed: {error}"
                            ))
                        })??;
                        let origin = working_dir.clone();
                        let source = tokio::task::spawn_blocking(move || {
                            crate::sandbox::git_worktree::fresh_rolling_base(
                                &origin,
                                session_id,
                                source,
                                crate::sandbox::git_worktree::RollingBasePolicy::FastForwardOnly,
                            )
                        })
                        .await
                        .map_err(|error| {
                            DaemonError::Process(format!(
                                "successor rolling base observation join failed: {error}"
                            ))
                        })??;
                        let commit = source.commit.clone();
                        rolling_selection = Some(source);
                        (working_dir.clone(), commit)
                    } else {
                        let requested_source = config
                            .closure_selector
                            .as_ref()
                            .map_or("HEAD", |selector| selector.base_sha.as_str());
                        let source_commit = std::process::Command::new("git")
                            .args([
                                "rev-parse",
                                "--verify",
                                &format!("{requested_source}^{{commit}}"),
                            ])
                            .current_dir(&working_dir)
                            .output()
                            .map_err(|error| {
                                DaemonError::Process(format!(
                                    "failed to resolve sandbox source commit: {error}"
                                ))
                            })?;
                        if !source_commit.status.success() {
                            return Err(DaemonError::InvalidParam(
                                "sandbox source commit is unavailable".to_string(),
                            ));
                        }
                        let mut source_commit = String::from_utf8_lossy(&source_commit.stdout)
                            .trim()
                            .to_string();
                        if matches!(launch_purpose, LaunchPurpose::Interactive)
                            && config.closure_selector.is_none()
                        {
                            let origin = working_dir.clone();
                            let selection = tokio::task::spawn_blocking(move || {
                                crate::sandbox::git_worktree::fresh_rolling_base(
                                    &origin,
                                    session_id,
                                    source_commit,
                                    crate::sandbox::git_worktree::RollingBasePolicy::RemoteTip,
                                )
                            })
                            .await
                            .map_err(|error| {
                                DaemonError::Process(format!(
                                    "rolling base observation join failed: {error}"
                                ))
                            })??;
                            source_commit = selection.commit.clone();
                            rolling_selection = Some(selection);
                        }
                        (working_dir.clone(), source_commit)
                    };
                allocation_source_commit = Some(source_commit.clone());
                let allocate = |commit: &str| {
                    if launch_purpose.closure_source().is_some() {
                        self.sandbox_allocator.allocate_or_adopt_reserved_closure(
                            session_id,
                            &working_dir,
                            kind,
                            commit,
                            spec.branch.as_deref(),
                        )
                    } else {
                        self.sandbox_allocator.allocate(
                            session_id,
                            &source_origin,
                            kind,
                            commit,
                            spec.branch.as_deref(),
                        )
                    }
                };
                let allocation_result = if let Some(selection) = rolling_selection {
                    selection.allocate_with_cleanup(allocate)
                } else {
                    allocate(&source_commit)
                };
                match allocation_result {
                    Ok(a) => {
                        tracing::info!(
                            session_id = %session_id,
                            sandbox_root = %a.root.display(),
                            sandbox_branch = ?a.branch,
                            "Sandbox allocated for session"
                        );
                        Some(a)
                    }
                    Err(e) => {
                        tracing::error!(
                            session_id = %session_id,
                            error = %e,
                            "Sandbox allocation failed; aborting launch"
                        );
                        // H1-04 (F-011): a failed fork allocation settles as
                        // a bounded custody refusal for agent children so the
                        // reserved spawn row and child id fail closed.
                        if launch_purpose.agent_child().is_some() {
                            return Err(CustodyService::refusal(
                                rsi_common::types::SandboxCustodyErrorCodeV1::AllocationFailed,
                                Some(session_id),
                                rsi_common::types::SandboxCustodyTransitionV1::AgentSpawnChild,
                            ));
                        }
                        return Err(e);
                    }
                }
            }
            None => None,
        };

        // Armed for as long as this launch has an allocated-but-not-yet-owned
        // sandbox. A direct launch disarms immediately after its durable
        // ownership bind; non-direct paths keep the established active-map
        // boundary. Any earlier return retains the allocation for recovery.
        let mut sandbox_guard = SandboxLaunchGuard {
            session_id,
            allocation: allocation.clone(),
        };

        // Effective working directory: sandbox root if present, else the
        // canonical working_dir. Every provider spawn uses this — substituted
        // here via `config.working_dir` mutation so tool-level working_dir
        // propagation is unchanged.
        let effective_working_dir = allocation
            .as_ref()
            .map(|a| a.root.clone())
            .unwrap_or_else(|| working_dir.clone());
        // Keep Session.working_dir = canonical; mutate config so every
        // provider that reads `config.working_dir` spawns in the sandbox.
        // Never accept an execution descriptor from a raw launch config. It
        // becomes available only after the custody ContextRead below.
        config.execution_scratch = None;
        if !authenticated_retry {
            config.working_dir = Some(effective_working_dir.clone());
        }

        // Issue #25: designate a session-scoped cargo build scratch inside the
        // sandbox root. Providers stamp it into the subprocess env as
        // `CARGO_TARGET_DIR`, so worker `cargo` runs build on disk-backed
        // storage (reclaimed with the sandbox) instead of improvising a
        // multi-GB target dir on the size-limited /tmp tmpfs — whose
        // exhaustion surfaces as spurious SQLITE_IOERR_WRITE test failures.
        // Non-sandboxed sessions keep the user's own cargo config untouched.
        if !authenticated_retry {
            config.cargo_target_dir = allocation.as_ref().map(|a| {
                a.root
                    .join(rsi_common::identity::SANDBOX_BUILD_CACHE_DIR_NAME)
            });
        }

        // Inject flywheel env vars for flywheel-signal
        if !authenticated_retry {
            config.rsi_session_id = Some(session_id);
            config.rsi_socket = Some(self.socket_path.clone());
        }
        // A caller-supplied authority token must never survive into a fresh
        // provider launch. A fresh token is minted only after model admission
        // succeeds, immediately before provider spawn.
        config.rsi_session_token = None;

        // Resolve project early — pipeline needs project data for context file injection.
        // find_project_for_path is O(n) on sorted Vec — microseconds, safe for hot path.
        let resolved_project_id = if authenticated_retry {
            config.project_id
        } else if config.project_id.is_some() {
            config.project_id
        } else {
            let index = self.project_index.read().await;
            index.find_project_for_path(&working_dir)
        };

        // Fetch full Project struct if we have a project_id (needed for context_files).
        let mut resolved_project: Option<rsi_common::types::Project> = if authenticated_retry {
            None
        } else if let Some(pid) = resolved_project_id {
            let store = self.store.clone();
            tokio::task::spawn_blocking(move || {
                let store = store.blocking_lock();
                store.get_project(pid).ok().flatten()
            })
            .await
            .ok()
            .flatten()
        } else {
            None
        };

        // Apply per-project settings overrides from FLYWHEEL.md (fallback -- explicit config wins).
        if !authenticated_retry && let Some(pid) = resolved_project_id {
            let cache = self.workflow_config_cache.read().await;
            if let Some(wf) = cache.get(&pid) {
                let ps = &wf.settings;
                if config.provider.is_none() {
                    config.provider = ps.provider;
                }
                if config.model.is_none() && !config.skip_project_model_default {
                    config.model = ps.model.clone();
                }
                if config.session_kind.is_none() {
                    config.session_kind = ps.session_kind;
                }
            }
        }
        // Re-resolve provider after settings override
        let provider = config.provider.unwrap_or(SessionProvider::Claude);
        apply_provider_model_default(provider, &mut config.model);
        if let Some(context) = launch_purpose.manager_action() {
            let frozen = context
                .claim
                .operation
                .context
                .launch
                .as_ref()
                .ok_or_else(|| DaemonError::InvalidParam("manager_v2_launch_unavailable".into()))?;
            if provider != frozen.provider
                || config.model.as_deref() != Some(frozen.model.as_str())
                || config.effort != frozen.effort
            {
                return Err(DaemonError::InvalidParam(
                    "manager_v2_launch_changed".into(),
                ));
            }
        }

        if config.configured_context_window.is_none() {
            config.configured_context_window = retry_admission.as_ref().and_then(|admission| {
                admission
                    .source()
                    .resolved_context_budget
                    .as_ref()
                    .and_then(|budget| budget.capacity.configured_tokens)
            });
        }
        match provider {
            SessionProvider::Codex => {
                if let Some(tokens) = config.configured_context_window {
                    crate::codex::validate_codex_configured_context_window(tokens)?;
                }
            }
            _ if config.configured_context_window.is_some() => {
                return Err(DaemonError::InvalidParam(
                    "configured_context_window is supported only for the Codex provider".into(),
                ));
            }
            _ => {}
        }
        if let Err(error) = crate::provider_capabilities::refresh_installed_catalog_for_provider(
            provider,
            Arc::clone(&self.runtime_config),
        )
        .await
        {
            tracing::warn!(
                session_id = %session_id,
                %error,
                "Installed provider catalog refresh failed at launch; using degraded capability evidence"
            );
        }
        let mut launch_context_budget = retry_admission.as_ref().map_or_else(
            || {
                crate::provider_capabilities::resolve_fresh_context_budget(
                    provider,
                    config.model.as_deref().unwrap_or("unknown"),
                    config.configured_context_window,
                )
            },
            |admission| {
                crate::provider_capabilities::resolve_new_incarnation_context_budget_for(
                    provider,
                    config.model.as_deref().unwrap_or("unknown"),
                    admission.source().resolved_context_budget.as_ref(),
                )
            },
        );
        if let LaunchPurpose::ControllerCandidate(context) = &launch_purpose
            && (context.reservation.candidate_session_id != session_id
                || context.reservation.validate(context.idea_id).is_err()
                || resolved_project_id != Some(context.project_id)
                || config.project_id != Some(context.project_id))
        {
            return Err(DaemonError::InvalidParam(
                "controller candidate launch scope or deterministic identity mismatch".into(),
            ));
        }
        if let LaunchPurpose::AgentSuccessor(context) = &launch_purpose {
            let frozen = context.reservation.inherited_launch()?;
            let expected_invocation = context.reservation.model_invocation_id.ok_or_else(|| {
                DaemonError::Store("successor launch context omitted invocation identity".into())
            })?;
            let expected_dedup = format!(
                "agent:reserve:successor:{}:{expected_invocation}",
                context.reservation.reservation_id
            );
            if context.reservation.candidate_session_id != session_id
                || config.parent_id != Some(context.reservation.epic_id)
                || config.continued_from != Some(context.reservation.predecessor_session_id)
                || provider != frozen.provider()?
                || resolved_project_id != frozen.project_id
                || config.project_id != frozen.project_id
                || config.model_invocation_purpose
                    != rsi_common::model_control::ModelInvocationPurpose::AgentReserveSuccessor
                || config.model_invocation_dedup_key.as_deref() != Some(expected_dedup.as_str())
            {
                return Err(DaemonError::InvalidParam(
                    "agent successor launch scope or frozen identity mismatch".into(),
                ));
            }
        }
        let session_kind = config.session_kind.unwrap_or_default();
        let default_max_retries =
            super::retry_policy::effective_default(&self.runtime_config, session_kind);
        let configured_max_retries = config.max_retries;
        if let Some(parent) = config.parent_id {
            self.store
                .lock()
                .await
                .manager_v2_resource_gate_for_parent(parent, provider)?;
        }
        let purpose = config.model_invocation_purpose;
        // Every new UUID with a parent reserves its manager cohort before
        // publication, regardless of invocation purpose (retry, workflow,
        // replacement, fresh or agent launch). The opaque launch context is
        // derived here after ordinary scope/custody validation; it grants no
        // lifecycle authority. Agent paths additionally bind their actual
        // durable reservation, rechecked inside the admission transaction.
        let resource_launch_origin = if let Some(context) = launch_purpose.manager_successor() {
            let claim = context.claim().await;
            Some(
                self.store
                    .lock()
                    .await
                    .manager_v2_root_successor_origin(&claim)?,
            )
        } else if let Some(parent) = config.parent_id {
            let store = self.store.lock().await;
            let origin = store.manager_v2_launch_origin(
                session_id,
                parent,
                resolved_project_id,
                session_kind,
            )?;
            Some(match &launch_purpose {
                LaunchPurpose::AgentChild(context) => store.manager_v2_bind_child_origin(
                    origin,
                    context.spawn_request_id,
                    context.owner_session_id,
                )?,
                LaunchPurpose::AgentSuccessor(context) => {
                    store.manager_v2_bind_successor_origin(origin, &context.reservation)?
                }
                _ => origin,
            })
        } else {
            if matches!(
                launch_purpose,
                LaunchPurpose::AgentChild(_) | LaunchPurpose::AgentSuccessor(_)
            ) {
                return Err(DaemonError::PolicyDenied(
                    "agent launch requires its reserved parent".into(),
                ));
            }
            None
        };
        #[cfg(test)]
        if resource_launch_origin.is_some() {
            pause_controller_candidate_test(
                session_id,
                ControllerCandidateTestPhase::FreshChildAfterParentValidation,
            )
            .await;
        }
        let parent_invocation_id = if let Some(context) = launch_purpose.manager_successor() {
            context
                .claim()
                .await
                .reservation
                .frozen
                .predecessor_invocation_id
        } else {
            resolve_parent_invocation_id_for_launch(&self.store, &config).await?
        };
        let retry_of_invocation_id =
            if purpose == rsi_common::model_control::ModelInvocationPurpose::SessionRetryAuto {
                match config.continued_from {
                    Some(session_id) => load_session_invocation_id(&self.store, session_id).await?,
                    None => None,
                }
            } else {
                None
            };
        let admission_request = crate::model_control::ModelAdmissionRequest {
            purpose,
            provider: Some(launch_provider_label(provider)),
            model: config.model.clone(),
            backend: Some(launch_provider_label(provider)),
            effort: config.effort.clone(),
            trigger: if launch_purpose.manager_successor().is_some() {
                "manager_self_succession"
            } else {
                "launch_session"
            }
            .to_string(),
            owner: launch_owner_from_config(session_id, resolved_project_id, &config),
            dedup_key: Some(
                config
                    .model_invocation_dedup_key
                    .clone()
                    .unwrap_or_else(|| format!("{purpose}:{session_id}")),
            ),
            request_fingerprint: Some(
                config
                    .model_invocation_request_fingerprint
                    .clone()
                    .unwrap_or_else(|| {
                        hash_request_fingerprint(&[
                            purpose.as_str(),
                            &launch_provider_label(provider),
                            config.model.as_deref().unwrap_or(""),
                            &config.query,
                        ])
                    }),
            ),
            parent_invocation_id,
            retry_of_invocation_id,
            expected_usage: Some(crate::model_control::explicit_expected_usage(
                purpose,
                Some(launch_provider_label(provider).as_str()),
                Some(launch_provider_label(provider).as_str()),
                config.model.as_deref(),
            )),
            baseline_input_tokens: 0,
            baseline_output_tokens: 0,
            baseline_cache_creation_tokens: 0,
            baseline_cache_read_tokens: 0,
            baseline_reasoning_tokens: 0,
            baseline_embedding_input_count: 0,
            baseline_wall_time_ms: 0,
        };

        let mut retry_bound: Option<BoundRetryCustody> = None;
        let mut retry_session: Option<Session> = None;
        let mut retry_admission_permit = None;
        let mut retry_context_permit = None;
        if let Some(admission) = retry_admission.as_ref() {
            let mut session = build_starting_session(
                &config,
                session_id,
                provider,
                &working_dir,
                resolved_project_id,
                session_kind,
                configured_max_retries,
                default_max_retries,
                None,
                None,
                None,
                context_rotation_enabled,
            );
            install_context_budget(&mut session, launch_context_budget.clone());
            session.retry_attempt = Some(admission.retry_attempt);
            session.max_retries = Some(admission.max_retries);
            session.tags = admission.source().tags.clone();
            session.tag = session.tags.first().cloned().unwrap_or_default();
            crate::sandbox::custody::CustodyExecutionRuntime::apply_retry_successor_tuple(
                admission.custody_candidate(),
                admission.source(),
                &mut session,
            )?;

            // Model admission is the only model-side effect before the
            // unchanged C5 transaction and remains immediately adjacent to it.
            tracing::info!(session_id = %session_id, "Launch: requesting retry model admission");
            let admission_permit = match crate::model_control::admit_launch_invocation(
                &self.store,
                admission_request.clone(),
                self.event_bus(),
                resource_launch_origin.as_ref(),
            )
            .await?
            {
                AdmissionDecision::Admitted(permit) => permit,
                AdmissionDecision::Duplicate { invocation_id } => {
                    return Err(DaemonError::PolicyDenied(format!(
                        "duplicate model invocation admission blocked backend execution: {invocation_id}"
                    )));
                }
            };
            admission.mark_attempted();
            let c5_result = self.store.lock().await.admit_c5_retry_successor(
                admission.parent_session_id,
                &session,
                admission.retry_attempt,
                admission.max_retries,
                admission_permit.invocation_id(),
                &admission.pending_marker,
            );
            if let Err(error) = c5_result {
                admission.mark_failed(error.is_retryable_admission_failure());
                let reclaim_prepared = matches!(
                    error,
                    crate::store::daemon_settings::C5TransitionError::ReclaimPrepared { .. }
                );
                if reclaim_prepared {
                    admission.mark_reclaim_prepared();
                }
                let _ = complete_invocation(
                    &self.store,
                    &admission_permit,
                    InvocationCompletion {
                        error_class: Some(if reclaim_prepared {
                            "reclaim_prepared".into()
                        } else {
                            "retry_admission_failed".into()
                        }),
                        confidence: Some(ModelUsageConfidence::Unavailable),
                        ..InvocationCompletion::default()
                    },
                    self.event_bus(),
                )
                .await;
                return Err(error.into());
            }
            admission.mark_committed();
            #[cfg(test)]
            pause_retry_custody_test(session_id, RetryCustodyTestPhase::AfterC5BeforeBind).await;

            let bound = match self
                .custody_execution_runtime()
                .bind_retry_successor(admission.custody_candidate(), admission.source(), &session)
                .await
            {
                Ok(bound) => bound,
                Err(failure) => {
                    let error = match failure {
                        RetryBindFailure::Superseded => {
                            DaemonError::Store("retry custody bind was superseded".into())
                        }
                        RetryBindFailure::SettlementFailed(error) => error,
                    };
                    let _ = complete_invocation(
                        &self.store,
                        &admission_permit,
                        InvocationCompletion {
                            error_class: Some("custody_bind_failed".into()),
                            confidence: Some(ModelUsageConfidence::Unavailable),
                            ..InvocationCompletion::default()
                        },
                        self.event_bus(),
                    )
                    .await;
                    return Err(error);
                }
            };
            if bound.disposition() == RetryCustodyDisposition::Transferred {
                self.revoke_agent_token_for_session(admission.parent_session_id)
                    .await;
            }
            #[cfg(test)]
            pause_retry_custody_test(session_id, RetryCustodyTestPhase::AfterBindBeforeContext)
                .await;

            let context_permit = match self
                .custody_execution_runtime()
                .begin_retry_context_read(&bound, &session)
                .await
            {
                Ok(permit) => permit,
                Err(error) => {
                    let _ = self
                        .custody_execution_runtime()
                        .settle_retry_context_failure(session_id, &bound, &error)
                        .await;
                    let _ = complete_invocation(
                        &self.store,
                        &admission_permit,
                        InvocationCompletion {
                            error_class: Some("context_custody_failed".into()),
                            confidence: Some(ModelUsageConfidence::Unavailable),
                            ..InvocationCompletion::default()
                        },
                        self.event_bus(),
                    )
                    .await;
                    return Err(error);
                }
            };
            config.working_dir = Some(context_permit.effective_cwd().to_path_buf());
            config.cargo_target_dir = context_permit.cargo_target_dir().map(ToOwned::to_owned);
            #[cfg(test)]
            if take_retry_execution_scratch_failure_for_test(session_id) {
                std::os::unix::fs::symlink(
                    context_permit.effective_cwd(),
                    context_permit.effective_cwd().join("target"),
                )
                .expect("install retry descriptor-relative target symlink");
            }
            config.execution_scratch = match crate::sandbox::execution_scratch::SandboxExecutionScratch::from_context_permit(
                &context_permit,
            ) {
                Ok(scratch) => scratch,
                Err(error) => {
                    drop(context_permit);
                    if let Err(settlement_error) = self
                        .custody_execution_runtime()
                        .settle_retry_context_failure(session_id, &bound, &error)
                        .await
                    {
                        return Err(settlement_error);
                    }
                    complete_invocation(
                        &self.store,
                        &admission_permit,
                        InvocationCompletion {
                            error_class: Some("execution_scratch_unavailable".into()),
                            confidence: Some(ModelUsageConfidence::Unavailable),
                            ..InvocationCompletion::default()
                        },
                        self.event_bus(),
                    )
                    .await?;
                    return Err(error);
                }
            };
            config.rsi_session_id = Some(session_id);
            config.rsi_socket = Some(self.socket_path.clone());
            if let Some(pid) = resolved_project_id {
                let store = self.store.clone();
                resolved_project = tokio::task::spawn_blocking(move || {
                    let store = store.blocking_lock();
                    store.get_project(pid).ok().flatten()
                })
                .await
                .ok()
                .flatten();
                if let Some(project) = resolved_project.as_mut() {
                    project.path = Some(context_permit.effective_cwd().to_path_buf());
                }
            }
            retry_bound = Some(bound);
            retry_session = Some(session);
            retry_admission_permit = Some(admission_permit);
            retry_context_permit = Some(context_permit);
        }

        // Every non-retry fresh launch that owns a direct custody binding must
        // commit that binding before ContextRead/config/provider work.  The
        // scheduled and controller variants share the existing direct durable
        // transaction; their later persistence arms are skipped below.
        let direct_interactive = launch_purpose.manager_successor().is_some()
            || launch_purpose.is_agent_successor()
            || (launch_purpose.uses_direct_establishment()
                && retry_admission.is_none()
                && (config.continued_from.is_none() || launch_purpose.manager_action().is_some())
                && (!initial_rotation_disabled || config.scheduled_job_id.is_some()))
            || (retry_admission.is_none()
                && config.continued_from.is_none()
                && (config.scheduled_job_id.is_some()
                    || launch_purpose.is_controller_candidate()
                    || launch_purpose.agent_child().is_some()));
        let direct_binding = if direct_interactive {
            Some(if let Some(allocation) = allocation.as_ref() {
                new_root_binding_from_allocation(
                    allocation,
                    &working_dir,
                    allocation_source_commit.as_deref(),
                    if launch_purpose.agent_child().is_some() {
                        CustodyCause::AgentSpawnChild
                    } else {
                        CustodyCause::FreshLaunch
                    },
                    // A closure-source launch adopts its pre-reserved custody
                    // identity; every other fresh launch mints a new one.
                    launch_purpose
                        .closure_source()
                        .map(|context| context.custody_id),
                )?
            } else {
                SessionCustodyBinding::Ordinary
            })
        } else {
            None
        };
        let mut direct_session = None;
        let mut direct_prepared_launch: Option<PreparedLaunch> = None;
        let mut direct_admission = None;
        #[cfg(test)]
        let direct_test_control_key = direct_launch_custody_test_control_key(&config, session_id);
        if direct_interactive {
            let admission_permit = match crate::model_control::admit_launch_invocation(
                &self.store,
                admission_request.clone(),
                self.event_bus(),
                resource_launch_origin.as_ref(),
            )
            .await?
            {
                AdmissionDecision::Admitted(permit) => permit,
                AdmissionDecision::Duplicate { invocation_id }
                    if launch_purpose.closure_source().is_some() =>
                {
                    crate::model_control::resume_unexecuted_closure_launch_admission(
                        &self.store,
                        &admission_request,
                        invocation_id,
                    )
                    .await?
                }
                AdmissionDecision::Duplicate { invocation_id }
                    if launch_purpose.is_agent_successor() =>
                {
                    crate::model_control::resume_unexecuted_agent_successor_admission(
                        &self.store,
                        &admission_request,
                        invocation_id,
                    )
                    .await?
                }
                AdmissionDecision::Duplicate { invocation_id } => {
                    return Err(DaemonError::PolicyDenied(format!(
                        "duplicate model invocation admission blocked backend execution: {invocation_id}"
                    )));
                }
            };
            #[cfg(test)]
            if resource_launch_origin.is_some() {
                pause_controller_candidate_test(
                    session_id,
                    ControllerCandidateTestPhase::FreshChildAfterAdmission,
                )
                .await;
            }
            let mut session = build_starting_session(
                &config,
                session_id,
                provider,
                &working_dir,
                resolved_project_id,
                session_kind,
                configured_max_retries,
                default_max_retries,
                allocation.as_ref(),
                None,
                None,
                context_rotation_enabled,
            );
            install_context_budget(&mut session, launch_context_budget.clone());
            if initial_rotation_disabled {
                session
                    .rotation_disabled_at
                    .get_or_insert_with(chrono::Utc::now);
            }
            if let Some(context) = launch_purpose.manager_successor() {
                context.refresh().await?;
                let root = context.claim().await.reservation;
                session.rotation_depth = root
                    .frozen
                    .predecessor
                    .rotation_depth
                    .checked_add(1)
                    .ok_or_else(|| {
                        crate::store::harness_manager_v2::refused(
                            "manager_succession_depth_overflow",
                        )
                    })?;
                session.rotation_disabled_at = root.frozen.predecessor.rotation_disabled_at;
                session.description = root.frozen.predecessor.description.clone();
                session.active_task = root.frozen.predecessor.active_task.clone();
                session.tags = config.tags.clone();
                session.tag = root.frozen.predecessor.tag.clone();
            }
            if launch_purpose.is_agent_successor() {
                let LaunchPurpose::AgentSuccessor(context) = &launch_purpose else {
                    unreachable!("agent successor purpose checked above")
                };
                if let Some(disabled_at) =
                    context.reservation.inherited_launch()?.rotation_disabled_at
                {
                    session.rotation_disabled_at = Some(disabled_at);
                }
                session.tags = config.tags.clone();
                session.tag = session.tags.first().cloned().unwrap_or_default();
            }
            let binding = direct_binding
                .clone()
                .expect("direct interactive launches always construct a custody binding");
            let commit = if let Some(context) = launch_purpose.agent_child() {
                self.store.lock().await.admit_agent_child_session(
                    &session,
                    admission_permit.invocation_id(),
                    context.spawn_request_id,
                    context.owner_session_id,
                    binding,
                )
            } else if let LaunchPurpose::AgentSuccessor(context) = &launch_purpose {
                self.store
                    .lock()
                    .await
                    .insert_agent_successor_session_with_custody(
                        &context.reservation,
                        &session,
                        admission_permit.invocation_id(),
                        binding,
                    )
            } else {
                self.store
                    .lock()
                    .await
                    .insert_direct_session_with_custody_and_invocation(
                        &session,
                        binding,
                        admission_permit.invocation_id(),
                    )
            };
            if let Err(error) = commit {
                if let Err(settlement_error) = complete_invocation(
                    &self.store,
                    &admission_permit,
                    InvocationCompletion {
                        error_class: Some("session_custody_bind_failed".into()),
                        confidence: Some(ModelUsageConfidence::Unavailable),
                        ..InvocationCompletion::default()
                    },
                    self.event_bus(),
                )
                .await
                {
                    tracing::warn!(session_id=%session_id, error=%settlement_error, "failed to settle direct launch admission after custody transaction failure");
                }
                return Err(error);
            }
            // A committed root is retained for recovery; no later pre-provider
            // failure may invoke the allocation guard's destructive cleanup.
            sandbox_guard.disarm();
            if let Some(context) = launch_purpose.manager_successor() {
                let claim = context.claim().await;
                self.store
                    .lock()
                    .await
                    .record_manager_succession_candidate_bound(&claim)?;
                context.refresh().await?;
            }
            let authorization = {
                let mut store = self.store.lock().await;
                match allocation.as_ref() {
                    Some(_) => CustodyService::authorize_live(
                        &session,
                        &mut store,
                        self.sandbox_allocator.base_dir(),
                        rsi_common::types::SandboxCustodyTransitionV1::FreshLaunch,
                    ),
                    None => CustodyService::authorize_ordinary(&session),
                }
            };
            let handle = match authorization {
                Ok(handle) => handle,
                Err(error) => {
                    if let Err(settlement_error) = settle_failed_bound_fresh_pre_provider(
                        &mut launch_purpose,
                        &self.store,
                        self.event_bus(),
                        &self.agent_tokens,
                        session_id,
                        &admission_permit,
                        "fresh launch custody authorization failed",
                        "session_custody_authorization_failed",
                    )
                    .await
                    {
                        return Err(settlement_error);
                    }
                    return Err(error);
                }
            };
            direct_session = Some(session);
            direct_prepared_launch = Some(PreparedLaunch::new(handle));
            direct_admission = Some(admission_permit);
        }
        #[cfg(test)]
        if direct_interactive {
            pause_direct_launch_custody_test(&direct_test_control_key, session_id).await;
        }
        #[cfg(test)]
        if launch_purpose.is_agent_successor() {
            pause_controller_candidate_test(
                session_id,
                ControllerCandidateTestPhase::SuccessorAfterDurablePreEffect,
            )
            .await;
        }
        if let Some(context) = launch_purpose.manager_action() {
            self.check_manager_action_runtime(&context.claim, false)
                .await?;
        }
        let mut direct_context_permit = if let (Some(session), Some(prepared)) =
            (direct_session.as_ref(), direct_prepared_launch.as_ref())
        {
            #[cfg(test)]
            let context_effect =
                if take_direct_launch_context_failure_for_test(&direct_test_control_key) {
                    Err(DaemonError::Store(
                        "injected direct launch context authorization failure".into(),
                    ))
                } else {
                    CustodyService::begin_effect(
                        &self.store,
                        &self.custody_settlements,
                        prepared.custody(),
                        session,
                        self.sandbox_allocator.base_dir(),
                        self.program_run_boot_id,
                        EffectKind::ContextRead,
                    )
                    .await
                };
            #[cfg(not(test))]
            let context_effect = CustodyService::begin_effect(
                &self.store,
                &self.custody_settlements,
                prepared.custody(),
                session,
                self.sandbox_allocator.base_dir(),
                self.program_run_boot_id,
                EffectKind::ContextRead,
            )
            .await;
            match context_effect {
                Ok(permit) => Some(permit),
                Err(error) => {
                    if let Some(admission_permit) = direct_admission.as_ref()
                        && let Err(settlement_error) = settle_failed_bound_fresh_pre_provider(
                            &mut launch_purpose,
                            &self.store,
                            self.event_bus(),
                            &self.agent_tokens,
                            session_id,
                            admission_permit,
                            "fresh launch ContextRead authorization failed",
                            "session_context_authorization_failed",
                        )
                        .await
                    {
                        return Err(settlement_error);
                    }
                    return Err(error);
                }
            }
        } else {
            None
        };
        let custody_context_cwd = retry_context_permit
            .as_ref()
            .or(direct_context_permit.as_ref())
            .map(|permit| permit.effective_cwd().to_path_buf())
            .unwrap_or_else(|| effective_working_dir.clone());
        if let Some(permit) = direct_context_permit.as_ref() {
            // The unchanged provider funnel still consumes LaunchConfig in
            // this slice, so overwrite its raw paths from the authorized
            // permit before any provider-facing preparation can observe them.
            config.working_dir = Some(permit.effective_cwd().to_path_buf());
            config.cargo_target_dir = permit.cargo_target_dir().map(ToOwned::to_owned);
        }
        #[cfg(test)]
        if take_direct_launch_execution_scratch_failure_for_test(&direct_test_control_key) {
            let permit = direct_context_permit
                .as_ref()
                .expect("execution-scratch failure injection requires a ContextRead permit");
            std::os::unix::fs::symlink(
                permit.effective_cwd(),
                permit.effective_cwd().join("target"),
            )
            .expect("install descriptor-relative target symlink");
        }
        let direct_execution_scratch = match direct_context_permit.as_ref() {
            Some(permit) => {
                crate::sandbox::execution_scratch::SandboxExecutionScratch::from_context_permit(
                    permit,
                )
            }
            None => Ok(None),
        };
        match direct_execution_scratch {
            Ok(scratch) => config.execution_scratch = scratch,
            Err(error) => {
                drop(direct_context_permit.take());
                if let Some(admission_permit) = direct_admission.as_ref()
                    && let Err(settlement_error) = settle_failed_bound_fresh_pre_provider(
                        &mut launch_purpose,
                        &self.store,
                        self.event_bus(),
                        &self.agent_tokens,
                        session_id,
                        admission_permit,
                        "authenticated execution scratch preparation failed",
                        "execution_scratch_unavailable",
                    )
                    .await
                {
                    return Err(settlement_error);
                }
                return Err(error);
            }
        }

        // `config/read` starts a Codex transport, so it is provider-facing
        // preparation even though it never starts a thread or submits model
        // input. It must therefore use the same post-ContextRead cwd that the
        // provider will receive. Direct and retry launches have already made
        // their initial durable Starting row by this point, so persist the
        // newly discovered raw configuration with its full typed budget before
        // assembling context or entering the provider funnel.
        if provider == SessionProvider::Codex && config.configured_context_window.is_none() {
            let configured_tokens = match crate::codex::load_codex_configured_context_window(
                None,
                &custody_context_cwd,
            )
            .await
            {
                Ok(tokens) => tokens,
                Err(error) => {
                    drop(direct_context_permit.take());
                    drop(retry_context_permit.take());
                    if let Some(admission_permit) = direct_admission.as_ref() {
                        settle_failed_bound_fresh_pre_provider(
                            &mut launch_purpose,
                            &self.store,
                            self.event_bus(),
                            &self.agent_tokens,
                            session_id,
                            admission_permit,
                            "Codex config preparation failed",
                            "context_config_preparation_failed",
                        )
                        .await?;
                    } else if let (Some(bound), Some(admission_permit)) =
                        (retry_bound.as_ref(), retry_admission_permit.as_ref())
                    {
                        self.custody_execution_runtime()
                            .settle_retry_context_failure(session_id, bound, &error)
                            .await?;
                        complete_invocation(
                            &self.store,
                            admission_permit,
                            InvocationCompletion {
                                error_class: Some("context_config_preparation_failed".into()),
                                confidence: Some(ModelUsageConfidence::Unavailable),
                                ..InvocationCompletion::default()
                            },
                            self.event_bus(),
                        )
                        .await?;
                    }
                    return Err(error);
                }
            };
            if let Some(configured_tokens) = configured_tokens {
                config.configured_context_window = Some(configured_tokens);
                let configured_budget = crate::provider_capabilities::resolve_fresh_context_budget(
                    provider,
                    config.model.as_deref().unwrap_or("unknown"),
                    config.configured_context_window,
                );
                let persistence_error = if let Some(session) = direct_session.as_mut() {
                    let persisted = self
                        .persistence
                        .compare_and_update_session_model(
                            Arc::clone(&self.store),
                            session_id,
                            session.model.clone(),
                            session.context_window,
                            session.resolved_context_budget.clone(),
                            session.model.clone(),
                            Some(configured_budget.active_tokens),
                            Some(configured_budget.clone()),
                        )
                        .await;
                    match persisted {
                        Ok(true) => {
                            install_context_budget(session, configured_budget.clone());
                            None
                        }
                        Ok(false) => Some(DaemonError::Store(
                            "direct launch context budget changed while Codex config was preparing"
                                .into(),
                        )),
                        Err(error) => Some(error),
                    }
                } else if let Some(session) = retry_session.as_mut() {
                    let persisted = self
                        .persistence
                        .compare_and_update_session_model(
                            Arc::clone(&self.store),
                            session_id,
                            session.model.clone(),
                            session.context_window,
                            session.resolved_context_budget.clone(),
                            session.model.clone(),
                            Some(configured_budget.active_tokens),
                            Some(configured_budget.clone()),
                        )
                        .await;
                    match persisted {
                        Ok(true) => {
                            install_context_budget(session, configured_budget.clone());
                            None
                        }
                        Ok(false) => Some(DaemonError::Store(
                            "retry launch context budget changed while Codex config was preparing"
                                .into(),
                        )),
                        Err(error) => Some(error),
                    }
                } else {
                    None
                };
                if let Some(error) = persistence_error {
                    drop(direct_context_permit.take());
                    drop(retry_context_permit.take());
                    if let Some(admission_permit) = direct_admission.as_ref() {
                        settle_failed_bound_fresh_pre_provider(
                            &mut launch_purpose,
                            &self.store,
                            self.event_bus(),
                            &self.agent_tokens,
                            session_id,
                            admission_permit,
                            "Codex config persistence failed",
                            "session_context_config_persistence_failed",
                        )
                        .await?;
                    } else if let (Some(bound), Some(admission_permit)) =
                        (retry_bound.as_ref(), retry_admission_permit.as_ref())
                    {
                        self.custody_execution_runtime()
                            .settle_bound_retry_failure(
                                session_id,
                                bound,
                                SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                            )
                            .await?;
                        complete_invocation(
                            &self.store,
                            admission_permit,
                            InvocationCompletion {
                                error_class: Some(
                                    "session_context_config_persistence_failed".into(),
                                ),
                                confidence: Some(ModelUsageConfidence::Unavailable),
                                ..InvocationCompletion::default()
                            },
                            self.event_bus(),
                        )
                        .await?;
                    }
                    return Err(error);
                }
                launch_context_budget = configured_budget;
            }
        }

        // The allocation/retry custody tuple is already authenticated above.
        // Inject its dynamic ownership instruction before any provider-facing
        // context assembly, including the Codex CLI's separate stdin path.
        // Ordinary launches intentionally leave the caller prompt unchanged.
        let sandbox_custody_instruction = allocation
            .as_ref()
            .and_then(|allocation| {
                allocation.branch.as_deref().map(|branch| {
                    super::preamble::sandbox_custody_instruction(&allocation.root, branch)
                })
            })
            .or_else(|| {
                retry_session
                    .as_ref()
                    .and_then(super::preamble::sandbox_custody_instruction_for_session)
            });
        config.system_prompt = super::preamble::prepend_sandbox_custody_instruction(
            config.system_prompt.take(),
            sandbox_custody_instruction,
        );

        // Render FLYWHEEL.md template for context injection.
        let workflow_content: Option<String> = if let Some(pid) = resolved_project_id {
            let cache = self.workflow_config_cache.read().await;
            if let Some(wf) = cache.get(&pid) {
                if wf.template_body.is_empty() {
                    None
                } else {
                    let proj = resolved_project.as_ref();
                    // Use effective cwd so sandboxed sessions reflect the
                    // worktree branch (e.g. `rsi/<short>`) rather than the
                    // canonical repo branch.
                    let git_branch_for_tpl = std::process::Command::new("git")
                        .args(["rev-parse", "--abbrev-ref", "HEAD"])
                        .current_dir(&custody_context_cwd)
                        .output()
                        .ok()
                        .filter(|o| o.status.success())
                        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
                        .unwrap_or_default();
                    let ctx = crate::project_workflow::TemplateContext {
                        project: crate::project_workflow::ProjectTemplateVars {
                            name: proj.map(|p| p.name.clone()).unwrap_or_default(),
                            path: proj
                                .and_then(|p| p.path.as_ref())
                                .map(|p| p.display().to_string())
                                .unwrap_or_default(),
                            description: proj
                                .and_then(|p| p.description.clone())
                                .unwrap_or_default(),
                        },
                        session: crate::project_workflow::SessionTemplateVars {
                            query: config.query.clone(),
                            working_dir: custody_context_cwd.display().to_string(),
                            git_branch: git_branch_for_tpl,
                            model: config.model.clone().unwrap_or_default(),
                            provider: format!("{:?}", provider),
                            kind: format!(
                                "{:?}",
                                config.session_kind.unwrap_or(SessionKind::Standard)
                            ),
                            rotation_depth: 0,
                        },
                        env: std::env::vars().collect(),
                    };
                    match crate::project_workflow::render_template(&wf.template_body, &ctx) {
                        Ok(rendered) => Some(rendered),
                        Err(e) => {
                            tracing::warn!(
                                project_id = %pid,
                                error = %e,
                                "FLYWHEEL.md template render failed; skipping workflow context"
                            );
                            None
                        }
                    }
                }
            } else {
                None
            }
        } else {
            None
        };

        // Compose system prompt from multiple sources via context pipeline.
        // Caller-provided prompt (e.g., TaskRabbit instructions) is preserved, not overwritten.
        //
        // RSI-006: hermetic eval mode bypasses ContextPipeline entirely. When
        // `config.skip_context_pipeline` is true, `system_prompt` is left untouched;
        // the provider sees exactly what the caller passed. No preamble, no project
        // context, no memory bundle, no FLYWHEEL.md, no git log. This is the
        // load-bearing primitive for ±5% reproducibility — runtime-resolved sources
        // (memory, git log, FLYWHEEL.md, project files) drift between replays even
        // with frozen corpus inputs, so they must be skipped.
        if !config.skip_context_pipeline && provider_uses_launch_system_prompt(provider) {
            tracing::info!(session_id = %session_id, "Launch: assembling context pipeline");
            // Skip heavy context injection for TaskRabbit/Bug sessions (only active_task if present)
            let root_active_task = if let Some(context) = launch_purpose.manager_successor() {
                context
                    .claim()
                    .await
                    .reservation
                    .frozen
                    .predecessor
                    .active_task
            } else {
                None
            };
            let active_task = root_active_task.as_deref();
            let (pipeline_project, pipeline_active_task) = if matches!(
                config.session_kind,
                Some(SessionKind::TaskRabbit) | Some(SessionKind::Bug)
            ) {
                (None, active_task)
            } else {
                (resolved_project.as_ref(), active_task)
            };

            let pipeline = super::context_pipeline::ContextPipeline::new(
                Arc::clone(&self.token_counter),
                self.memory_handle.clone(),
                Arc::clone(&self.store),
            );
            let budget = super::context_pipeline::context_injection_allowance(
                launch_context_budget.active_tokens,
            );

            let mut parts = fresh_launch_preamble_parts(config.session_kind.unwrap_or_default());
            // Orchestration router — "the very mouth of the pipeline" for every
            // leaf-kind session (Standard / TaskRabbit / Bug / Story / Task /
            // Feature / Refactor / Research). Frames the worker BEFORE the
            // per-kind preamble so the worker classifies its task as Singular vs
            // Team Implement before doing the kind-specific work. Container kinds
            // (Group/Epic) never reach this assembly path — they're rejected by
            // `is_leaf_kind` at the top of `launch_session`. Runtime children
            // spawned by an Epic-lead via `<docregblock>/spawn_child …</docregblock>`
            // re-enter `launch_session` and inherit the router automatically.
            // Loader returns `None` if the skill file is absent; launch proceeds.
            // RSI-012: prepend kind-specific preamble (or base) BEFORE caller_prompt.
            // The preamble FRAMES the worker — subsequent context (caller prompt, FLYWHEEL,
            // memory bundle, query) is interpreted through that frame. Loader returns
            // `None` if no harness root could be discovered; launch continues either way.
            if let Some(caller_prompt) = config.system_prompt.take() {
                parts.push(caller_prompt);
            }
            if let Some(context) = pipeline
                .assemble(
                    &config.query,
                    &custody_context_cwd,
                    pipeline_project,
                    pipeline_active_task,
                    workflow_content.as_deref(),
                    None, // no parent session on initial launch
                    budget,
                )
                .await
            {
                parts.push(context);
            }
            if !parts.is_empty() {
                config.system_prompt = Some(parts.join("\n\n"));
            }
            tracing::info!(session_id = %session_id, "Launch: context pipeline assembly complete");
        }

        if let (Some(session), Some(admission_permit)) =
            (direct_session.as_mut(), direct_admission.as_ref())
        {
            let git_branch = std::process::Command::new("git")
                .args(["rev-parse", "--abbrev-ref", "HEAD"])
                .current_dir(&custody_context_cwd)
                .output()
                .ok()
                .filter(|output| output.status.success())
                .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_string());
            let harness_version_hash = Some(compute_harness_version_hash(
                config.system_prompt.as_deref(),
                &config.query,
                Some(config.session_kind.unwrap_or_default()),
            ));
            session.git_branch = git_branch;
            session.harness_version_hash = harness_version_hash;
            let metadata_result = {
                let mut store = self.store.lock().await;
                store.finalize_direct_launch_metadata(
                    session_id,
                    admission_permit.invocation_id(),
                    session.git_branch.as_deref(),
                    session.harness_version_hash.as_deref(),
                )
            };
            if let Err(error) = metadata_result {
                drop(direct_context_permit.take());
                settle_failed_bound_fresh_pre_provider(
                    &mut launch_purpose,
                    &self.store,
                    self.event_bus(),
                    &self.agent_tokens,
                    session_id,
                    admission_permit,
                    "fresh launch metadata persistence failed",
                    "session_metadata_persistence_failed",
                )
                .await?;
                return Err(error);
            }
        }
        if let (Some(session), Some(admission_permit), Some(bound)) = (
            retry_session.as_mut(),
            retry_admission_permit.as_ref(),
            retry_bound.as_ref(),
        ) {
            session.git_branch = std::process::Command::new("git")
                .args(["rev-parse", "--abbrev-ref", "HEAD"])
                .current_dir(&custody_context_cwd)
                .output()
                .ok()
                .filter(|output| output.status.success())
                .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_string());
            session.harness_version_hash = Some(compute_harness_version_hash(
                config.system_prompt.as_deref(),
                &config.query,
                Some(session.session_kind),
            ));
            let metadata_result = {
                let mut store = self.store.lock().await;
                store.finalize_direct_launch_metadata(
                    session_id,
                    admission_permit.invocation_id(),
                    session.git_branch.as_deref(),
                    session.harness_version_hash.as_deref(),
                )
            };
            if let Err(error) = metadata_result {
                drop(retry_context_permit.take());
                self.custody_execution_runtime()
                    .settle_bound_retry_failure(
                        session_id,
                        bound,
                        SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                    )
                    .await?;
                complete_invocation(
                    &self.store,
                    admission_permit,
                    InvocationCompletion {
                        error_class: Some("session_metadata_persistence_failed".into()),
                        confidence: Some(ModelUsageConfidence::Unavailable),
                        ..InvocationCompletion::default()
                    },
                    self.event_bus(),
                )
                .await?;
                return Err(error);
            }
        }
        // Drop queues ContextRead settlement through the existing
        // cancellation-safe worker before provider launch; durable SQLite
        // release may complete asynchronously.
        drop(direct_context_permit.take());
        drop(retry_context_permit.take());

        // Launch provider process (synchronous spawn -- fast enough to keep inline).
        // For CodexAppServer, the entire launch (including async JSON-RPC handshake)
        // is deferred to the background tokio::spawn task below. At the outer level,
        // we insert process=None into TrackedSession for CodexAppServer; the background
        // task updates it after the handshake completes.
        //
        // For all CLI providers, process and event_rx are ready synchronously.
        enum SyncLaunchResult {
            /// CLI-based provider: process and event channel ready immediately.
            Cli(
                ProviderProcess,
                tokio::sync::mpsc::Receiver<crate::claude::StreamEvent>,
            ),
            /// App-server provider: entire launch deferred to background task.
            AppServerDeferred,
        }

        // Verify CodexAppServer binary is available before accepting the request.
        #[cfg(test)]
        let codex_app_server_available =
            !take_direct_launch_provider_unavailable_for_test(&direct_test_control_key)
                && (provider != SessionProvider::CodexAppServer
                    || crate::codex_app_server::CodexAppServerClient::is_available()
                    || controller_candidate_test_app_server_binary_is_registered(session_id)
                    || successor_test_app_server_client_failure_is_registered(session_id));
        #[cfg(not(test))]
        let codex_app_server_available = provider != SessionProvider::CodexAppServer
            || crate::codex_app_server::CodexAppServerClient::is_available();
        if !codex_app_server_available {
            if let Some(admission_permit) = direct_admission.as_ref() {
                settle_failed_bound_fresh_pre_provider(
                    &mut launch_purpose,
                    &self.store,
                    self.event_bus(),
                    &self.agent_tokens,
                    session_id,
                    admission_permit,
                    "provider unavailable before launch",
                    "provider_unavailable",
                )
                .await?;
            }
            if let (Some(bound), Some(admission_permit)) =
                (retry_bound.as_ref(), retry_admission_permit.as_ref())
            {
                self.custody_execution_runtime()
                    .settle_bound_retry_failure(
                        session_id,
                        bound,
                        SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                    )
                    .await?;
                complete_invocation(
                    &self.store,
                    admission_permit,
                    InvocationCompletion {
                        error_class: Some("provider_unavailable".into()),
                        confidence: Some(ModelUsageConfidence::Unavailable),
                        ..InvocationCompletion::default()
                    },
                    self.event_bus(),
                )
                .await?;
            }
            return Err(DaemonError::CodexBinaryNotFound);
        }

        tracing::info!(session_id = %session_id, "Launch: requesting model admission");
        let admission_permit = if let Some(permit) = retry_admission_permit.take() {
            permit
        } else if let Some(permit) = direct_admission.take() {
            permit
        } else {
            match crate::model_control::admit_launch_invocation(
                &self.store,
                admission_request.clone(),
                self.event_bus(),
                resource_launch_origin.as_ref(),
            )
            .await?
            {
                AdmissionDecision::Admitted(permit) => permit,
                AdmissionDecision::Duplicate { invocation_id }
                    if launch_purpose.is_agent_successor() =>
                {
                    crate::model_control::resume_unexecuted_agent_successor_admission(
                        &self.store,
                        &admission_request,
                        invocation_id,
                    )
                    .await?
                }
                AdmissionDecision::Duplicate { invocation_id } => {
                    self.revoke_agent_token_for_session(session_id).await;
                    return Err(DaemonError::PolicyDenied(format!(
                        "duplicate model invocation admission blocked backend execution: {invocation_id}"
                    )));
                }
            }
        };
        tracing::info!(session_id = %session_id, "Launch: model admission granted");
        #[cfg(test)]
        if resource_launch_origin.is_some() {
            pause_controller_candidate_test(
                session_id,
                ControllerCandidateTestPhase::FreshChildAfterAdmission,
            )
            .await;
        }

        // Resolve every field of a successor candidate before any provider or
        // backend can execute. The exact row/invocation transaction is the
        // durable incarnation fence: once it exists, reconciliation never
        // dispatches another provider for this reservation.
        let successor_pre_effect = if let Some(context) = launch_purpose.manager_successor() {
            context.refresh().await?;
            let claim = context.claim().await;
            let mut session = direct_session
                .take()
                .expect("root candidate bound before context work");
            let rotation = initialize_session_rotation(
                &mut session,
                initial_rotation_disabled,
                context_rotation_enabled,
            );
            session.rotation_disabled_at =
                claim.reservation.frozen.predecessor.rotation_disabled_at;
            #[cfg(test)]
            pause_controller_candidate_test(
                session_id,
                ControllerCandidateTestPhase::SuccessorAfterDurablePreEffect,
            )
            .await;
            Some((session, rotation))
        } else if let LaunchPurpose::AgentSuccessor(_) = &launch_purpose {
            debug_assert!(retry_session.is_none());
            let mut session = direct_session
                .take()
                .expect("agent successor bound before context work");
            let inherited_rotation_disabled = session.rotation_disabled_at.is_some();
            let rotation = initialize_session_rotation(
                &mut session,
                inherited_rotation_disabled,
                context_rotation_enabled,
            );
            Some((session, rotation))
        } else {
            None
        };

        // Mint/register the authority only after admission, but before any
        // provider can produce a callback. Every confirmed pre-active exit
        // below revokes this prospective binding; an unconfirmed provider
        // termination deliberately retains it with the running admission.
        let session_token = super::remint_agent_token(&self.agent_tokens, session_id).await;
        if let Some(witness) = launch_purpose.prospective_a6() {
            witness.install(session_token.clone()).await;
        }
        config.rsi_session_token = Some(session_token.clone());

        if let Some(selector) = config.closure_selector.as_mut() {
            let custody = self
                .store
                .lock()
                .await
                .live_custody_for_session(session_id)?;
            selector.custody_id = Some(custody.custody_id);
            selector.custody_generation = Some(custody.generation);
            selector.model_invocation_id = Some(admission_permit.invocation_id());
            selector.lineage_root_session_id = Some(session_id);
            let contract = crate::closure_kernel::terminal_contract(selector, session_id, 0)?;
            config.system_prompt = Some(match config.system_prompt.take() {
                Some(existing) => format!("{existing}\n\n{contract}"),
                None => contract,
            });
        }

        if let Some(context) = launch_purpose.manager_action() {
            self.check_manager_action_runtime(
                &context.claim,
                provider != SessionProvider::CodexAppServer,
            )
            .await?;
        }
        if provider != SessionProvider::CodexAppServer
            && let Some(context) = launch_purpose.manager_successor()
        {
            context.claim_effect().await?;
        }
        let sync_launch = if provider == SessionProvider::CodexAppServer {
            // Entire launch deferred to background task (async handshake required).
            SyncLaunchResult::AppServerDeferred
        } else {
            // All CLI providers funnel through the single guarded spawn primitive
            // (`&spawn_guard` is the mandatory single-flight witness). The harness
            // arm captures the freshly resolved project ID here so the
            // `memory_search` tool cannot be widened through tool args (plan §D2);
            // `config.working_dir` already holds the effective (sandbox) cwd, and
            // history is None on a fresh launch.
            let harness_project_id = resolved_project.as_ref().map(|p| p.id);
            let launcher = super::provider_spawn::CachedLauncher {
                mgr: self,
                harness: super::provider_spawn::HarnessLaunchCtx {
                    conversation_history: None,
                    project_id: harness_project_id,
                    initial_admission_permit: admission_permit.clone(),
                    model_call_settlements: model_call_settlements.clone(),
                    resolved_context_budget: launch_context_budget.clone(),
                },
            };
            tracing::info!(session_id = %session_id, ?provider, "Launch: spawning provider process");
            #[cfg(test)]
            observe_provider_config_for_test(session_id, &config);
            #[cfg(test)]
            inject_final_scratch_drift_for_test(&direct_test_control_key, false, &config);
            #[cfg(test)]
            if authenticated_retry {
                observe_retry_config_for_test(session_id, &config);
            }
            if let LaunchPurpose::AgentSuccessor(context) = &launch_purpose {
                let effect_fence = {
                    let store = self.store.lock().await;
                    store.validate_agent_successor_provider_effect_fence(
                        &context.reservation,
                        admission_permit.invocation_id(),
                    )
                };
                if let Err(error) = effect_fence {
                    settle_rejected_agent_successor_provider_effect(
                        context,
                        &self.store,
                        self.event_bus(),
                        &self.agent_tokens,
                        &admission_permit,
                    )
                    .await;
                    return Err(error);
                }
            }
            #[cfg(test)]
            let launch_result =
                if authenticated_retry && take_retry_provider_failure_for_test(session_id) {
                    Err(DaemonError::Process(
                        "injected retry provider spawn failure".into(),
                    ))
                } else {
                    take_successor_task_provider_test_process(session_id, provider)
                        .or_else(|| take_controller_candidate_test_process(session_id))
                        .map_or_else(
                            || {
                                super::provider_spawn::spawn_provider_process(
                                    provider,
                                    &config,
                                    &launcher,
                                    &admission_permit,
                                    &spawn_guard,
                                )
                            },
                            Ok,
                        )
                };
            #[cfg(not(test))]
            let launch_result = super::provider_spawn::spawn_provider_process(
                provider,
                &config,
                &launcher,
                &admission_permit,
                &spawn_guard,
            );
            let (process, event_rx) = match launch_result {
                Ok(pair) => pair,
                Err(error) => {
                    let execution_scratch_failure =
                        matches!(&error, DaemonError::ExecutionScratchUnavailable(_));
                    let safe_error_class = if execution_scratch_failure {
                        "execution_scratch_unavailable"
                    } else {
                        "provider_spawn_failed"
                    };
                    if launch_purpose.manager_successor().is_some() {
                        // Even a failed establishment may have spawned an OS
                        // cohort. The root owner proves drain before releasing
                        // this invocation/capacity, outside the launch guards.
                        return Err(error);
                    }
                    if direct_interactive {
                        settle_failed_bound_fresh_pre_provider(
                            &mut launch_purpose,
                            &self.store,
                            self.event_bus(),
                            &self.agent_tokens,
                            session_id,
                            &admission_permit,
                            if execution_scratch_failure {
                                "execution scratch revalidation failed before provider dispatch"
                            } else {
                                "provider spawn failed before establishment"
                            },
                            safe_error_class,
                        )
                        .await?;
                        self.revoke_agent_token_for_session(session_id).await;
                        return Err(error);
                    }
                    if let Some(bound) = retry_bound.as_ref()
                        && let Err(settlement_error) = self
                            .custody_execution_runtime()
                            .settle_bound_retry_failure(
                                session_id,
                                bound,
                                SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                            )
                            .await
                    {
                        tracing::warn!(session_id=%session_id, error=%settlement_error, "failed to settle bound retry provider-spawn failure");
                    }
                    if let Err(settle_error) = complete_invocation(
                        &self.store,
                        &admission_permit,
                        InvocationCompletion {
                            error_class: Some(
                                if execution_scratch_failure {
                                    "execution_scratch_unavailable"
                                } else {
                                    "spawn_failed"
                                }
                                .to_string(),
                            ),
                            confidence: Some(ModelUsageConfidence::Unavailable),
                            ..InvocationCompletion::default()
                        },
                        self.event_bus(),
                    )
                    .await
                    {
                        tracing::warn!(
                            error = %settle_error,
                            session_id = %session_id,
                            "Failed to settle fresh launch admission after spawn error"
                        );
                    }
                    self.revoke_agent_token_for_session(session_id).await;
                    return Err(error);
                }
            };
            tracing::info!(session_id = %session_id, "Launch: provider process spawned");
            #[cfg(test)]
            if launch_purpose.is_agent_successor() || launch_purpose.manager_successor().is_some() {
                pause_controller_candidate_test(
                    session_id,
                    ControllerCandidateTestPhase::SuccessorAfterSyncProviderStart,
                )
                .await;
            }
            SyncLaunchResult::Cli(process, event_rx)
        };

        // Destructure sync_launch into (process, event_rx) once.
        // For CodexAppServer: process=None (set in background task), event_rx=None.
        let (mut initial_process, cli_event_rx): (
            Option<ProviderProcess>,
            Option<tokio::sync::mpsc::Receiver<crate::claude::StreamEvent>>,
        ) = match sync_launch {
            SyncLaunchResult::Cli(p, rx) => (Some(p), Some(rx)),
            SyncLaunchResult::AppServerDeferred => (None, None),
        };
        let (stop_tx, stop_rx) = mpsc::channel(1);

        let (session, rotation) = match successor_pre_effect {
            Some(prepared) => prepared,
            None => {
                // Direct launches finalized these fields before provider
                // execution. Keep raw Git/hash work on the unchanged
                // non-direct path only.
                let (git_branch, harness_version_hash) =
                    if direct_interactive || authenticated_retry {
                        (None, None)
                    } else {
                        let git_branch = std::process::Command::new("git")
                            .args(["rev-parse", "--abbrev-ref", "HEAD"])
                            .current_dir(&effective_working_dir)
                            .output()
                            .ok()
                            .filter(|o| o.status.success())
                            .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string());
                        let harness_version_hash = Some(compute_harness_version_hash(
                            config.system_prompt.as_deref(),
                            &config.query,
                            Some(config.session_kind.unwrap_or_default()),
                        ));
                        (git_branch, harness_version_hash)
                    };

                // Build session with explicit project_id if provided (path
                // resolution may override).
                let mut session = direct_session.or(retry_session).unwrap_or_else(|| {
                    build_starting_session(
                        &config,
                        session_id,
                        provider,
                        &working_dir,
                        resolved_project_id,
                        session_kind,
                        configured_max_retries,
                        default_max_retries,
                        allocation.as_ref(),
                        git_branch,
                        harness_version_hash,
                        context_rotation_enabled,
                    )
                });
                install_context_budget(&mut session, launch_context_budget.clone());
                if let Some(admission) = retry_admission.as_ref() {
                    debug_assert_eq!(session.continued_from, Some(admission.parent_session_id));
                    session.retry_attempt = Some(admission.retry_attempt);
                    session.max_retries = Some(admission.max_retries);
                }
                let rotation = initialize_session_rotation(
                    &mut session,
                    initial_rotation_disabled,
                    context_rotation_enabled,
                );
                (session, rotation)
            }
        };

        // P1.6: debug log for workflow_id_override wired but not consumed at execution time
        if let Some(override_id) = session.workflow_id_override {
            tracing::debug!(
                session_id = %session.id,
                workflow_id_override = %override_id,
                "P1.6: workflow_id_override wired but not yet consumed at execution time (Phase 5)"
            );
        }

        // A retry/rotation successor is not a valid recovery owner until its
        // `continued_from` link is durable. Scheduled Fresh children that
        // inherit disabled rotation likewise need their persisted state before
        // becoming active. Direct interactive launches committed their custody
        // and model binding before any context or provider effect above;
        // successor candidates committed their exact row/invocation boundary
        // before token mint and provider dispatch above.
        let row_is_durable_before_active = direct_interactive
            || session.continued_from.is_some()
            || initial_rotation_disabled
            || launch_purpose.is_controller_candidate()
            || launch_purpose.is_agent_successor()
            || launch_purpose.agent_child().is_some();
        if row_is_durable_before_active {
            let admission_result = if direct_interactive {
                Ok(())
            } else if retry_admission.is_some() {
                // The authenticated retry path committed C5 and custody before
                // ContextRead/config/provider work above.
                Ok(())
            } else {
                if launch_purpose.is_agent_successor()
                    || launch_purpose.manager_successor().is_some()
                {
                    Ok(())
                } else if initial_rotation_disabled {
                    persist_scheduled_fresh_disabled_row_before_active(
                        &self.store,
                        &session,
                        &admission_permit,
                    )
                    .await
                } else if launch_purpose.is_controller_candidate() {
                    self.store
                        .lock()
                        .await
                        .insert_session_with_model_invocation(
                            &session,
                            admission_permit.invocation_id(),
                        )
                } else if let Some(context) = launch_purpose.agent_child() {
                    // H1-04 (F-011): the forked child binds its independent
                    // generation-1 root (cause agent_spawn_child) in the same
                    // transaction that admits the child row and settles the
                    // spawn reservation. A sandbox-less (test-constructed)
                    // request stays an ordinary binding.
                    let binding = match allocation.as_ref() {
                        Some(allocation) => new_root_binding_from_allocation(
                            allocation,
                            &working_dir,
                            allocation_source_commit.as_deref(),
                            CustodyCause::AgentSpawnChild,
                            // Forked agent children always mint a fresh
                            // custody identity; closure adoption never
                            // applies on this path.
                            None,
                        ),
                        None => Ok(SessionCustodyBinding::Ordinary),
                    };
                    match binding {
                        Ok(binding) => self.store.lock().await.admit_agent_child_session(
                            &session,
                            admission_permit.invocation_id(),
                            context.spawn_request_id,
                            context.owner_session_id,
                            binding,
                        ),
                        // Fold into admission_result so the shared failure
                        // path below still stops the spawned provider.
                        Err(error) => Err(error),
                    }
                } else {
                    self.store.lock().await.insert_session(&session)
                }
            };
            if let Err(error) = admission_result {
                if initial_rotation_disabled {
                    return Err(cleanup_failed_scheduled_fresh_before_active(
                        &self.store,
                        &self.agent_tokens,
                        session_id,
                        &admission_permit,
                        self.event_bus(),
                        &mut initial_process,
                        error,
                    )
                    .await?);
                }

                // The provider may already be spawned for CLI backends. The
                // successor path cannot reach this branch because its exact
                // candidate row was committed before provider dispatch;
                // app-server launch remains deferred at this point.
                let provider_terminated = match initial_process.as_mut() {
                    Some(process) => match process.kill().await {
                        Ok(()) => {
                            tokio::task::yield_now().await;
                            !process.is_alive()
                        }
                        Err(kill_error) => {
                            tracing::error!(
                                session_id = %session_id,
                                error = %kill_error,
                                "Failed to stop unadmitted retry successor after admission failure"
                            );
                            false
                        }
                    },
                    // App-server launch is deferred, so no provider is live
                    // before active publication on this branch.
                    None => true,
                };
                if provider_terminated {
                    self.revoke_agent_token_for_session(session_id).await;
                }
                return Err(error);
            }
        }
        #[cfg(test)]
        if launch_purpose.is_controller_candidate() {
            pause_controller_candidate_test(
                session_id,
                ControllerCandidateTestPhase::AfterDurablePersistence,
            )
            .await;
        }

        let spawn_generation = self.next_spawn_generation();
        if let Some(context) = launch_purpose.manager_successor() {
            context
                .generation
                .store(spawn_generation, Ordering::Release);
        }
        if let Some(context) = launch_purpose.manager_action() {
            context
                .generation
                .store(spawn_generation, Ordering::Release);
        }
        let tracked = TrackedSession {
            session: session.clone(),
            spawn_generation,
            events: Vec::new(),
            turn_metrics: Vec::new(),
            process: initial_process,
            deferred_successor_start_gate: (provider == SessionProvider::CodexAppServer
                && (launch_purpose.is_agent_successor()
                    || launch_purpose.manager_successor().is_some()
                    || launch_purpose.manager_action().is_some()))
            .then(|| Arc::new(tokio::sync::Mutex::new(()))),
            stop_tx,
            interrupt_requested: false,
            pending_archive: false,
            rotation,
            live_input_tokens: 0,
            live_output_tokens: 0,
            live_usage_confidence: rsi_common::types::ContextUsageConfidence::Missing,
            daemon_input_tokens: 0,
            daemon_output_tokens: 0,
            daemon_tokens_at_last_api_update: 0,
            codex_context_tokens: 0,
            pipeline_artifact: None,
            memory_flush_compaction_count: None,
            pending_question: None,
            approval_wait_start: None,
            approval_wait_total_ms: 0,
            work_run_start: None,
            work_time_base_ms: 0,
            received_meaningful_output: false,
            exit_code: None,
            retry_attempt: retry_admission
                .as_ref()
                .map_or(0, |admission| admission.retry_attempt),
            // Explicit max_retries in params takes priority; fall back to kind-scoped default.
            max_retries: retry_admission.as_ref().map_or_else(
                || configured_max_retries.unwrap_or(default_max_retries),
                |admission| admission.max_retries,
            ),
            last_event_at: chrono::Utc::now(),
            stall_interrupted: false,
            last_usage_update: None,
            last_mismatch_warn: None,
            last_classified_at: None,
            classification_count: 0,
            last_verdict: None,
        };

        // Point of no return: the session is now reachable via `active` (and
        // GetSession), so an allocated sandbox is no longer orphaned even
        // though durable SQLite persistence is still pending (background
        // work below). Disarm before the in-memory insert so a session that
        // IS visible is never torn down out from under it by something
        // dropped after this point.
        sandbox_guard.disarm();
        self.active.write().await.insert(session_id, tracked);
        self.event_bus.publish(DaemonEvent::SessionCreated {
            session: session.clone(),
        });
        let manager_successor_context = launch_purpose.manager_successor().cloned();
        let deferred_agent_child_context = launch_purpose.agent_child().cloned();
        // Root authority is published only while these actual launch guards
        // remain held, including the deferred handshake and failed-start cleanup.
        let (launch_spawn_guard, mut manager_successor_guards) =
            if manager_successor_context.is_some() {
                (None, Some((spawn_guard, cwd_admission_guard)))
            } else {
                drop(cwd_admission_guard);
                (Some(spawn_guard), None)
            };

        let manager_action_context = launch_purpose.manager_action().cloned();
        let suppress_generic_lead_promotion = launch_purpose.is_agent_successor()
            || manager_action_context.is_some()
            || manager_successor_context.is_some();
        let (mut controller_launch_context, mut successor_launch_context) = match launch_purpose {
            LaunchPurpose::ControllerCandidate(context) => (Some(context), None),
            LaunchPurpose::AgentSuccessor(context) => (None, Some(context)),
            LaunchPurpose::Interactive
            | LaunchPurpose::AgentChild(_)
            | LaunchPurpose::ClosureSource(_)
            | LaunchPurpose::ManagerAction(_)
            | LaunchPurpose::TopologyNode(_)
            | LaunchPurpose::ManagerSuccessor(_) => (None, None),
        };
        if provider != SessionProvider::CodexAppServer
            && let Some(context) = controller_launch_context.as_mut()
        {
            #[cfg(test)]
            pause_controller_candidate_test(
                session_id,
                ControllerCandidateTestPhase::BeforeConfirmation,
            )
            .await;
            let confirmation_kind = {
                let mut active = self.active.write().await;
                active
                    .get_mut(&session_id)
                    .and_then(|tracked| tracked.process.as_mut())
                    .and_then(|process| {
                        super::provider_spawn::installed_provider_confirmation(provider, process)
                    })
            };
            if let Some(confirmation_kind) = confirmation_kind {
                let _ = signal_controller_candidate_confirmation(
                    context,
                    &self.store,
                    &self.agent_tokens,
                    provider,
                    admission_permit.invocation_id(),
                    confirmation_kind,
                )
                .await;
            } else {
                context.confirmation_tx.take();
            }
        }
        if provider != SessionProvider::CodexAppServer
            && let Some(context) = successor_launch_context.as_mut()
        {
            let confirmation_kind = {
                let mut active = self.active.write().await;
                active
                    .get_mut(&session_id)
                    .and_then(|tracked| tracked.process.as_mut())
                    .and_then(|process| {
                        super::provider_spawn::installed_provider_confirmation(provider, process)
                    })
            };
            if let Some(confirmation_kind) = confirmation_kind {
                let _ = signal_agent_successor_confirmation(
                    context,
                    &self.store,
                    &self.agent_tokens,
                    provider,
                    admission_permit.invocation_id(),
                    confirmation_kind,
                )
                .await;
            } else {
                context.confirmation_tx.take();
            }
        }

        if !suppress_generic_lead_promotion
            && let Some(parent_id) = session.parent_id
            && let Err(e) = self
                .try_auto_promote_epic_lead(parent_id, &session, launch_spawn_guard.as_ref())
                .await
        {
            tracing::warn!(
                session_id = %session_id,
                parent_id = %parent_id,
                error = %e,
                "Failed to auto-promote first Epic child lead"
            );
        }

        // === RPC responds here -- everything below is background work ===

        let store = Arc::clone(&self.store);
        let persistence = self.persistence.clone();
        let active = Arc::clone(&self.active);
        let completed = Arc::clone(&self.completed);
        let event_bus = Arc::clone(&self.event_bus);
        let socket_path = self.socket_path.clone();
        let query_for_event = config.query.clone();
        let counter = Arc::clone(&self.token_counter);
        let memory_handle = self.memory_handle.clone();
        let retry_tx = self.retry_tx.clone();
        // Build a per-session tool registry so `rsi_memory_search` is
        // bound to this session's project scope (plan §D2). The agent
        // cannot widen the scope through tool args — the schema does
        // not expose project_id.
        let tool_registry = {
            let mut registry = crate::tool_registry::ToolRegistry::new();
            crate::tool_registry::register_builtin_tools(
                &mut registry,
                memory_handle.clone(),
                resolved_project_id,
                Some(self.agent_control()),
                config.rsi_session_id,
            );
            if let (Some(handle), Some(project_id), Some(session_id)) = (
                &self.codegraph_handle,
                resolved_project_id,
                config.rsi_session_id,
            ) {
                let root = session
                    .sandbox_root
                    .as_ref()
                    .unwrap_or(&session.working_dir);
                if let Some(binding) =
                    crate::codegraph::NativeCodegraphBinding::for_launch(handle, project_id, root)
                {
                    crate::tool_registry::register_codegraph_tools(
                        &mut registry,
                        handle.clone(),
                        Arc::clone(&self.store),
                        session_id,
                        binding,
                    );
                }
            }
            Arc::new(registry)
        };
        let runtime_config = Arc::clone(&self.runtime_config);
        let spawn_coordinator = Arc::clone(&self.spawn_coordinator);
        let app_server_control = Arc::clone(&self.app_server_control);
        let agent_tokens = Arc::clone(&self.agent_tokens);
        let spawn_epoch = Arc::clone(&self.spawn_epoch);
        let agent_message_arbiter = Arc::clone(&self.agent_message_arbiter);
        let codegraph_handle = self.codegraph_handle.clone();
        let custody_runtime = self.custody_execution_runtime();
        // Extra clones for title generation nested task
        let persistence_for_title = persistence.clone();
        let active_for_title = Arc::clone(&active);
        let completed_for_title = Arc::clone(&completed);
        let store_for_title = self.store.clone();
        let config_session_kind = config.session_kind.unwrap_or_default();
        let should_generate_title = super::title::should_enqueue_initial_title_generation(
            config_session_kind,
            config.parent_id,
            config.agent_role.as_deref(),
            config.epic_spawn_ordinal,
        );
        // Lead authority is resolved here, after the auto-promotion above, so a
        // session that leads a container is titled for that authority rather
        // than for the craft named in its prompt.
        let title_forced_role = super::title::forced_role_for_session(
            &self.active,
            &self.completed,
            &self.store,
            session_id,
            session.parent_id,
        )
        .await;
        let admission_permit_for_task = admission_permit.clone();
        let exact_launch_token_for_task = session_token;
        #[cfg(test)]
        let deferred_test_control_key = direct_test_control_key.clone();

        tokio::spawn(async move {
            let root_exit = manager_successor_context.clone();
            let task = async {
                // Project was pre-resolved synchronously for the context pipeline.
                // Just apply it to the session if not already set.
                let project_id = resolved_project_id;
                if let Some(project_id) = project_id {
                    let mut active_guard = active.write().await;
                    if let Some(tracked) = active_guard.get_mut(&session_id) {
                        tracked.session.project_id = Some(project_id);
                    }
                }

                // 1b. Workflow propagation
                // (NOTE: previously, /research launches created a workflow row here.
                //  That path produced ~84 junk rows where the title was the raw session
                //  prompt. Disabled in P1.13. The bridge upserts workflow rows now
                //  (P1.12), so /research no longer needs to.)
                {
                    let query_clean = query_for_event.trim_start_matches('/');
                    // For pipeline commands with a workflow_id, advance the workflow stage.
                    let current_workflow_id = {
                        let active_guard = active.read().await;
                        active_guard
                            .get(&session_id)
                            .and_then(|t| t.session.workflow_id)
                    };
                    if let Some(wf_id) = current_workflow_id {
                        let new_stage = if query_clean.starts_with("plan") {
                            Some(WorkflowStage::Planning)
                        } else if query_clean.starts_with("implement") {
                            Some(WorkflowStage::Implementing)
                        } else {
                            None
                        };
                        if let Some(stage) = new_stage {
                            if let Err(e) =
                                persistence.update_workflow_stage(wf_id, stage, None).await
                            {
                                tracing::warn!(error = %e, workflow_id = %wf_id, "Failed to advance workflow stage on launch");
                            } else {
                                tracing::info!(workflow_id = %wf_id, ?stage, "Advanced workflow stage on pipeline command launch");
                            }
                        }
                    }
                }

                // 2. Persist session to SQLite
                {
                    let session_for_db = {
                        let active_guard = active.read().await;
                        active_guard.get(&session_id).map(|t| t.session.clone())
                    };
                    if let Some(session_clone) = session_for_db {
                        if !row_is_durable_before_active {
                            let store_ref = store.clone();
                            let invocation_id = admission_permit_for_task.invocation_id();
                            let session_for_insert = session_clone.clone();
                            match tokio::task::spawn_blocking(move || {
                                let store = store_ref.blocking_lock();
                                store.insert_session_with_model_invocation(
                                    &session_for_insert,
                                    invocation_id,
                                )
                            })
                            .await
                            {
                                Ok(Ok(())) => {}
                                Ok(Err(e)) => {
                                    tracing::error!(
                                        error = %e,
                                        session_id = %session_id,
                                        "Failed to persist session row with active model invocation"
                                    );
                                }
                                Err(e) => {
                                    tracing::error!(
                                        error = %e,
                                        session_id = %session_id,
                                        "Failed to join session persistence task"
                                    );
                                }
                            }
                        }

                        // Create initial model segment for new sessions
                        if let Some(ref model) = session_clone.model {
                            let store_ref = store.clone();
                            let sid = session_id;
                            let m = model.clone();
                            if let Err(e) = tokio::task::spawn_blocking(move || {
                                let store = store_ref.blocking_lock();
                                store.create_model_segment(sid, &m, 0)
                            })
                            .await
                            {
                                tracing::warn!(
                                    session_id = %session_id,
                                    error = %e,
                                    "Failed to create initial model segment"
                                );
                            }
                        }
                    }
                }

                // 3. Create synthetic user event
                let user_event = Self::create_user_event(session_id, 1, &query_for_event);
                {
                    let mut active_guard = active.write().await;
                    if let Some(tracked) = active_guard.get_mut(&session_id) {
                        tracked.events.push(user_event.clone());
                    }
                }

                // 4. Persist user event
                match persistence.insert_event(user_event.clone()).await {
                    Ok(db_id) => {
                        let mut active_guard = active.write().await;
                        if let Some(tracked) = active_guard.get_mut(&session_id)
                            && let Some(last_event) = tracked.events.last_mut()
                        {
                            last_event.id = db_id;
                        }
                    }
                    Err(e) => {
                        tracing::error!(
                            error = %e,
                            session_id = %session_id,
                            "Failed to persist synthetic user event"
                        );
                    }
                }

                // 5. Publish events
                event_bus.publish(DaemonEvent::SessionStatusChanged {
                    session_id,
                    old_status: SessionStatus::Starting,
                    new_status: SessionStatus::Starting,
                });
                event_bus.publish(DaemonEvent::ConversationEvent {
                    session_id,
                    event: user_event,
                });

                // Count initial query tokens for daemon-side tracking
                {
                    let query_tokens = counter.count(&query_for_event);
                    let mut active_guard = active.write().await;
                    if let Some(tracked) = active_guard.get_mut(&session_id) {
                        tracked.daemon_input_tokens += query_tokens;
                        tracked.session.daemon_input_tokens = Some(tracked.daemon_input_tokens);
                    }
                }

                // 5.5 Spawn title generation as a separate task (don't block monitor start)
                // Root succession preserves the manager's identity. An ancillary
                // title invocation must not race its exact establishment ledger.
                if manager_successor_context.is_none() && should_generate_title {
                    let query_for_title = query_for_event.clone();
                    let persistence_title = persistence_for_title.clone();
                    let active_title = active_for_title.clone();
                    let completed_title = completed_for_title.clone();
                    let ollama_model = runtime_config.title_model_local.read().clone();
                    let fallback_model = runtime_config.title_model_fallback.read().clone();
                    let title_provider = *runtime_config.title_model_provider.read();
                    let title_base_url = runtime_config.title_model_base_url.read().clone();
                    let title_api_key = runtime_config.title_model_api_key.read().clone();
                    let title_event_bus = Arc::clone(&event_bus);
                    tokio::spawn(async move {
                        match generate_title_and_description(
                            &store_for_title,
                            &title_event_bus,
                            session_id,
                            &query_for_title,
                            None,
                            title_forced_role,
                            &ollama_model,
                            &fallback_model,
                            title_provider,
                            title_base_url,
                            title_api_key,
                        )
                        .await
                        {
                            Ok(result) => {
                                // Generated enrichment may fill an absent title
                                // but never replaces an explicit one. The
                                // durable row is the arbiter, so the projection
                                // is only advanced when the store accepted the
                                // fill. Writing the projection unconditionally
                                // would show a generated title in the session
                                // list while the row still held the explicit one.
                                let filled = match persistence_title
                                    .fill_session_title_if_absent(session_id, result.title.clone())
                                    .await
                                {
                                    Ok(filled) => filled,
                                    Err(e) => {
                                        tracing::warn!(
                                            error = %e,
                                            session_id = %session_id,
                                            "Failed to persist generated title"
                                        );
                                        false
                                    }
                                };
                                if filled {
                                    if let Some(tracked) =
                                        active_title.write().await.get_mut(&session_id)
                                    {
                                        tracked.session.title = Some(result.title.clone());
                                    }
                                    if let Some(completed) =
                                        completed_title.write().await.get_mut(&session_id)
                                    {
                                        completed.session.title = Some(result.title.clone());
                                    }
                                }
                                if !result.description.is_empty() {
                                    if let Some(tracked) =
                                        active_title.write().await.get_mut(&session_id)
                                    {
                                        tracked.session.description =
                                            Some(result.description.clone());
                                    }
                                    if let Some(completed) =
                                        completed_title.write().await.get_mut(&session_id)
                                    {
                                        completed.session.description =
                                            Some(result.description.clone());
                                    }
                                    if let Err(e) = persistence_title
                                        .update_session_description(session_id, result.description)
                                        .await
                                    {
                                        tracing::warn!(
                                            error = %e,
                                            session_id = %session_id,
                                            "Failed to persist generated description"
                                        );
                                    }
                                }
                            }
                            Err(e) => {
                                tracing::warn!(
                                    error = %e,
                                    session_id = %session_id,
                                    "Failed to generate title and description"
                                );
                            }
                        }
                    });
                }

                // 6. Start monitor
                // For CLI providers: wrap the event_rx in a CliProviderSession.
                // For CodexAppServer: launch the async handshake and get the provider session directly.
                let provider_session: Box<dyn crate::provider::ProviderSession> = if let Some(
                    event_rx,
                ) =
                    cli_event_rx
                {
                    Box::new(crate::provider::CliProviderSession::new(event_rx))
                } else {
                    // CodexAppServer: launch async (process spawn + JSON-RPC handshake)
                    #[cfg(test)]
                    if successor_launch_context.is_some()
                        || manager_action_context.is_some()
                        || manager_successor_context.is_some()
                    {
                        pause_controller_candidate_test(
                            session_id,
                            ControllerCandidateTestPhase::SuccessorBeforeDeferredProviderStart,
                        )
                        .await;
                    }
                    #[cfg(test)]
                    let app_server_client = if take_successor_test_app_server_client_failure(
                        session_id,
                    ) {
                        Err(DaemonError::CodexBinaryNotFound)
                    } else {
                        match take_controller_candidate_test_app_server_binary(session_id) {
                    Some(binary_path) => crate::codex_app_server::CodexAppServerClient::new_after_admission_with_test_binary(
                        &store,
                        &event_bus,
                        &admission_permit_for_task,
                        binary_path,
                    )
                    .await,
                    None => crate::codex_app_server::CodexAppServerClient::new_after_admission(
                        &store,
                        &event_bus,
                        &admission_permit_for_task,
                    )
                    .await,
                }
                    };
                    #[cfg(not(test))]
                    let app_server_client =
                        crate::codex_app_server::CodexAppServerClient::new_after_admission(
                            &store,
                            &event_bus,
                            &admission_permit_for_task,
                        )
                        .await;
                    let app_server_client = match app_server_client {
                        Ok(c) => c,
                        Err(e) => {
                            if let Some(bound) = retry_bound.as_ref() {
                                let _ = custody_runtime
                                    .settle_bound_retry_failure(
                                        session_id,
                                        bound,
                                        SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                                    )
                                    .await;
                                let _ = complete_invocation(
                                    &store,
                                    &admission_permit_for_task,
                                    InvocationCompletion {
                                        error_class: Some(
                                            "codex_app_server_client_failed".to_string(),
                                        ),
                                        confidence: Some(ModelUsageConfidence::Unavailable),
                                        ..InvocationCompletion::default()
                                    },
                                    &event_bus,
                                )
                                .await;
                                super::revoke_agent_tokens_for_session(&agent_tokens, session_id)
                                    .await;
                            }
                            if let Some(context) = successor_launch_context.as_mut() {
                                settle_failed_deferred_agent_successor(
                                context,
                                &active,
                                &store,
                                &event_bus,
                                &agent_tokens,
                                &admission_permit_for_task,
                                spawn_generation,
                                "CodexAppServer client creation failed before successor establishment",
                                "agent_successor_codex_app_server_client_failed",
                            )
                            .await;
                            }
                            if let Some(context) = manager_action_context.as_ref() {
                                settle_failed_deferred_manager_action(
                                    context,
                                    &active,
                                    &store,
                                    &event_bus,
                                    &agent_tokens,
                                    &admission_permit_for_task,
                                    spawn_generation,
                                    "manager_v2_deferred_client_failed",
                                )
                                .await;
                            }
                            tracing::error!(session_id = %session_id, error = %e, "Failed to create CodexAppServerClient");
                            return;
                        }
                    };
                    let tool_specs = tool_registry.tool_specs();
                    let turn_control: Arc<dyn ModelCallControl> =
                    Arc::new(StoreBackedModelCallControl::new(
                        Arc::clone(&store),
                        Arc::clone(&event_bus),
                        model_call_settlements.clone(),
                        rsi_common::model_control::InvocationOwner {
                            session_id: Some(session_id),
                            project_id: resolved_project_id,
                            ..Default::default()
                        },
                        "CodexAppServer",
                        config.model.clone(),
                        "CodexAppServer",
                        config.effort.clone(),
                        "codex_app_server",
                        admission_permit_for_task.clone(),
                        rsi_common::model_control::ModelInvocationPurpose::SessionCodexAppServerTurn,
                        None,
                        crate::model_control::registry::RuntimeExecutionRoute::CodexAppServer,
                    ));
                    let deferred_successor_start_permit = if successor_launch_context.is_some()
                        || manager_action_context.is_some()
                        || manager_successor_context.is_some()
                    {
                        match acquire_deferred_successor_start_permit(
                            &active,
                            session_id,
                            spawn_generation,
                        )
                        .await
                        {
                            Ok(permit) => Some(permit),
                            Err(rejection) => {
                                if let Some(context) = successor_launch_context.as_mut() {
                                    settle_failed_deferred_agent_successor(
                                        context,
                                        &active,
                                        &store,
                                        &event_bus,
                                        &agent_tokens,
                                        &admission_permit_for_task,
                                        spawn_generation,
                                        rejection.reason(),
                                        rejection.safe_error_class(),
                                    )
                                    .await;
                                }
                                tracing::info!(
                                    session_id = %session_id,
                                    ?rejection,
                                    "Cancelled deferred successor before provider effect"
                                );
                                return;
                            }
                        }
                    } else {
                        None
                    };
                    if let Some(context) = successor_launch_context.as_mut() {
                        let effect_fence = {
                            let store = store.lock().await;
                            store.validate_agent_successor_provider_effect_fence(
                                &context.reservation,
                                admission_permit_for_task.invocation_id(),
                            )
                        };
                        if let Err(error) = effect_fence {
                            drop(deferred_successor_start_permit);
                            settle_failed_deferred_agent_successor(
                                context,
                                &active,
                                &store,
                                &event_bus,
                                &agent_tokens,
                                &admission_permit_for_task,
                                spawn_generation,
                                "durable successor provider-effect fence rejected",
                                "agent_successor_provider_effect_fence_rejected",
                            )
                            .await;
                            tracing::warn!(
                                session_id = %session_id,
                                error = %error,
                                "Rejected stale deferred successor provider effect"
                            );
                            return;
                        }
                    }
                    if let Some(context) = manager_action_context.as_ref() {
                        let source_fence = super::manager_actions::manager_action_source_gate(
                            &custody_runtime,
                            &store,
                            &context.claim,
                        )
                        .await;
                        let fence = if source_fence.is_err() {
                            source_fence
                        } else if matches!(
                            context.claim.action(),
                            rsi_common::harness_manager_v2::ManagerActionV2::RetryLead { .. }
                        ) && !runtime_config
                            .retry_enabled
                            .load(std::sync::atomic::Ordering::Relaxed)
                        {
                            Err(DaemonError::InvalidParam(
                                "manager_v2_retry_disabled".into(),
                            ))
                        } else {
                            store
                                .lock()
                                .await
                                .manager_action_runtime_gate(&context.claim, true)
                        };
                        if let Err(error) = fence {
                            drop(deferred_successor_start_permit);
                            tracing::warn!(session_id=%session_id, error=%error, "manager deferred provider fence rejected");
                            settle_failed_deferred_manager_action(
                                context,
                                &active,
                                &store,
                                &event_bus,
                                &agent_tokens,
                                &admission_permit_for_task,
                                spawn_generation,
                                super::manager_actions::safe_action_error(&error),
                            )
                            .await;
                            return;
                        }
                    }
                    // The ONE intentional provider spawn that does NOT go through
                    // `provider_spawn::spawn_provider_process`. It is async/deferred and
                    // shape-incompatible: it returns `(CodexAppServerProcess, impl
                    // ProviderSession)` rather than the primitive's `(ProviderProcess,
                    // event_rx)`, and the process is installed into `TrackedSession`
                    // after the fact. It is structurally safe without a new guard —
                    // this fresh-UUID launch is the session's sole spawner — and adding
                    // `acquire_spawn_guard(session_id)` here would contend with the
                    // outer `launch_session` guard on the same id (an observable change,
                    // forbidden). See the plan's App-server exception.
                    if let Some(context) = manager_successor_context.as_ref() {
                        if let Err(error) = context.claim_effect().await {
                            context.remember_refusal(&error);
                            tracing::warn!(%error, "manager succession deferred effect refused");
                            return;
                        }
                    }
                    let manager_gate_context = manager_successor_context.clone();
                    #[cfg(test)]
                    inject_final_scratch_drift_for_test(&deferred_test_control_key, true, &config);
                    match app_server_client
                        .launch_with_gate(
                            &config,
                            admission_permit_for_task.invocation_id(),
                            &tool_specs,
                            &turn_control,
                            app_server_control,
                            move |_checkpoint| {
                                let context = manager_gate_context.clone();
                                async move {
                                    #[cfg(test)]
                                    if context.is_some() && _checkpoint == crate::codex_app_server::AppServerLaunchGate::BeforeThreadAdmission {
                                        pause_controller_candidate_test(session_id, ControllerCandidateTestPhase::ManagerAfterDeferredInitialize).await;
                                    }
                                    if let Some(context) = context {
                                        context.source_gate().await?;
                                    }
                                    Ok(())
                                }
                            },
                        )
                        .await
                    {
                        Ok((as_process, as_session)) => {
                            #[cfg(test)]
                            let mut as_process = as_process;
                            #[cfg(test)]
                            if let Some(control) =
                                take_successor_deferred_provider_test_control(session_id)
                            {
                                control
                                    .productive_start_count
                                    .fetch_add(1, Ordering::SeqCst);
                                pause_controller_candidate_test(
                                session_id,
                                ControllerCandidateTestPhase::SuccessorAfterDeferredProviderStart,
                            )
                            .await;
                                if control.fail_after_start {
                                    if let Err(error) = as_process.kill().await {
                                        tracing::warn!(
                                            session_id = %session_id,
                                            error = %error,
                                            "Failed to stop injected post-start deferred successor"
                                        );
                                    }
                                    drop(deferred_successor_start_permit);
                                    if let Some(context) = successor_launch_context.as_mut() {
                                        settle_failed_deferred_agent_successor(
                                            context,
                                            &active,
                                            &store,
                                            &event_bus,
                                            &agent_tokens,
                                            &admission_permit_for_task,
                                            spawn_generation,
                                            "injected CodexAppServer failure after provider start",
                                            "agent_successor_codex_app_server_post_start_failed",
                                        )
                                        .await;
                                    }
                                    return;
                                }
                            }
                            let mut as_process = Some(as_process);
                            // Install the process before releasing the exact
                            // per-incarnation start gate. An interrupt that lost
                            // the gate race cannot acknowledge until this handle
                            // is visible and therefore killable.
                            let installed = {
                                let mut active_guard = active.write().await;
                                match active_guard.get_mut(&session_id) {
                                    Some(tracked)
                                        if tracked.spawn_generation == spawn_generation
                                            && !tracked.interrupt_requested
                                            && deferred_successor_start_permit
                                                .as_ref()
                                                .is_none_or(|permit| {
                                                    tracked
                                                        .deferred_successor_start_gate
                                                        .as_ref()
                                                        .is_some_and(|current| {
                                                            Arc::ptr_eq(current, &permit.gate)
                                                        })
                                                }) =>
                                    {
                                        tracked.process =
                                            Some(super::types::ProviderProcess::CodexAppServer(
                                                as_process
                                                    .take()
                                                    .expect("deferred process installs once"),
                                            ));
                                        true
                                    }
                                    _ => false,
                                }
                            };
                            drop(deferred_successor_start_permit);
                            if !installed {
                                if let Some(as_process) = as_process.as_mut()
                                    && let Err(error) = as_process.kill().await
                                {
                                    tracing::warn!(
                                        session_id = %session_id,
                                        error = %error,
                                        "Failed to stop stale deferred successor provider"
                                    );
                                }
                                if let Some(context) = successor_launch_context.as_mut() {
                                    settle_failed_deferred_agent_successor(
                                        context,
                                        &active,
                                        &store,
                                        &event_bus,
                                        &agent_tokens,
                                        &admission_permit_for_task,
                                        spawn_generation,
                                        DeferredSuccessorStartRejection::IncarnationChanged
                                            .reason(),
                                        DeferredSuccessorStartRejection::IncarnationChanged
                                            .safe_error_class(),
                                    )
                                    .await;
                                }
                                if let Some(context) = manager_action_context.as_ref() {
                                    settle_failed_deferred_manager_action(
                                        context,
                                        &active,
                                        &store,
                                        &event_bus,
                                        &agent_tokens,
                                        &admission_permit_for_task,
                                        spawn_generation,
                                        "manager_v2_candidate_cancelled",
                                    )
                                    .await;
                                }
                                return;
                            }
                            if let Some(context) = controller_launch_context.as_mut() {
                                let _ = signal_controller_candidate_confirmation(
                                    context,
                                    &store,
                                    &agent_tokens,
                                    provider,
                                    admission_permit_for_task.invocation_id(),
                                    ControllerConfirmationKindV1::CodexAppServerInitialized,
                                )
                                .await;
                            }
                            if let Some(context) = successor_launch_context.as_mut() {
                                let _ = signal_agent_successor_confirmation(
                                    context,
                                    &store,
                                    &agent_tokens,
                                    provider,
                                    admission_permit_for_task.invocation_id(),
                                    ControllerConfirmationKindV1::CodexAppServerInitialized,
                                )
                                .await;
                            }
                            Box::new(as_session)
                        }
                        Err(e) => {
                            let execution_scratch_failure = matches!(
                                &e,
                                DaemonError::ExecutionScratchUnavailable(_)
                            );
                            if let Some(context) = manager_successor_context.as_ref() {
                                context.remember_refusal(&e);
                                // Dropping the client is not a checked process
                                // settlement. Keep the main invocation reserved
                                // for the guarded root task's exit cleanup.
                                return;
                            }
                            drop(deferred_successor_start_permit);
                            if let Some(context) = manager_action_context.as_ref() {
                                settle_failed_deferred_manager_action(
                                    context,
                                    &active,
                                    &store,
                                    &event_bus,
                                    &agent_tokens,
                                    &admission_permit_for_task,
                                    spawn_generation,
                                    if execution_scratch_failure {
                                        "execution_scratch_unavailable"
                                    } else {
                                        "manager_v2_deferred_initialize_failed"
                                    },
                                )
                                .await;
                                return;
                            }
                            if execution_scratch_failure {
                                if let Some(context) = successor_launch_context.as_mut() {
                                    settle_failed_deferred_agent_successor(
                                        context,
                                        &active,
                                        &store,
                                        &event_bus,
                                        &agent_tokens,
                                        &admission_permit_for_task,
                                        spawn_generation,
                                        "execution scratch revalidation failed before deferred provider dispatch",
                                        "execution_scratch_unavailable",
                                    )
                                    .await;
                                } else {
                                    settle_failed_deferred_execution_scratch(
                                        &active,
                                        &store,
                                        &event_bus,
                                        &agent_tokens,
                                        &custody_runtime,
                                        session_id,
                                        &admission_permit_for_task,
                                        spawn_generation,
                                        &exact_launch_token_for_task,
                                        retry_bound.as_ref(),
                                        deferred_agent_child_context.as_ref(),
                                        controller_launch_context.as_deref_mut(),
                                    )
                                    .await;
                                }
                                tracing::error!(session_id = %session_id, error = %e, "CodexAppServer execution scratch revalidation failed");
                                return;
                            }
                            if let Some(bound) = retry_bound.as_ref() {
                                let _ = custody_runtime
                                    .settle_bound_retry_failure(
                                        session_id,
                                        bound,
                                        SandboxCustodyErrorCodeV1::PersistenceTransitionFailed,
                                    )
                                    .await;
                            }
                            if let Some(context) = successor_launch_context.as_mut() {
                                settle_failed_deferred_agent_successor(
                                    context,
                                    &active,
                                    &store,
                                    &event_bus,
                                    &agent_tokens,
                                    &admission_permit_for_task,
                                    spawn_generation,
                                    "CodexAppServer initialize/thread-start failed before successor establishment",
                                    "agent_successor_codex_app_server_initialize_failed",
                                )
                                .await;
                            } else {
                                let child_settlement = if let Some(context) =
                                    deferred_agent_child_context.as_ref()
                                {
                                    store
                                        .lock()
                                        .await
                                        .settle_post_bind_agent_child_failure(
                                            context.spawn_request_id,
                                            session_id,
                                            admission_permit_for_task.invocation_id(),
                                            "codex_app_server_launch_failed",
                                        )
                                        .map_err(|error| error.to_string())
                                } else {
                                    Ok(())
                                };
                                if let Err(settle_error) = child_settlement {
                                    tracing::warn!(
                                        error = %settle_error,
                                        session_id = %session_id,
                                        "Failed to settle CodexAppServer child launch; retaining active session for recovery"
                                    );
                                    persistence
                                        .record_session_diagnostic(
                                            session_id,
                                            rsi_common::types::SessionDiagnosticLevelV1::Error,
                                            "CodexAppServer child launch settlement failed",
                                        )
                                        .await;
                                    return;
                                }
                                let finalized = Self::finalize_session(
                                    session_id,
                                    spawn_generation,
                                    super::types::TerminalFinalizeDecision::failed(
                                        crate::store::daemon_settings::AutofileCause::OtherTerminalFailure,
                                    ),
                                    active.clone(),
                                    completed.clone(),
                                    event_bus.clone(),
                                    store.clone(),
                                    persistence.clone(),
                                    memory_handle.clone(),
                                    runtime_config.clone(),
                                )
                                .await;
                                if finalized.is_none() {
                                    tracing::warn!(
                                        session_id = %session_id,
                                        "CodexAppServer launch failure lost its active incarnation before settlement"
                                    );
                                } else {
                                    super::revoke_agent_tokens_for_session(&agent_tokens, session_id)
                                        .await;
                                    if let Some(context) = controller_launch_context.as_mut() {
                                        context.confirmation_tx.take();
                                        context.prospective_a6.clear().await;
                                    }
                                }
                            }
                            persistence
                                .record_session_diagnostic(
                                    session_id,
                                    rsi_common::types::SessionDiagnosticLevelV1::Error,
                                    "CodexAppServer handshake failed",
                                )
                                .await;
                            tracing::error!(session_id = %session_id, error = %e, "CodexAppServer handshake failed");
                            return;
                        }
                    }
                };
                if let Some(context) = manager_successor_context.as_ref() {
                    #[cfg(test)]
                    pause_controller_candidate_test(
                        session_id,
                        ControllerCandidateTestPhase::ManagerBeforePublication,
                    )
                    .await;
                    if let Err(error) = context.publish().await {
                        context.remember_refusal(&error);
                        tracing::warn!(%error, "manager succession publication refused");
                        return;
                    }
                    manager_successor_guards.take();
                }
                // Phase 7: Build TurnController based on SessionKind.
                // TaskRabbit and Bug sessions may run multiple turns; Standard runs one.
                let turn_policy = match config.session_kind.unwrap_or_default() {
                    SessionKind::TaskRabbit | SessionKind::Bug => {
                        crate::turn_controller::ContinuationPolicy::MaxTurns(5)
                    }
                    _ => crate::turn_controller::ContinuationPolicy::Single,
                };
                let turn_controller = crate::turn_controller::TurnController::new(turn_policy);

                Self::monitor_session(
                    session_id,
                    spawn_generation,
                    provider_session,
                    active,
                    completed,
                    event_bus,
                    stop_rx,
                    store,
                    model_call_settlements,
                    persistence,
                    1,
                    context_rotation_enabled,
                    socket_path,
                    counter,
                    memory_handle,
                    retry_tx,
                    tool_registry,
                    turn_controller,
                    runtime_config,
                    spawn_coordinator,
                    agent_tokens,
                    spawn_epoch,
                    agent_message_arbiter,
                    codegraph_handle,
                    custody_runtime,
                )
                .await;
            };
            task.await;
            if let Some(context) = root_exit {
                if let Err(error) = context.fail_and_settle().await {
                    tracing::error!(%error, "manager succession cleanup remains durably owed");
                }
            }
            drop(manager_successor_guards);
        });

        Ok(session_id)
    }

    /// Load completed sessions from database into the completed HashMap.
    /// Mark any sessions that were "Running" or "Starting" when daemon died as "Failed".
    pub async fn restore_sessions(&self) -> Result<()> {
        let restore_started_at = Instant::now();
        let mut phase_started_at = restore_started_at;
        // Fence stale effects first. Retained V94 Git intents must reconcile
        // after that fence but before generic custody classification can
        // reinterpret an intentionally half-complete settlement saga.
        tokio::task::spawn_blocking({
            let store = self.store.clone();
            let boot_id = self.program_run_boot_id;
            move || {
                let mut store = store.blocking_lock();
                store.reconcile_stale_effect_boots_complete(boot_id, 64)
            }
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;
        let sandbox_base = self.sandbox_allocator.base_dir().to_path_buf();
        let orphan_candidates = tokio::task::spawn_blocking({
            let store = self.store.clone();
            let sandbox_base = sandbox_base.clone();
            move || {
                store
                    .blocking_lock()
                    .source_worktree_startup_orphan_candidates(&sandbox_base)
            }
        })
        .await;
        let settlement_recovery_safe = match orphan_candidates {
            Ok(Ok(candidates)) => {
                match tokio::task::spawn_blocking(move || {
                    super::reaper::reap_startup_settlement_orphans_checked(&candidates)
                })
                .await
                {
                    Ok(Ok(reaped)) => {
                        if reaped > 0 {
                            tracing::warn!(
                                reaped,
                                "Reaped exact-stamped provider orphan(s) before settlement recovery"
                            );
                        }
                        true
                    }
                    Ok(Err(error)) => {
                        tracing::error!(
                            error = %error,
                            "Skipping source-worktree settlement recovery: startup orphan proof failed"
                        );
                        false
                    }
                    Err(error) => {
                        tracing::error!(
                            error = %error,
                            "Skipping source-worktree settlement recovery: startup orphan proof task failed"
                        );
                        false
                    }
                }
            }
            Ok(Err(error)) => {
                tracing::error!(
                    error = %error,
                    "Skipping source-worktree settlement recovery: orphan candidate scan failed"
                );
                false
            }
            Err(error) => {
                tracing::error!(
                    error = %error,
                    "Skipping source-worktree settlement recovery: orphan candidate task failed"
                );
                false
            }
        };
        if settlement_recovery_safe {
            self.recover_source_worktree_settlements().await?;
        }
        // Ordinary archive cleanup owns its authenticated quarantine until
        // its journal reaches a terminal phase. Resume it before generic
        // custody reconciliation can classify the original path as missing.
        self.recover_archive_cleanups().await?;
        let adoption_store = Arc::clone(&self.store);
        let adoption_base = self.sandbox_allocator.base_dir().to_path_buf();
        match tokio::task::spawn_blocking(move || {
            let mut store = adoption_store.blocking_lock();
            crate::sandbox::reclaim::run_absent_root_adoption(
                &mut store,
                &adoption_base,
                "startup",
                false,
                1024,
                None,
            )
        })
        .await
        {
            Ok(Ok(_run_id)) => {}
            Ok(Err(error)) => tracing::error!(
                error = %error,
                "Sandbox absent-root startup adoption failed; continuing restore"
            ),
            Err(error) => tracing::error!(
                error = %error,
                "Sandbox absent-root startup adoption task failed; continuing restore"
            ),
        }
        log_authority_restore_phase(
            "stale_effect_and_settlement_recovery",
            phase_started_at,
            restore_started_at,
        );
        phase_started_at = Instant::now();
        // Custody classification precedes every remaining restore-side effect.
        // The Store drains deterministic bounded batches internally, so this
        // call cannot expose a partially classified startup to later work.
        tokio::task::spawn_blocking({
            let store = self.store.clone();
            let sandbox_base = self.sandbox_allocator.base_dir().to_path_buf();
            move || {
                let mut store = store.blocking_lock();
                CustodyService::reconcile_startup(&mut store, &sandbox_base)
            }
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;
        log_authority_restore_phase(
            "custody_classification",
            phase_started_at,
            restore_started_at,
        );
        phase_started_at = Instant::now();
        // D03 startup gate: validate every durable controller tail, release
        // every pre-boot reservation with zero grace, and intentionally
        // reconstruct no A6/semantic grant before session restoration begins.
        self.reconcile_idea_controllers_at_startup(chrono::Utc::now())
            .await?;

        let store = self.store.clone();
        let reconciled_invocations = tokio::task::spawn_blocking(move || {
            let store = store.blocking_lock();
            store.reconcile_running_model_invocations()
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;
        if reconciled_invocations > 0 {
            tracing::warn!(
                reconciled_invocations,
                "Reconciled running model invocations during restore"
            );
        }
        let open_relaunches = self.store.lock().await.open_child_relaunch_intents()?;
        for row in open_relaunches {
            let _guard = super::spawn_single_flight::acquire_spawn_guard(row.tip_session_id).await;
            self.recover_agent_child_relaunch(&row).await?;
        }
        log_authority_restore_phase(
            "controller_and_invocation_reconciliation",
            phase_started_at,
            restore_started_at,
        );
        phase_started_at = Instant::now();

        let store = self.store.clone();
        let (sessions, retry_eligible) = tokio::task::spawn_blocking(move || {
            let store = store.blocking_lock();
            let sessions = store.load_sessions()?;
            // Invalid custody is historical/auditable, not invisible.  Keep
            // every loaded terminal row in the completed map, while deriving
            // restart retry eligibility from durable Session classification.
            // One joined projection/root read avoids N+1 rechecks. It
            // intentionally materializes at most the already-loaded restore
            // corpus; terminal history remains visible in `sessions`, while
            // only executable verified custody enters the retry set.
            let retry_eligible = store.startup_retry_eligible_sessions()?;
            Ok::<_, DaemonError>((sessions, retry_eligible))
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;

        // Rows this pass moved from a live status to Failed/ProcessDied. Only
        // these can carry an open rotation intent (F3 Slice 3a, RPC-1 C7).
        let mut crash_reconciled: Vec<Uuid> = Vec::new();
        let mut completed_guard = self.completed.write().await;
        for mut session in sessions {
            // A provider that was live when the daemon died must acquire its
            // durable terminal state before pending-archive cleanup can erase
            // the last manager route.
            let waiting_with_question = session.status == SessionStatus::WaitingApproval
                && session.pending_question.is_some();
            let crash_reconciliation = if matches!(
                session.status,
                SessionStatus::Running | SessionStatus::Starting
            ) || (session.status == SessionStatus::WaitingApproval
                && !waiting_with_question)
            {
                let old_status = session.status;
                session.status = SessionStatus::Failed;
                session.updated_at = chrono::Utc::now();
                // Pending archive is user cancellation, so its restore path
                // persists Failed without staging a transient C5 autofile
                // marker. The ordinary crash path keeps the existing atomic
                // Failed-plus-marker transition.
                if !session.pending_archive {
                    if let Err(e) = self
                        .persistence
                        .update_failed_and_stage_autofile(
                            session.id,
                            crate::store::daemon_settings::AutofileCause::ProcessDied,
                        )
                        .await
                    {
                        tracing::warn!(
                            session_id = %session.id,
                            error = %e,
                            "Failed to persist crash-recovered status"
                        );
                    }
                    self.event_bus.publish(DaemonEvent::SessionReconciled {
                        session_id: session.id,
                        old_status,
                        new_status: SessionStatus::Failed,
                        reason: crate::reconciliation::ReconciliationReason::ProcessDied,
                    });
                    crash_reconciled.push(session.id);
                }
                Some(old_status)
            } else {
                None
            };
            // Pending archive is durable user intent.  Resolve it before
            // loading restored session state into memory. Live-at-crash rows
            // are terminalized during pre-archive capture so it cannot
            // silently return None.
            if session.pending_archive {
                drop(completed_guard);
                // Archive is a terminal metadata transition. It deliberately
                // retains sandbox files, refs, and custody, so D00's physical
                // cleanup/reclamation proof must not gate restore-side archive.
                tracing::info!(session_id = %session.id, "Auto-archiving pending session on restore");
                // A crash can occur after pending_archive and terminal state
                // persist but before the ordinary finalizer captures its
                // manager notice. Re-establish that exact durable obligation
                // while the Epic still names this lead; any failure leaves the
                // pointer and pending intent intact for the next restore.
                let notice_capture: Result<(Option<Uuid>, Session)> = {
                    let store = self.store.lock().await;
                    (|| {
                        if crash_reconciliation.is_some() {
                            store.update_session_status(session.id, SessionStatus::Failed)?;
                        }
                        let persisted = store
                            .get_session(session.id)?
                            .ok_or(DaemonError::SessionNotFound(session.id))?;
                        let job =
                            store.record_manager_terminal_notice_before_archive(&persisted)?;
                        Ok((job, persisted))
                    })()
                };
                let notice_job = match notice_capture {
                    Ok((job, persisted)) => {
                        session = persisted;
                        job
                    }
                    Err(error) => {
                        tracing::warn!(
                            session_id = %session.id,
                            error = %error,
                            "Failed to capture terminal manager notice before restore auto-archive"
                        );
                        completed_guard = self.completed.write().await;
                        continue;
                    }
                };
                if let Some(old_status) = crash_reconciliation {
                    self.event_bus.publish(DaemonEvent::SessionReconciled {
                        session_id: session.id,
                        old_status,
                        new_status: SessionStatus::Failed,
                        reason: crate::reconciliation::ReconciliationReason::ProcessDied,
                    });
                }
                if let Some(job_id) = notice_job {
                    self.event_bus
                        .publish(DaemonEvent::ManagerNoticeQueued { job_id });
                }
                // The hierarchy mutation is the admission gate for archival.
                // If it cannot be made durable, leave the row pending and
                // unarchived so the next restore can retry without an Epic
                // retaining an Archived lead.
                if let Err(e) = self.clear_lead_pointers_to(session.id).await {
                    tracing::warn!(
                        session_id = %session.id,
                        error = %e,
                        "Failed to clear Epic lead pointers before restore auto-archive"
                    );
                    completed_guard = self.completed.write().await;
                    continue;
                }
                if let Err(e) = self
                    .persistence
                    .archive_and_resolve_autofile(session.id)
                    .await
                {
                    tracing::warn!(session_id = %session.id, error = %e, "Failed to persist auto-archive on restore");
                    completed_guard = self.completed.write().await;
                    continue;
                }
                self.event_bus.publish(DaemonEvent::SessionArchived {
                    session_id: session.id,
                    projection_id: None,
                });
                completed_guard = self.completed.write().await;
                continue;
            }
            // Load turn_metrics for this session. C7 Phase 1: do NOT eagerly load
            // the full event transcript here -- restore_sessions runs for every
            // Completed/Failed/Interrupted row at startup, and the transcript
            // content (~1GB across a real operator's history) dominates daemon
            // RSS if pulled into the long-lived `completed` map unconditionally.
            // Events are durable in SQLite and are hydrated on first actual use
            // via `hydrate_completed_events` (index-backed, cheap per session).
            let store = self.store.clone();
            let sid = session.id;
            let load_result = tokio::task::spawn_blocking(move || {
                let store = store.blocking_lock();
                store.load_turn_metrics(sid)
            })
            .await
            .map_err(|e| DaemonError::Store(e.to_string()));

            let turn_metrics = match load_result {
                Ok(Ok(data)) => data,
                Ok(Err(e)) => {
                    tracing::warn!(
                        session_id = %session.id,
                        error = %e,
                        "Skipping session with corrupt data during restore"
                    );
                    continue;
                }
                Err(e) => {
                    tracing::warn!(
                        session_id = %session.id,
                        error = %e,
                        "Skipping session due to task join error during restore"
                    );
                    continue;
                }
            };

            if let Some(resolved) = session.resolved_context_budget.take() {
                let resolved = crate::provider_capabilities::rehydrate_resolved_context_budget(
                    session.provider,
                    session.model.as_deref().unwrap_or("unknown"),
                    resolved,
                );
                session.context_window = Some(resolved.active_tokens);
                session.resolved_context_budget = Some(resolved);
            }
            sanitize_codex_restored_context_usage(&mut session, &turn_metrics);

            // Set confidence based on whether we have persisted token data
            if session.total_input_tokens.unwrap_or(0) > 0 {
                session.context_usage_confidence = ContextUsageConfidence::Partial;
            }

            completed_guard.insert(
                session.id,
                CompletedSession {
                    session,
                    events: Vec::new(),
                    turn_metrics,
                    retry_cancel: None,
                    retry_fired_at: None,
                    superseded_by_retry: None,
                    events_hydrated: false,
                },
            );
        }

        drop(completed_guard);
        log_authority_restore_phase(
            "session_rows_and_metrics",
            phase_started_at,
            restore_started_at,
        );
        phase_started_at = Instant::now();
        self.repair_invalid_epic_leads_on_restore().await?;
        // An open rotation intent (paused for transfer) yields exactly one
        // successor decision; restart retry must not relaunch its predecessor.
        let recovered_rotations = self.recover_open_rotation_intents(&crash_reconciled).await;
        let completed_guard = self.completed.write().await;
        let suppress_retry_restore = self
            .runtime_config
            .smoke_suppress_retry_restore
            .load(std::sync::atomic::Ordering::Relaxed);
        if suppress_retry_restore {
            tracing::warn!(
                "Suppressing restart-recovery retry relaunches because RSI_SMOKE_SUPPRESS_RETRY_RESTORE is enabled"
            );
        }

        // Re-queue failed sessions with remaining retries
        let retry_restore_disabled =
            suppress_retry_restore || !super::retry_policy::retries_enabled(&self.runtime_config);
        if retry_restore_disabled && !suppress_retry_restore {
            tracing::info!(
                "Skipping restart-recovery retry relaunches because retry_enabled=false"
            );
        }

        let retry_candidates: Vec<(Uuid, u8, u8)> = if retry_restore_disabled {
            Vec::new()
        } else {
            // Build set of session IDs that have been superseded by a retry child.
            // A session is superseded if any other session has `continued_from` pointing to it.
            let superseded: std::collections::HashSet<Uuid> = completed_guard
                .values()
                .filter_map(|cs| cs.session.continued_from)
                .collect();

            // Collect raw candidates, excluding superseded sessions.
            let mut raw: Vec<(Uuid, u8, u8)> = completed_guard
                .iter()
                .filter_map(|(id, cs)| {
                    if retry_eligible.contains(id)
                        && cs.session.status == SessionStatus::Failed
                        && !superseded.contains(id)
                        && !recovered_rotations.contains(id)
                    {
                        let attempt = cs.session.retry_attempt.unwrap_or(0);
                        let max = cs.session.max_retries;
                        if super::retry_policy::session_retries_allowed(
                            &self.runtime_config,
                            cs.session.session_kind,
                            max,
                        ) && attempt < max.unwrap_or(0)
                        {
                            Some((*id, attempt, max.unwrap_or(0)))
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                })
                .collect();

            // De-duplicate by retry chain: group by the chain root and keep only the
            // session with the highest retry_attempt per chain.
            // Walk continued_from links to find each session's chain root.
            let find_root = |start_id: Uuid| -> Uuid {
                let mut current = start_id;
                for _ in 0..10 {
                    // depth limit to prevent cycles
                    if let Some(cs) = completed_guard.get(&current) {
                        if let Some(parent) = cs.session.continued_from {
                            current = parent;
                            continue;
                        }
                    }
                    break;
                }
                current
            };

            let mut best_per_chain: std::collections::HashMap<Uuid, (Uuid, u8, u8)> =
                std::collections::HashMap::new();
            for (id, attempt, max) in raw.drain(..) {
                let root = find_root(id);
                let entry = best_per_chain.entry(root).or_insert((id, attempt, max));
                if attempt > entry.1 {
                    *entry = (id, attempt, max);
                }
            }

            best_per_chain.into_values().collect()
        };

        drop(completed_guard);

        for (session_id, attempt, max_retries) in retry_candidates {
            let next_attempt = attempt + 1;
            let max_backoff = self
                .runtime_config
                .retry_max_backoff_ms
                .load(std::sync::atomic::Ordering::Relaxed);
            let delay = crate::session::monitor::backoff_ms(next_attempt, max_backoff);
            tracing::info!(
                session_id = %session_id,
                attempt = next_attempt,
                max_retries = max_retries,
                backoff_ms = delay,
                "Re-queuing retry after daemon restart"
            );

            self.event_bus
                .publish(crate::bus::DaemonEvent::SessionRetrying {
                    session_id,
                    attempt: next_attempt,
                    max_retries,
                    backoff_ms: delay,
                    reason: "daemon restart recovery".to_string(),
                });

            let (cancel_tx, cancel_rx) = tokio::sync::oneshot::channel();
            {
                let mut completed_guard = self.completed.write().await;
                if let Some(cs) = completed_guard.get_mut(&session_id) {
                    cs.retry_cancel = Some(cancel_tx);
                    cs.retry_fired_at = None;
                    cs.session.retry_attempt = Some(next_attempt);
                }
            }

            if let Err(e) = self
                .persistence
                .update_retry_state(session_id, Some(next_attempt), Some(max_retries))
                .await
            {
                tracing::warn!(
                    session_id = %session_id,
                    error = %e,
                    "Failed to persist restart-recovery retry state"
                );
            }

            spawn_retry_timer(
                Arc::clone(&self.completed),
                self.retry_tx.clone(),
                session_id,
                delay,
                cancel_rx,
                "Restart-recovery retry cancelled",
            );
        }
        log_authority_restore_phase(
            "lead_and_retry_reconciliation",
            phase_started_at,
            restore_started_at,
        );
        phase_started_at = Instant::now();

        // Retry setup holds no completed-map guard here. Keep the orphan sweep
        // outside map locks: it queries the store
        // and may contend on the persistence worker, and it does NOT need
        // the completed-map lock held.
        // Sandbox orphan sweep: reconcile DB cleanup_state=Live rows whose
        // owning session is terminal, and any on-disk sandbox subdirs that
        // have no owning Live row. Non-fatal on error.
        if let Err(e) = self.sandbox_orphan_sweep().await {
            tracing::warn!(error = %e, "Sandbox orphan sweep failed during restore (non-fatal)");
        }
        log_authority_restore_phase(
            "orphan_classification",
            phase_started_at,
            restore_started_at,
        );
        tracing::info!(
            startup_milestone = "authority_restore_complete",
            total_elapsed_ms = bounded_elapsed_ms(restore_started_at),
            "Daemon authority restore completed"
        );

        Ok(())
    }

    /// Walk the DB + filesystem and classify retained sandbox candidates.
    ///
    /// Algorithm:
    /// 1. Fetch all rows where `sandbox_cleanup_state='Live'` along with
    ///    their current status and sandbox_root.
    /// 2. For each non-resumable owner, re-read the typed row and classify it
    ///    through the shared D00 boundary.
    /// 3. Read the sandbox base directory; any subdir whose allocation UUID
    ///    is NOT represented by a live owner root is classified as path-only.
    ///
    /// D00 has no positive cleanup authorization, so every real candidate is
    /// retained without filesystem, ref, cleanup-state, or event mutation.
    pub(super) async fn sandbox_orphan_sweep(&self) -> Result<()> {
        // 1. Snapshot the Live-owner set from the store.
        let store = self.store.clone();
        let live_owners = tokio::task::spawn_blocking(move || {
            let store = store.blocking_lock();
            store.list_live_sandbox_owners()
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;

        // The directory name is a durable allocation identity. It normally
        // matches the owner session ID, but restored sandboxes intentionally
        // receive a fresh allocation ID so their historical custody roots can
        // remain immutable.
        let live_allocation_ids: std::collections::HashSet<Uuid> = live_owners
            .iter()
            .filter_map(|(_, _, root)| {
                root.file_name()
                    .and_then(|name| name.to_str())
                    .and_then(|name| Uuid::parse_str(name).ok())
            })
            .collect();

        // 2. Classify non-resumable typed owners without mutating them.
        for (session_id, status, sandbox_root) in live_owners.iter() {
            if !should_purge_sandbox_on_restore(*status) {
                continue;
            }
            let store = self.store.clone();
            let sid = *session_id;
            #[cfg(test)]
            let inject_row_reread_failure = {
                let mut guard = D00_STARTUP_ROW_REREAD_FAILURE
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                if guard.as_ref() == Some(&sid) {
                    *guard = None;
                    true
                } else {
                    false
                }
            };
            #[cfg(not(test))]
            let inject_row_reread_failure = false;
            let session_row = if inject_row_reread_failure {
                Err(DaemonError::Store(
                    "injected D00 startup row re-read failure".to_string(),
                ))
            } else {
                tokio::task::spawn_blocking(move || {
                    let store = store.blocking_lock();
                    store.get_session(sid)
                })
                .await
                .map_err(|e| DaemonError::Store(e.to_string()))
            };

            let candidate = startup_candidate_from_row_read(
                *session_id,
                sandbox_root,
                session_row.ok().and_then(Result::ok).flatten(),
            );
            match self.classify_cleanup_candidate(candidate).await {
                CleanupDecision::Blocked(reason) => {
                    tracing::warn!(
                        session_id = %session_id,
                        sandbox_root = %sandbox_root.display(),
                        cleanup_reason = reason.as_str(),
                        "Retaining typed startup sandbox candidate"
                    );
                }
                CleanupDecision::NoCleanupRequired => {
                    tracing::debug!(
                        session_id = %session_id,
                        "Startup sandbox row has no cleanup target"
                    );
                }
            }
        }

        // 3. Path-only candidates are retained independently of any prior
        // cleanup state. Absence from the Live-owner set is not authority.
        let allocator_for_list = Arc::clone(&self.sandbox_allocator);
        let on_disk = tokio::task::spawn_blocking(move || allocator_for_list.list_on_disk())
            .await
            .map_err(|e| DaemonError::Process(e.to_string()))??;

        for uuid in on_disk {
            if live_allocation_ids.contains(&uuid) {
                continue;
            }
            let stray_path = self.sandbox_allocator.base_dir().join(uuid.to_string());
            let candidate = CleanupCandidate::PathOnly {
                attributed_session_id: Some(uuid),
                root: stray_path.clone(),
            };
            if let CleanupDecision::Blocked(reason) =
                self.classify_cleanup_candidate(candidate).await
            {
                tracing::warn!(
                    session_id = %uuid,
                    sandbox_root = %stray_path.display(),
                    cleanup_reason = reason.as_str(),
                    "Retaining path-only startup sandbox candidate"
                );
            }
        }

        Ok(())
    }

    /// Reclaim cargo build caches inside terminal sessions' Live sandboxes
    /// (issue #25).
    ///
    /// The daemon designates `<sandbox_root>/target` as each sandboxed
    /// session's `CARGO_TARGET_DIR` at launch, so build artifacts are the one
    /// piece of sandbox state the daemon positively owns and knows to be
    /// regenerable. This sweep deletes exactly that directory — never the
    /// worktree, never user work — for sessions that have been terminal
    /// (Completed/Failed/Interrupted/Archived/Deleted) for at least
    /// the operator-configured TTL. Under configured disk pressure, terminal
    /// caches may be reclaimed sooner; a later continue just pays one cold
    /// rebuild.
    ///
    /// Deliberately NOT part of the D00 cleanup boundary: D00 governs sandbox
    /// *identity* destruction (worktree + branch) and has no positive
    /// authorization today. Build caches are ignored-by-git scratch inside a
    /// dir the daemon itself designated; the safety checks here are
    /// filesystem-local:
    ///   1. owning row is terminal AND idle past the TTL (store query +
    ///      `updated_at` age gate);
    ///   2. the session is not in the in-memory active map;
    ///   3. the sandbox root canonicalizes to a descendant of the sandbox
    ///      base dir AND its directory name is its persisted allocation UUID;
    ///   4. the cache path is a real directory, not a symlink.
    ///
    /// Returns the total bytes reclaimed. Errors on individual candidates are
    /// logged and skipped — one bad row must not starve the rest.
    pub async fn reclaim_terminal_build_caches(&self) -> Result<u64> {
        Ok(self
            .run_sandbox_build_cache_reclaim(false)
            .await?
            .reclaimed_bytes)
    }

    /// Run one bounded target-cache maintenance pass. Dry-run traverses the
    /// exact custody and filesystem authentication boundary and sizes targets,
    /// but cannot remove them or mutate the pressure hysteresis bit.
    pub async fn run_sandbox_build_cache_reclaim(
        &self,
        dry_run: bool,
    ) -> Result<SandboxBuildCacheReclaimReport> {
        // The only production caller of this compatibility entry point is the
        // periodic daemon worker.  Startup and operator paths name their
        // trigger explicitly below.
        self.run_sandbox_build_cache_reclaim_for_trigger(dry_run, "periodic")
            .await
    }

    pub(crate) async fn run_sandbox_build_cache_reclaim_for_trigger(
        &self,
        dry_run: bool,
        trigger: &'static str,
    ) -> Result<SandboxBuildCacheReclaimReport> {
        Ok(self
            .run_sandbox_build_cache_reclaim_with_evidence_for_trigger(dry_run, trigger)
            .await?
            .report)
    }

    pub(crate) async fn run_sandbox_build_cache_reclaim_wire_for_trigger(
        &self,
        dry_run: bool,
        trigger: &'static str,
    ) -> Result<SandboxBuildCacheReclaimReportWire> {
        Ok(self
            .run_sandbox_build_cache_reclaim_with_evidence_for_trigger(dry_run, trigger)
            .await?
            .into_wire())
    }

    pub(crate) async fn run_sandbox_worktree_reclaim(
        &self,
        dry_run: bool,
        max_count: usize,
    ) -> Result<serde_json::Value> {
        let store = Arc::clone(&self.store);
        let sandbox_base = self.sandbox_allocator.base_dir().to_path_buf();
        tokio::task::spawn_blocking(move || {
            let mut store = store.blocking_lock();
            let run_id = crate::sandbox::reclaim::run_absent_root_adoption(
                &mut store,
                &sandbox_base,
                "operator",
                dry_run,
                max_count,
                None,
            )?;
            store.sandbox_reclaim_run_result(run_id)
        })
        .await
        .map_err(|error| DaemonError::Store(error.to_string()))?
    }

    async fn run_sandbox_build_cache_reclaim_with_evidence_for_trigger(
        &self,
        dry_run: bool,
        trigger: &'static str,
    ) -> Result<SandboxReclaimRun> {
        self.submit_sandbox_build_cache_reclaim(dry_run, false, trigger)?
            .await
            .map_err(|_| {
                DaemonError::Process(
                    "sandbox reclaim coordinator terminated before returning a result".to_string(),
                )
            })?
    }

    fn submit_sandbox_build_cache_reclaim(
        &self,
        dry_run: bool,
        prepared_only: bool,
        trigger: &'static str,
    ) -> Result<tokio::sync::oneshot::Receiver<Result<SandboxReclaimRun>>> {
        let manager_key = sandbox_reclaim_manager_key(&self.store);
        let coordinator = match sandbox_reclaim_coordinator_for_manager(manager_key) {
            Ok(coordinator) => coordinator,
            Err(error) => {
                log_sandbox_build_cache_reclaim_preaccept_error(trigger, dry_run, &error);
                return Err(error);
            }
        };
        let context = SandboxReclaimContext {
            active: Arc::clone(&self.active),
            store: Arc::clone(&self.store),
            runtime_config: Arc::clone(&self.runtime_config),
            sandbox_allocator: Arc::clone(&self.sandbox_allocator),
        };
        let (result_tx, result_rx) = tokio::sync::oneshot::channel();
        let dispatch = tracing::dispatcher::get_default(Clone::clone);
        if let Err(error) = submit_sandbox_reclaim_job(
            coordinator,
            manager_key,
            SandboxReclaimJob {
                context,
                dry_run,
                prepared_only,
                trigger,
                manager_key,
                enqueued_at: Instant::now(),
                dispatch,
                result_tx,
            },
        ) {
            log_sandbox_build_cache_reclaim_preaccept_error(trigger, dry_run, &error);
            return Err(error);
        }
        Ok(result_rx)
    }

    /// Submit the startup pass after authority-bearing initialization and keep
    /// its response receiver alive until the process-wide worker settles it.
    /// Startup readiness does not depend on the report, while synchronous
    /// periodic, preview, and operator callers continue awaiting their own.
    pub fn submit_sandbox_build_cache_reclaim_startup(&self) -> Result<()> {
        let result_rx = self.submit_sandbox_build_cache_reclaim(false, false, "startup")?;
        tracing::info!(
            trigger = "startup",
            lifecycle_phase = "accepted",
            "Sandbox build-cache reclaim pass accepted for asynchronous startup execution"
        );
        tokio::spawn(async move {
            let _ = result_rx.await;
        });
        Ok(())
    }

    /// Promptly retry journaled Prepared gates through the same single-flight
    /// worker as ordinary reclaim. The daemon calls this at a one-second
    /// cadence; a full queue is retried on the next tick.
    pub async fn recover_prepared_target_reclaims(&self) -> Result<()> {
        // Queue behind Store users so continuous contention cannot skip every
        // recovery tick while a Prepared gate keeps custody blocked.
        let pending = self
            .store
            .lock()
            .await
            .target_reclaim_intent_counts()?
            .prepared
            > 0;
        if !pending {
            return Ok(());
        }
        self.submit_sandbox_build_cache_reclaim(false, true, "prepared_recovery")?
            .await
            .map_err(|_| DaemonError::Process("prepared reclaim worker disconnected".into()))??;
        Ok(())
    }

    async fn run_sandbox_build_cache_reclaim_owned(
        context: SandboxReclaimContext,
        dry_run: bool,
        prepared_only: bool,
        manager_key: usize,
        worker_state: &SandboxReclaimWorkerState,
    ) -> Result<SandboxReclaimRun> {
        use crate::sandbox::target_reclaim::TargetReclaimKind;

        let base = context.sandbox_allocator.base_dir().to_path_buf();
        pause_reclaim_after_single_flight_for_test(manager_key, &base).await;
        maybe_panic_reclaim_job_for_test(manager_key);
        let pass_state = reclaim_pass_state_for_manager(manager_key);
        // Recovery and new-candidate deletion receive independent bounded
        // quanta. Exhausting one queue must not prevent the other from making
        // progress during the same daemon pass.
        let recovery_pass_state = crate::sandbox::target_reclaim::ReclaimPassState::new();
        let intent_recovery_pass_state = crate::sandbox::target_reclaim::ReclaimPassState::new();
        let config = context
            .runtime_config
            .sandbox_build_cache_reclaim_snapshot();
        let filesystem_before = sandbox_filesystem_stats(&base)?;
        let pressure_active_before = context
            .runtime_config
            .sandbox_build_cache_pressure_active
            .load(Ordering::Relaxed);
        let mut pressure_active_after = pressure_state(
            pressure_active_before,
            filesystem_before.used_percent,
            config.high_watermark_pct,
            config.low_watermark_pct,
        );
        if !dry_run {
            context
                .runtime_config
                .sandbox_build_cache_pressure_active
                .store(pressure_active_after, Ordering::Relaxed);
        }

        let mut report = SandboxBuildCacheReclaimReport {
            version: SANDBOX_BUILD_CACHE_REPORT_VERSION,
            dry_run,
            enabled: config.enabled,
            config,
            pressure_active_before,
            pressure_active_after,
            filesystem_before,
            filesystem_after: filesystem_before,
            candidates_considered: 0,
            eligible_candidates: 0,
            skip_counts: std::collections::BTreeMap::new(),
            would_reclaim_count: 0,
            would_reclaim_bytes: 0,
            staged_count: 0,
            staged_bytes: 0,
            newly_staged_count: 0,
            newly_staged_bytes: 0,
            recovered_count: 0,
            recovered_bytes: 0,
            pending_count: 0,
            pending_bytes: 0,
            fully_removed_count: 0,
            reclaimed_bytes: 0,
            stopped_at_low_watermark: false,
            candidate_budget_exhausted: false,
            stop_reason: ReclaimStopReason::Completed,
        };

        // Registered v3 work is database-scheduled and remains actionable
        // even when reclaim policy is disabled or its former custody owner has
        // transitioned. Reserve before all legacy discovery and policy gates.
        let prepared_after = if prepared_only {
            *worker_state
                .prepared_cursors
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .get(&manager_key)
                .unwrap_or(&0)
        } else {
            0
        };
        let intent_page = tokio::time::timeout(RECLAIM_STORE_WAIT, context.store.lock())
            .await
            .map_or_else(
                |_| Err(reclaim_store_busy_error()),
                |store| {
                    let page = if prepared_only {
                        store
                            .prepared_target_reclaim_intent_page(
                                prepared_after,
                                config.max_candidates,
                            )
                            .map(|intents| {
                                let cursor = intents.last().map(|intent| intent.schedule_id);
                                (intents, None, cursor)
                            })
                    } else if dry_run {
                        store
                            .preview_target_reclaim_intent_page(config.max_candidates)
                            .map(|page| {
                                (page.intents, Some(wire_intent_sweep(&page.evidence)), None)
                            })
                    } else {
                        store
                            .reserve_target_reclaim_intent_page(config.max_candidates)
                            .map(|page| {
                                (page.intents, Some(wire_intent_sweep(&page.evidence)), None)
                            })
                    };
                    page.map(Some)
                },
            );
        let mut intent_sweep_wire = None;
        let mut registered_any = false;
        match intent_page {
            Ok(Some((intents, sweep_wire, cursor))) => {
                intent_sweep_wire = sweep_wire;
                if let Some(cursor) = cursor {
                    worker_state
                        .prepared_cursors
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .insert(manager_key, cursor);
                }
                for intent in intents {
                    let (outcome, intent_remains_pending) = tokio::task::spawn_blocking({
                        let context = context.clone();
                        let base = base.clone();
                        let pass_state = Arc::clone(&intent_recovery_pass_state);
                        let identity = (intent.custody_id, intent.generation);
                        move || {
                            let outcome = crate::sandbox::target_reclaim::with_reclaim_pass_state(
                                &pass_state,
                                || {
                                    recover_registered_target_intent(
                                        &context,
                                        &pass_state,
                                        &base,
                                        intent,
                                        dry_run,
                                        prepared_only,
                                    )
                                },
                            );
                            let remains_pending = context.store.try_lock().map_or(true, |store| {
                                store
                                    .target_reclaim_intent(identity.0, identity.1)
                                    .map_or(true, |intent| intent.is_some())
                            });
                            (outcome, remains_pending)
                        }
                    })
                    .await
                    .map_err(|error| DaemonError::Process(error.to_string()))?;
                    registered_any = true;
                    match outcome.kind {
                        TargetReclaimKind::Inspected => {
                            report.staged_count += 1;
                            report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                            report.pending_count += 1;
                            report.pending_bytes =
                                report.pending_bytes.saturating_add(outcome.bytes);
                        }
                        TargetReclaimKind::RecoveredRemoved => {
                            report.staged_count += 1;
                            report.recovered_count += 1;
                            report.recovered_bytes =
                                report.recovered_bytes.saturating_add(outcome.bytes);
                            report.fully_removed_count += 1;
                        }
                        TargetReclaimKind::RecoveredPending | TargetReclaimKind::Refused => {
                            if intent_remains_pending {
                                report.pending_count += 1;
                            }
                            increment_reclaim_skip(
                                &mut report,
                                outcome
                                    .reason
                                    .unwrap_or(ReclaimSkipReason::StagedDeletionIncomplete),
                            );
                        }
                        TargetReclaimKind::StagedRemoved | TargetReclaimKind::StagedPending => {
                            unreachable!("registered recovery cannot create candidate evidence")
                        }
                    }
                }
            }
            Ok(None) => unreachable!("successful intent reservation always returns a page"),
            Err(error) if is_reclaim_store_contention(&error) => {
                if !report
                    .skip_counts
                    .contains_key(&ReclaimSkipReason::StoreBusy)
                {
                    increment_reclaim_skip(&mut report, ReclaimSkipReason::StoreBusy);
                }
            }
            Err(error) => return Err(error),
        }

        if prepared_only {
            report.stop_reason = ReclaimStopReason::RecoveryOnly;
            return Ok(SandboxReclaimRun {
                report,
                evidence: SandboxReclaimEvidence::default(),
            });
        }

        let recovered = tokio::task::spawn_blocking({
            let base = base.clone();
            let pass_state = Arc::clone(&recovery_pass_state);
            move || {
                crate::sandbox::target_reclaim::recover_staged_targets_run_with_state(
                    &base,
                    dry_run,
                    &pass_state,
                )
            }
        })
        .await
        .map_err(|error| DaemonError::Process(error.to_string()))?;
        let recovered_any = registered_any || !recovered.outcomes.is_empty();
        let intent_counts = match context.store.try_lock() {
            Ok(store) => store
                .target_reclaim_intent_counts()
                .ok()
                .map(wire_intent_counts),
            Err(_) => None,
        };
        let mut recovery_sweep = wire_recovery_sweep(recovered.evidence);
        recovery_sweep.intent_sweep = intent_sweep_wire;
        recovery_sweep.intent_counts = intent_counts;
        let mut reclaim_evidence = SandboxReclaimEvidence {
            recovery_sweep,
            ..SandboxReclaimEvidence::default()
        };
        for outcome in recovered.outcomes {
            match outcome.kind {
                TargetReclaimKind::Inspected => {
                    report.staged_count += 1;
                    report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                    report.pending_count += 1;
                    report.pending_bytes = report.pending_bytes.saturating_add(outcome.bytes);
                }
                TargetReclaimKind::RecoveredRemoved => {
                    report.staged_count += 1;
                    report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                    report.recovered_count += 1;
                    report.recovered_bytes = report.recovered_bytes.saturating_add(outcome.bytes);
                    report.fully_removed_count += 1;
                }
                TargetReclaimKind::RecoveredPending => {
                    report.staged_count += 1;
                    report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                    report.recovered_count += 1;
                    report.recovered_bytes = report.recovered_bytes.saturating_add(outcome.bytes);
                    report.pending_count += 1;
                    report.pending_bytes = report.pending_bytes.saturating_add(outcome.bytes);
                    increment_reclaim_skip(
                        &mut report,
                        outcome
                            .reason
                            .unwrap_or(ReclaimSkipReason::StagedDeletionIncomplete),
                    );
                }
                TargetReclaimKind::Refused => {
                    let reason = outcome
                        .reason
                        .unwrap_or(ReclaimSkipReason::RejectedRecoveryEntry);
                    increment_reclaim_skip(&mut report, reason);
                    if outcome.terminal_rejection {
                        report.staged_count += 1;
                        report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                        report.recovered_count += 1;
                        report.recovered_bytes =
                            report.recovered_bytes.saturating_add(outcome.bytes);
                    }
                }
                TargetReclaimKind::StagedRemoved | TargetReclaimKind::StagedPending => {
                    unreachable!("recovery scan cannot create a new stage")
                }
            }
        }
        refresh_reclaimable_claims(&mut report, &recovery_pass_state);

        if !config.enabled {
            if !checkpoint_reclaim_report(&mut report, &pass_state) {
                report.stop_reason = if recovered_any {
                    ReclaimStopReason::RecoveryOnly
                } else {
                    ReclaimStopReason::Disabled
                };
            }
            if !dry_run {
                report.filesystem_after = sandbox_filesystem_stats(&base)?;
                report.reclaimed_bytes = report
                    .filesystem_after
                    .available_bytes
                    .saturating_sub(report.filesystem_before.available_bytes);
                report.pressure_active_after = pressure_state(
                    pressure_active_after,
                    report.filesystem_after.used_percent,
                    config.high_watermark_pct,
                    config.low_watermark_pct,
                );
                context
                    .runtime_config
                    .sandbox_build_cache_pressure_active
                    .store(report.pressure_active_after, Ordering::Relaxed);
            }
            checkpoint_reclaim_report(&mut report, &pass_state);
            return Ok(SandboxReclaimRun {
                report,
                evidence: reclaim_evidence,
            });
        }

        let page = tokio::time::timeout(RECLAIM_STORE_WAIT, context.store.lock())
            .await
            .map_or_else(
                |_| Err(reclaim_store_busy_error()),
                |store| {
                    if dry_run {
                        store.preview_terminal_reclaim_page(config.max_candidates)
                    } else {
                        store.reserve_terminal_reclaim_page(config.max_candidates)
                    }
                },
            );
        let page = match page {
            Ok(page) => page,
            Err(error) if is_reclaim_store_contention(&error) => {
                if !report
                    .skip_counts
                    .contains_key(&ReclaimSkipReason::StoreBusy)
                {
                    increment_reclaim_skip(&mut report, ReclaimSkipReason::StoreBusy);
                }
                report.stop_reason = ReclaimStopReason::AllRefused;
                if !dry_run {
                    report.filesystem_after = sandbox_filesystem_stats(&base)?;
                    report.reclaimed_bytes = report
                        .filesystem_after
                        .available_bytes
                        .saturating_sub(report.filesystem_before.available_bytes);
                    report.pressure_active_after = pressure_state(
                        pressure_active_after,
                        report.filesystem_after.used_percent,
                        config.high_watermark_pct,
                        config.low_watermark_pct,
                    );
                    context
                        .runtime_config
                        .sandbox_build_cache_pressure_active
                        .store(report.pressure_active_after, Ordering::Relaxed);
                }
                reclaim_evidence.pass_contention = Some(ReclaimPassContention::StoreBusy);
                return Ok(SandboxReclaimRun {
                    report,
                    evidence: reclaim_evidence,
                });
            }
            Err(error) => return Err(error),
        };
        pause_reclaim_after_page_for_test(&base);
        reclaim_evidence.candidate_sweep = Some(wire_candidate_sweep(&page.evidence));
        reclaim_evidence.inspected_terminal_rows = page.evidence.inspected_terminal_rows;
        reclaim_evidence.custody_lookups = page.evidence.custody_lookups;

        if checkpoint_reclaim_report(&mut report, &pass_state) {
            report.filesystem_after = if dry_run {
                simulated_filesystem_after(report.filesystem_before, report.would_reclaim_bytes)
            } else {
                sandbox_filesystem_stats(&base)?
            };
            checkpoint_reclaim_report(&mut report, &pass_state);
            report.pressure_active_after = pressure_state(
                pressure_active_after,
                report.filesystem_after.used_percent,
                config.high_watermark_pct,
                config.low_watermark_pct,
            );
            if !dry_run {
                context
                    .runtime_config
                    .sandbox_build_cache_pressure_active
                    .store(report.pressure_active_after, Ordering::Relaxed);
                report.reclaimed_bytes = report
                    .filesystem_after
                    .available_bytes
                    .saturating_sub(report.filesystem_before.available_bytes);
            }
            return Ok(SandboxReclaimRun {
                report,
                evidence: reclaim_evidence,
            });
        }

        if page.candidates.is_empty() {
            if !checkpoint_reclaim_report(&mut report, &pass_state) {
                report.stop_reason = if page.has_more {
                    report.candidate_budget_exhausted = true;
                    ReclaimStopReason::CandidateBudget
                } else if recovered_any {
                    ReclaimStopReason::RecoveryOnly
                } else {
                    ReclaimStopReason::NoCandidates
                };
            }
            if !dry_run {
                report.filesystem_after = sandbox_filesystem_stats(&base)?;
                report.reclaimed_bytes = report
                    .filesystem_after
                    .available_bytes
                    .saturating_sub(report.filesystem_before.available_bytes);
                report.pressure_active_after = pressure_state(
                    pressure_active_after,
                    report.filesystem_after.used_percent,
                    config.high_watermark_pct,
                    config.low_watermark_pct,
                );
                context
                    .runtime_config
                    .sandbox_build_cache_pressure_active
                    .store(report.pressure_active_after, Ordering::Relaxed);
            }
            checkpoint_reclaim_report(&mut report, &pass_state);
            return Ok(SandboxReclaimRun {
                report,
                evidence: reclaim_evidence,
            });
        }

        let now = chrono::Utc::now();
        let has_more = page.has_more;

        for candidate in page.candidates {
            if checkpoint_reclaim_report(&mut report, &pass_state) {
                break;
            }
            report.candidates_considered += 1;
            // Age gate: only reclaim after the owning row has been idle past
            // the TTL unless pressure hysteresis is active. An unparseable
            // timestamp fails closed (skip) even under pressure.
            let idle_secs: Option<u64> =
                chrono::DateTime::parse_from_rfc3339(&candidate.updated_at)
                    .ok()
                    .and_then(|timestamp| {
                        (now - timestamp.with_timezone(&chrono::Utc))
                            .num_seconds()
                            .try_into()
                            .ok()
                    });
            let Some(idle_secs) = idle_secs else {
                increment_reclaim_skip(&mut report, ReclaimSkipReason::FreshOrInvalidTimestamp);
                continue;
            };
            if !pressure_active_after && idle_secs < config.ttl_secs {
                increment_reclaim_skip(&mut report, ReclaimSkipReason::FreshOrInvalidTimestamp);
                continue;
            }

            // The candidate preflight performs Git and descriptor checks with
            // neither Store nor a root stripe held. Each later SQL phase joins
            // the FIFO Store queue for at most the remaining pass budget.
            if pass_state.remaining_duration().is_zero() {
                report.stop_reason = ReclaimStopReason::DurationBudget;
                break;
            }
            let active = Arc::clone(&context.active);
            let store_handle = Arc::clone(&context.store);
            let candidate_base = base.clone();
            let candidate_for_reclaim = candidate.clone();
            let candidate_pass_state = Arc::clone(&pass_state);
            let reclaimed = tokio::task::spawn_blocking(move || {
                let active_owner = || {
                    active
                        .try_read()
                        .map(|active| active.contains_key(&candidate_for_reclaim.session_id))
                        .map_err(|_| ReclaimSkipReason::ActiveMapBusy)
                };
                crate::sandbox::target_reclaim::with_reclaim_pass_state(
                    &candidate_pass_state,
                    || {
                        crate::sandbox::custody::CustodyService::reclaim_terminal_target_outcome_phased(
                            store_handle,
                            Arc::clone(&candidate_pass_state),
                            &active_owner,
                            candidate_for_reclaim.custody_id,
                            candidate_for_reclaim.generation,
                            &candidate_base,
                            !dry_run,
                        )
                    },
                )
            })
            .await
            .map_err(|error| DaemonError::Process(error.to_string()))?;
            pause_reclaim_after_attempt_for_test(&base);
            match reclaimed {
                Ok(outcome) if outcome.kind == TargetReclaimKind::Inspected => {
                    report.eligible_candidates += 1;
                    tracing::info!(
                        session_id = %candidate.session_id,
                        custody_id = %candidate.custody_id,
                        dry_run,
                        bytes = outcome.bytes,
                        "Authenticated terminal session build cache under custody fence"
                    );
                }
                Ok(outcome) if outcome.kind == TargetReclaimKind::StagedRemoved => {
                    report.eligible_candidates += 1;
                    report.staged_count += 1;
                    report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                    report.newly_staged_count += 1;
                    report.newly_staged_bytes =
                        report.newly_staged_bytes.saturating_add(outcome.bytes);
                    report.fully_removed_count += 1;
                }
                Ok(outcome) if outcome.kind == TargetReclaimKind::StagedPending => {
                    report.eligible_candidates += 1;
                    report.staged_count += 1;
                    report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                    report.newly_staged_count += 1;
                    report.newly_staged_bytes =
                        report.newly_staged_bytes.saturating_add(outcome.bytes);
                    report.pending_count += 1;
                    report.pending_bytes = report.pending_bytes.saturating_add(outcome.bytes);
                    increment_reclaim_skip(
                        &mut report,
                        outcome
                            .reason
                            .unwrap_or(ReclaimSkipReason::StagedDeletionIncomplete),
                    );
                    if let Some(stop) = outcome.reason.and_then(reclaim_budget_stop_reason) {
                        report.stop_reason = stop;
                    }
                }
                Ok(outcome) if outcome.kind == TargetReclaimKind::Refused => {
                    let reason = outcome
                        .reason
                        .unwrap_or(ReclaimSkipReason::GitOrRootIdentityRefusal);
                    increment_reclaim_skip(&mut report, reason);
                    if outcome.terminal_rejection {
                        report.eligible_candidates += 1;
                        report.staged_count += 1;
                        report.staged_bytes = report.staged_bytes.saturating_add(outcome.bytes);
                        report.newly_staged_count += 1;
                        report.newly_staged_bytes =
                            report.newly_staged_bytes.saturating_add(outcome.bytes);
                    } else if let Some(stop) = reclaim_budget_stop_reason(reason) {
                        report.stop_reason = stop;
                    }
                    tracing::info!(
                        session_id = %candidate.session_id,
                        custody_id = %candidate.custody_id,
                        reason = ?reason,
                        dry_run,
                        "Target-cache candidate refused"
                    );
                }
                Ok(_) => unreachable!("candidate path cannot return a recovery outcome"),
                Err(error) => {
                    increment_reclaim_skip(
                        &mut report,
                        ReclaimSkipReason::CustodyOrGenerationDrift,
                    );
                    tracing::warn!(
                        session_id = %candidate.session_id,
                        custody_id = %candidate.custody_id,
                        error = %error,
                        dry_run,
                        "Failed to inspect or reclaim terminal session build cache (skipped)"
                    );
                }
            }

            refresh_reclaimable_claims(&mut report, &pass_state);

            if is_reclaim_budget_stop(report.stop_reason) {
                break;
            }

            if pressure_active_after {
                report.filesystem_after = if dry_run {
                    simulated_filesystem_after(report.filesystem_before, report.would_reclaim_bytes)
                } else {
                    sandbox_filesystem_stats(&base)?
                };
                pressure_active_after = pressure_state(
                    true,
                    report.filesystem_after.used_percent,
                    config.high_watermark_pct,
                    config.low_watermark_pct,
                );
                if !pressure_active_after {
                    report.stopped_at_low_watermark = true;
                    report.stop_reason = ReclaimStopReason::LowWatermark;
                    break;
                }
            }
        }

        checkpoint_reclaim_report(&mut report, &pass_state);
        if !dry_run {
            report.filesystem_after = sandbox_filesystem_stats(&base)?;
            pressure_active_after = pressure_state(
                pressure_active_after,
                report.filesystem_after.used_percent,
                config.high_watermark_pct,
                config.low_watermark_pct,
            );
            context
                .runtime_config
                .sandbox_build_cache_pressure_active
                .store(pressure_active_after, Ordering::Relaxed);
        } else if !report.stopped_at_low_watermark {
            report.filesystem_after =
                simulated_filesystem_after(report.filesystem_before, report.would_reclaim_bytes);
            pressure_active_after = pressure_state(
                pressure_active_after,
                report.filesystem_after.used_percent,
                config.high_watermark_pct,
                config.low_watermark_pct,
            );
        }
        if !dry_run {
            report.reclaimed_bytes = report
                .filesystem_after
                .available_bytes
                .saturating_sub(report.filesystem_before.available_bytes);
        }
        checkpoint_reclaim_report(&mut report, &pass_state);
        report.pressure_active_after = pressure_active_after;
        let work_budget_stopped = is_reclaim_budget_stop(report.stop_reason);
        report.candidate_budget_exhausted =
            !work_budget_stopped && !report.stopped_at_low_watermark && has_more;
        if report.candidate_budget_exhausted {
            report.stop_reason = ReclaimStopReason::CandidateBudget;
        } else if report.stop_reason == ReclaimStopReason::Completed
            && report.eligible_candidates == 0
            && report.staged_count == 0
        {
            report.stop_reason = ReclaimStopReason::AllRefused;
        }
        if report
            .skip_counts
            .get(&ReclaimSkipReason::StoreBusy)
            .copied()
            .unwrap_or(0)
            > 0
        {
            reclaim_evidence.pass_contention = Some(ReclaimPassContention::StoreBusy);
        }
        Ok(SandboxReclaimRun {
            report,
            evidence: reclaim_evidence,
        })
    }

    /// Load a single terminal session from the store and synthesize the
    /// `CompletedSession` entry `restore_sessions` would have produced for it.
    /// `continue_session` falls back to this when a durably-completed session
    /// is missing from the in-memory `completed` map (e.g. a restart raced its
    /// restoration), so `Continue` does not report a false "Session not
    /// found" for a row that is intact in the database.
    pub(super) async fn load_completed_session_from_store(
        &self,
        session_id: Uuid,
    ) -> Result<Option<CompletedSession>> {
        let store = self.store.clone();
        let session = tokio::task::spawn_blocking(move || {
            let store = store.blocking_lock();
            store.get_session(session_id)
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;

        let Some(mut session) = session else {
            return Ok(None);
        };

        // Only rows the completed map is meant to hold are eligible here;
        // Running/Starting/WaitingApproval/Archived/Deleted stay a "not found"
        // for this path so callers don't accidentally resume something live,
        // hidden, or gone.
        if !matches!(
            session.status,
            SessionStatus::Completed | SessionStatus::Failed | SessionStatus::Interrupted
        ) {
            return Ok(None);
        }

        let store = self.store.clone();
        let sid = session.id;
        let (events, turn_metrics) = tokio::task::spawn_blocking(move || {
            let store = store.blocking_lock();
            let events = store.load_events(sid)?;
            let turn_metrics = store.load_turn_metrics(sid)?;
            Ok::<_, DaemonError>((events, turn_metrics))
        })
        .await
        .map_err(|e| DaemonError::Store(e.to_string()))??;

        sanitize_codex_restored_context_usage(&mut session, &turn_metrics);
        if session.total_input_tokens.unwrap_or(0) > 0 {
            session.context_usage_confidence = ContextUsageConfidence::Partial;
        }

        Ok(Some(CompletedSession {
            session,
            events,
            turn_metrics,
            retry_cancel: None,
            retry_fired_at: None,
            superseded_by_retry: None,
            events_hydrated: true,
        }))
    }
}

/// Returns `true` for statuses whose retained sandboxes need startup
/// classification. Completed / Failed / Interrupted sessions remain resumable.
fn should_purge_sandbox_on_restore(status: rsi_common::types::SessionStatus) -> bool {
    use rsi_common::types::SessionStatus::*;
    matches!(status, Archived | Deleted)
}

fn startup_candidate_from_row_read(
    session_id: Uuid,
    sandbox_root: &std::path::Path,
    session: Option<Session>,
) -> CleanupCandidate {
    session
        .as_ref()
        .map(cleanup::candidate_from_session)
        .unwrap_or_else(|| CleanupCandidate::RowReadFailure {
            session_id,
            root: sandbox_root.to_path_buf(),
        })
}

