    fn manager() -> (SessionManager, TempDir, TempDir) {
        manager_with_smoke_suppress_retry_restore(false)
    }

    // Reclaim tests share the process-wide bounded coordinator and test hooks.
    // Hold this only in tests that exercise that shared lifecycle so parallel
    // unit-test execution cannot replace a hook or fill another test's queue.
    fn reclaim_test_isolation() -> std::sync::MutexGuard<'static, ()> {
        crate::sandbox::target_reclaim::reclaim_test_isolation_for_test()
    }

    fn disk_backed_tempdir(label: &str) -> TempDir {
        let root = std::env::var_os("CARGO_TARGET_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("target"))
            .join("rsid-test-fixtures");
        std::fs::create_dir_all(&root).expect("create disk-backed test fixture root");
        tempfile::Builder::new()
            .prefix(label)
            .tempdir_in(root)
            .expect("create disk-backed test fixture")
    }

    fn manager_for_disk_fixture(
        db_dir: &std::path::Path,
        sandbox_base: &std::path::Path,
    ) -> SessionManager {
        let database = db_dir.join("rsi.db");
        let store = Store::open(&database).expect("open fixture Store");
        let mut config = Config::from_env();
        config.retry_max_backoff_ms = 1;
        let runtime_config = RuntimeConfig::from_config(&config);
        let mut manager = SessionManager::new(
            Arc::new(EventBus::new(16)),
            store,
            false,
            db_dir.join("daemon.sock"),
            None,
            Vec::new(),
            runtime_config,
            sandbox_base.to_path_buf(),
        )
        .expect("fixture manager");
        // `SessionManager::new` starts a polling watcher that retains its
        // original Store Arc. Give reclaim an independently reopened Store so
        // restart tests model daemon reconstruction without test-only watcher
        // reads creating nondeterministic effect-time contention.
        manager.store = Arc::new(tokio::sync::Mutex::new(
            Store::open(&database).expect("reopen fixture reclaim Store"),
        ));
        manager
    }

    #[test]
    fn pioneer_launch_default_migrates_retired_router_and_preserves_explicit_model() {
        let mut model = None;
        apply_provider_model_default(SessionProvider::Pioneer, &mut model);
        assert_eq!(
            model.as_deref(),
            Some(crate::pioneer::PIONEER_DEFAULT_MODEL)
        );

        let mut retired = Some(crate::pioneer::PIONEER_RETIRED_AUTO_MODEL.to_string());
        apply_provider_model_default(SessionProvider::Pioneer, &mut retired);
        assert_eq!(
            retired.as_deref(),
            Some(crate::pioneer::PIONEER_DEFAULT_MODEL)
        );

        let mut explicit = Some("pioneer/custom".to_string());
        apply_provider_model_default(SessionProvider::Pioneer, &mut explicit);
        assert_eq!(explicit.as_deref(), Some("pioneer/custom"));

        let mut codex = None;
        apply_provider_model_default(SessionProvider::Codex, &mut codex);
        assert!(codex.is_none());
    }

