    fn write_d03_fake_codex_app_server(dir: &std::path::Path) -> std::path::PathBuf {
        let path = dir.join("d03-fake-codex-app-server");
        std::fs::write(
            &path,
            r#"#!/bin/sh
trap 'exit 0' INT TERM
while IFS= read -r request; do
    case "$request" in
        *'"method":"initialize"'*)
            printf '%s\n' '{"jsonrpc":"2.0","id":1,"result":{"protocolVersion":"2024-11-05"}}'
            ;;
        *'"method":"thread/start"'*)
            printf '%s\n' '{"jsonrpc":"2.0","id":2,"result":{"thread":{"id":"d03-fake-thread"}}}'
            ;;
    esac
done
"#,
        )
        .expect("write fake app-server binary");
        let mut permissions = std::fs::metadata(&path)
            .expect("fake app-server metadata")
            .permissions();
        permissions.set_mode(0o755);
        std::fs::set_permissions(&path, permissions).expect("make fake app-server executable");
        path
    }

    fn init_d00_git_repo(path: &std::path::Path) {
        for args in [
            &["init", "-q", "-b", "main"][..],
            &["config", "user.email", "d00@example.invalid"][..],
            &["config", "user.name", "D00 Fixture"][..],
        ] {
            assert!(
                Command::new("git")
                    .args(args)
                    .current_dir(path)
                    .status()
                    .expect("run git")
                    .success()
            );
        }
        std::fs::write(path.join("README.md"), "fixture\n").expect("write fixture");
        assert!(
            Command::new("git")
                .args(["add", "README.md"])
                .current_dir(path)
                .status()
                .expect("git add")
                .success()
        );
        assert!(
            Command::new("git")
                .args(["commit", "-q", "-m", "initial"])
                .current_dir(path)
                .status()
                .expect("git commit")
                .success()
        );
    }

    fn git_stdout(path: &std::path::Path, args: &[&str]) -> String {
        let output = Command::new("git")
            .env("GIT_OPTIONAL_LOCKS", "0")
            .args(args)
            .current_dir(path)
            .output()
            .expect("run git");
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout).expect("git output utf8")
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct D00TreeEntry {
        relative_path: PathBuf,
        kind: &'static str,
        mode: u32,
        size: u64,
        content: Option<Vec<u8>>,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct D00IndexSnapshot {
        bytes: Vec<u8>,
        mode: u32,
        size: u64,
        modified_seconds: i64,
        modified_nanoseconds: i64,
        lock_exists: bool,
    }

    #[derive(Debug, Clone, PartialEq)]
    struct D00DurableEvidence {
        tree: Vec<D00TreeEntry>,
        refs: String,
        worktrees: String,
        index: D00IndexSnapshot,
        rows: Vec<(Uuid, Option<serde_json::Value>)>,
    }

    #[derive(Debug, Clone, PartialEq)]
    struct D00FullEvidence {
        durable: D00DurableEvidence,
        active: Vec<(Uuid, bool, serde_json::Value)>,
        completed: Vec<(Uuid, serde_json::Value)>,
    }

    fn d00_tree(root: &std::path::Path) -> Vec<D00TreeEntry> {
        let mut entries = WalkDir::new(root)
            .follow_links(false)
            .into_iter()
            .map(|entry| entry.expect("walk isolated sandbox"))
            .map(|entry| {
                let path = entry.path();
                let metadata = std::fs::symlink_metadata(path).expect("sandbox metadata");
                let file_type = metadata.file_type();
                let (kind, content) = if file_type.is_file() {
                    (
                        "file",
                        Some(std::fs::read(path).expect("read sandbox file")),
                    )
                } else if file_type.is_dir() {
                    ("dir", None)
                } else if file_type.is_symlink() {
                    (
                        "symlink",
                        Some(
                            std::fs::read_link(path)
                                .expect("read sandbox symlink")
                                .as_os_str()
                                .as_encoded_bytes()
                                .to_vec(),
                        ),
                    )
                } else {
                    ("other", None)
                };
                D00TreeEntry {
                    relative_path: path
                        .strip_prefix(root)
                        .expect("sandbox-relative path")
                        .to_path_buf(),
                    kind,
                    mode: metadata.permissions().mode(),
                    size: metadata.size(),
                    content,
                }
            })
            .collect::<Vec<_>>();
        entries.sort_by(|left, right| left.relative_path.cmp(&right.relative_path));
        entries
    }

    fn d00_linked_index(root: &std::path::Path) -> PathBuf {
        let path = PathBuf::from(git_stdout(root, &["rev-parse", "--git-path", "index"]).trim());
        if path.is_absolute() {
            path
        } else {
            root.join(path)
        }
    }

    fn d00_index_snapshot(root: &std::path::Path) -> D00IndexSnapshot {
        let index = d00_linked_index(root);
        let metadata = std::fs::metadata(&index).expect("linked worktree index metadata");
        D00IndexSnapshot {
            bytes: std::fs::read(&index).expect("linked worktree index bytes"),
            mode: metadata.mode(),
            size: metadata.size(),
            modified_seconds: metadata.mtime(),
            modified_nanoseconds: metadata.mtime_nsec(),
            lock_exists: index.with_extension("lock").exists(),
        }
    }

    async fn d00_durable_evidence(
        manager: &SessionManager,
        repo: &std::path::Path,
        root: &std::path::Path,
        row_ids: &[Uuid],
    ) -> D00DurableEvidence {
        let rows = {
            let store = manager.store.lock().await;
            row_ids
                .iter()
                .map(|session_id| {
                    (
                        *session_id,
                        store
                            .get_session(*session_id)
                            .expect("load D00 evidence row")
                            .map(|session| {
                                serde_json::to_value(session).expect("serialize D00 evidence row")
                            }),
                    )
                })
                .collect()
        };
        D00DurableEvidence {
            tree: d00_tree(root),
            refs: git_stdout(
                repo,
                &[
                    "for-each-ref",
                    "--format=%(refname) %(objectname)",
                    "refs/heads",
                ],
            ),
            worktrees: git_stdout(repo, &["worktree", "list", "--porcelain"]),
            index: d00_index_snapshot(root),
            rows,
        }
    }

    async fn d00_full_evidence(
        manager: &SessionManager,
        repo: &std::path::Path,
        root: &std::path::Path,
        row_ids: &[Uuid],
    ) -> D00FullEvidence {
        let durable = d00_durable_evidence(manager, repo, root, row_ids).await;
        let mut active = manager
            .active
            .read()
            .await
            .iter()
            .map(|(id, tracked)| {
                (
                    *id,
                    tracked.pending_archive,
                    serde_json::to_value(&tracked.session).expect("serialize active D00 evidence"),
                )
            })
            .collect::<Vec<_>>();
        active.sort_by_key(|(id, _, _)| *id);
        let mut completed = manager
            .completed
            .read()
            .await
            .iter()
            .map(|(id, completed)| {
                (
                    *id,
                    serde_json::to_value(&completed.session)
                        .expect("serialize completed D00 evidence"),
                )
            })
            .collect::<Vec<_>>();
        completed.sort_by_key(|(id, _)| *id);
        D00FullEvidence {
            durable,
            active,
            completed,
        }
    }

    fn assert_no_d00_success_events(
        event_bus: &EventBus,
        receiver: &mut tokio::sync::broadcast::Receiver<Arc<DaemonEvent>>,
    ) {
        while let Ok(event) = receiver.try_recv() {
            assert!(
                !matches!(
                    event.as_ref(),
                    DaemonEvent::SandboxOrphanCleaned { .. }
                        | DaemonEvent::SessionArchived { .. }
                        | DaemonEvent::SessionDeleted { .. }
                ),
                "blocked cleanup emitted success event: {event:?}"
            );
        }
        event_bus.unsubscribe();
    }

    async fn drain_d00_persistence(manager: &SessionManager) {
        for _ in 0..10_000 {
            if manager.persistence.pending.load(Ordering::SeqCst) == 0 {
                return;
            }
            tokio::task::yield_now().await;
        }
        panic!("D00 persistence worker did not drain");
    }

    async fn wait_for_d00_pending_archive(
        manager: &SessionManager,
        session_id: Uuid,
        pending_archive: bool,
    ) {
        for _ in 0..10_000 {
            let matches = manager
                .store
                .lock()
                .await
                .get_session(session_id)
                .expect("load pending-archive fixture row")
                .is_some_and(|session| session.pending_archive == pending_archive);
            if matches {
                return;
            }
            tokio::task::yield_now().await;
        }
        panic!("pending_archive persistence worker did not reach expected state");
    }

    #[test]
    fn launch_abort_guard_retains_root_registration_ref_and_content() {
        let repo = TempDir::new().expect("repo tempdir");
        let base = TempDir::new().expect("sandbox tempdir");
        init_d00_git_repo(repo.path());
        let session_id = Uuid::new_v4();
        let allocation = crate::sandbox::SandboxAllocator::new(base.path().to_path_buf())
            .allocate(
                session_id,
                repo.path(),
                SandboxKind::GitWorktree,
                "HEAD",
                None,
            )
            .expect("allocate sandbox");
        let marker = allocation.root.join("uncommitted.txt");
        std::fs::write(&marker, "recoverable launch-abort work\n").expect("write marker");
        let branch = allocation.branch.clone().expect("sandbox branch");
        let worktrees_before = git_stdout(repo.path(), &["worktree", "list", "--porcelain"]);
        let ref_before = git_stdout(
            repo.path(),
            &["rev-parse", "--verify", &format!("refs/heads/{branch}")],
        );
        let content_before = std::fs::read(&marker).expect("read marker");

        drop(SandboxLaunchGuard {
            session_id,
            allocation: Some(allocation.clone()),
        });

        assert!(allocation.root.exists());
        assert_eq!(
            std::fs::read(&marker).expect("read retained marker"),
            content_before
        );
        assert_eq!(
            git_stdout(repo.path(), &["worktree", "list", "--porcelain"]),
            worktrees_before
        );
        assert_eq!(
            git_stdout(
                repo.path(),
                &["rev-parse", "--verify", &format!("refs/heads/{branch}")],
            ),
            ref_before
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn launch_abort_then_restore_path_only_is_inert() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let session_id = Uuid::new_v4();
        let allocation = crate::sandbox::SandboxAllocator::new(sandbox_base.path().to_path_buf())
            .allocate(
                session_id,
                repo.path(),
                SandboxKind::GitWorktree,
                "HEAD",
                None,
            )
            .expect("allocate sandbox");
        std::fs::write(
            allocation.root.join("recoverable.txt"),
            "launch-abort recovery\n",
        )
        .expect("write recoverable launch-abort content");

        drop(SandboxLaunchGuard {
            session_id,
            allocation: Some(allocation.clone()),
        });

        let before = d00_durable_evidence(&manager, repo.path(), &allocation.root, &[]).await;
        assert!(!before.index.lock_exists);
        let mut events = manager.event_bus().subscribe();
        manager
            .restore_sessions()
            .await
            .expect("restart classification");
        assert_eq!(
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[]).await,
            before
        );
        assert_no_d00_success_events(manager.event_bus(), &mut events);
    }

    #[test]
    fn startup_row_read_failure_candidate_is_inert() {
        let base = TempDir::new().expect("sandbox tempdir");
        let session_id = Uuid::new_v4();
        let root = base.path().join(session_id.to_string());
        std::fs::create_dir_all(&root).expect("create attributed root");
        let marker = root.join("retained.txt");
        std::fs::write(&marker, "retained\n").expect("write marker");
        let candidate = startup_candidate_from_row_read(session_id, &root, None);

        assert_eq!(
            cleanup::classify_candidate(
                &candidate,
                OwnershipObservation::Exclusive,
                OwnershipObservation::Exclusive,
            ),
            CleanupDecision::Blocked(cleanup::CleanupBlockedReason::RowReadFailure)
        );
        assert_eq!(
            std::fs::read_to_string(marker).expect("read retained marker"),
            "retained\n"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn runtime_ownership_read_failure_is_inert_in_isolated_repository() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let (session, allocation, candidate) = d00_sandbox_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
        )
        .await;
        let before =
            d00_full_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        let mut events = manager.event_bus().subscribe();

        {
            let store = manager.store.lock().await;
            store
                .conn
                .execute_batch("ALTER TABLE sessions RENAME TO d00_unreadable_sessions;")
                .expect("hide sessions table from runtime ownership lookup");
        }
        let decision = manager.classify_cleanup_candidate(candidate).await;
        {
            let store = manager.store.lock().await;
            store
                .conn
                .execute_batch("ALTER TABLE d00_unreadable_sessions RENAME TO sessions;")
                .expect("restore sessions table after injected read failure");
        }

        assert_eq!(
            decision,
            CleanupDecision::Blocked(cleanup::CleanupBlockedReason::OwnershipReadFailure)
        );
        assert_eq!(
            d00_full_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await,
            before
        );
        assert_no_d00_success_events(manager.event_bus(), &mut events);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn runtime_ownership_drift_is_compared_to_post_external_snapshot() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let (session, allocation, candidate) = d00_sandbox_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
        )
        .await;
        let before =
            d00_full_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        let mut events = manager.event_bus().subscribe();

        let mut second = test_session(Uuid::new_v4());
        second.working_dir = repo.path().to_path_buf();
        second.status = SessionStatus::Completed;
        second.sandbox_kind = Some(SandboxKind::GitWorktree);
        second.sandbox_root = Some(allocation.root.clone());
        second.sandbox_branch = allocation.branch.clone();
        second.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
        let classify = manager.classify_cleanup_candidate(candidate);
        let external_drift = async {
            manager
                .completed
                .write()
                .await
                .insert(second.id, d00_completed_session(second));
            d00_full_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await
        };
        let (decision, post_external) = tokio::join!(classify, external_drift);

        assert_eq!(
            decision,
            CleanupDecision::Blocked(cleanup::CleanupBlockedReason::ConcurrentDrift)
        );
        let after = d00_full_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        assert_eq!(after, post_external);
        assert_eq!(after.durable, before.durable);
        assert_no_d00_success_events(manager.event_bus(), &mut events);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn restore_row_reread_failure_uses_sweep_and_is_inert() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let (session, allocation, _) = d00_sandbox_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Archived,
        )
        .await;
        let before =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        let mut events = manager.event_bus().subscribe();
        {
            let mut guard = D00_STARTUP_ROW_REREAD_FAILURE
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *guard = Some(session.id);
        }

        manager
            .restore_sessions()
            .await
            .expect("restore must classify injected row re-read failure");

        assert!(
            D00_STARTUP_ROW_REREAD_FAILURE
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_none(),
            "startup sweep must consume the exact row re-read failure seam"
        );
        let after =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        assert_eq!(after.tree, before.tree);
        assert_eq!(after.refs, before.refs);
        assert_eq!(after.worktrees, before.worktrees);
        assert_eq!(after.index, before.index);
        assert_eq!(after.rows.len(), 1);
        assert_eq!(after.rows[0].0, before.rows[0].0);
        let before_row = before.rows[0].1.as_ref().expect("before row");
        let after_row = after.rows[0].1.as_ref().expect("after row");
        let before_updated_at = chrono::DateTime::parse_from_rfc3339(
            before_row["updated_at"]
                .as_str()
                .expect("before updated_at"),
        )
        .expect("parse before updated_at");
        let after_updated_at = chrono::DateTime::parse_from_rfc3339(
            after_row["updated_at"].as_str().expect("after updated_at"),
        )
        .expect("parse after updated_at");
        assert!(
            after_updated_at >= before_updated_at,
            "startup reconciliation must not move updated_at backwards"
        );
        let mut normalized_after_row = after_row.clone();
        normalized_after_row["updated_at"] = before_row["updated_at"].clone();
        assert_eq!(&normalized_after_row, before_row);
        assert_no_d00_success_events(manager.event_bus(), &mut events);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn pending_archive_admission_retains_the_sandbox_in_an_isolated_repository() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let (mut session, allocation, _) = d00_sandbox_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Running,
        )
        .await;
        session.status = SessionStatus::Running;
        manager
            .active
            .write()
            .await
            .insert(session.id, TrackedSession::new_for_test(session.clone()));
        let before =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        let mut events = manager.event_bus().subscribe();

        manager
            .mark_pending_archive(session.id, true)
            .await
            .expect("pending archive must not require physical cleanup proof");
        wait_for_d00_pending_archive(&manager, session.id, true).await;
        let after =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        assert_eq!(after.tree, before.tree);
        assert_eq!(after.refs, before.refs);
        assert_eq!(after.worktrees, before.worktrees);
        assert_eq!(after.index, before.index);
        let after_row = after.rows[0].1.as_ref().expect("pending archive row");
        assert_eq!(
            after_row
                .get("pending_archive")
                .and_then(serde_json::Value::as_bool),
            Some(true)
        );
        assert_eq!(
            after_row.get("sandbox_root"),
            before.rows[0]
                .1
                .as_ref()
                .expect("original sandbox row")
                .get("sandbox_root")
        );
        let before_row = before.rows[0].1.as_ref().expect("original sandbox row");
        for field in [
            "sandbox_kind",
            "sandbox_root",
            "sandbox_branch",
            "sandbox_cleanup_state",
        ] {
            assert_eq!(after_row.get(field), before_row.get(field), "{field}");
        }
        assert!(
            manager
                .active
                .read()
                .await
                .get(&session.id)
                .expect("active sandbox session")
                .pending_archive
        );
        assert_no_d00_success_events(manager.event_bus(), &mut events);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn terminal_pending_archive_commits_metadata_without_sandbox_cleanup() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let (mut session, allocation, _) = d00_sandbox_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Running,
        )
        .await;
        session.pending_archive = true;
        manager
            .store
            .lock()
            .await
            .update_pending_archive(session.id, true)
            .expect("set durable pending archive");
        let mut tracked = TrackedSession::new_for_test(session.clone());
        tracked.pending_archive = true;
        tracked.received_meaningful_output = true;
        manager.active.write().await.insert(session.id, tracked);
        std::fs::write(allocation.root.join("terminal.txt"), "terminal work\n")
            .expect("write terminal work");
        let before =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        let mut events = manager.event_bus().subscribe();

        SessionManager::finalize_session(
            session.id,
            0,
            crate::session::types::TerminalFinalizeDecision::completed(),
            Arc::clone(&manager.active),
            Arc::clone(&manager.completed),
            Arc::clone(&manager.event_bus),
            Arc::clone(&manager.store),
            manager.persistence.clone(),
            None,
            Arc::clone(&manager.runtime_config),
        )
        .await;
        drain_d00_persistence(&manager).await;

        let after =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        assert_eq!(after.tree, before.tree);
        assert_eq!(after.refs, before.refs);
        assert_eq!(after.worktrees, before.worktrees);
        assert_eq!(after.index, before.index);
        let before_row = before.rows[0].1.as_ref().expect("before row");
        let after_row = after.rows[0].1.as_ref().expect("after row");
        for field in [
            "sandbox_kind",
            "sandbox_root",
            "sandbox_branch",
            "sandbox_cleanup_state",
            "parent_id",
            "lead_session_id",
        ] {
            assert_eq!(after_row.get(field), before_row.get(field), "{field}");
        }
        assert_eq!(
            after_row.get("status").and_then(serde_json::Value::as_str),
            Some("Archived")
        );
        assert_eq!(
            after_row
                .get("pending_archive")
                .and_then(serde_json::Value::as_bool),
            Some(false)
        );
        assert!(!manager.active.read().await.contains_key(&session.id));
        assert!(!manager.completed.read().await.contains_key(&session.id));
        let archived = std::iter::from_fn(|| events.try_recv().ok())
            .any(|event| matches!(event.as_ref(), DaemonEvent::SessionArchived { .. }));
        assert!(archived, "terminal auto-archive must emit success");
        manager.event_bus().unsubscribe();
    }

    fn manager_with_smoke_suppress_retry_restore(
        smoke_suppress_retry_restore: bool,
    ) -> (SessionManager, TempDir, TempDir) {
        let dir = TempDir::new().expect("temp db dir");
        let sandbox_base = TempDir::new().expect("temp sandbox dir");
        let db_path = dir.path().join("rsi.db");
        let store = Store::open(&db_path).expect("open store");
        let mut config = Config::from_env();
        config.retry_max_backoff_ms = 1;
        config.smoke_suppress_retry_restore = smoke_suppress_retry_restore;
        let runtime_config = RuntimeConfig::from_config(&config);
        let manager = SessionManager::new(
            Arc::new(EventBus::new(16)),
            store,
            false,
            dir.path().join("daemon.sock"),
            None,
            Vec::new(),
            runtime_config,
            sandbox_base.path().to_path_buf(),
        )
        .expect("manager");
        (manager, dir, sandbox_base)
    }

