    async fn d00_sandbox_row(
        manager: &SessionManager,
        repo: &std::path::Path,
        sandbox_base: &std::path::Path,
        status: SessionStatus,
    ) -> (Session, SandboxAllocation, CleanupCandidate) {
        let session_id = Uuid::new_v4();
        let allocation = crate::sandbox::SandboxAllocator::new(sandbox_base.to_path_buf())
            .allocate(session_id, repo, SandboxKind::GitWorktree, "HEAD", None)
            .expect("allocate D00 sandbox");
        let mut session = test_session(session_id);
        session.working_dir = repo.to_path_buf();
        session.status = status;
        session.sandbox_kind = Some(SandboxKind::GitWorktree);
        session.sandbox_root = Some(allocation.root.clone());
        session.sandbox_branch = allocation.branch.clone();
        session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
        manager
            .store
            .lock()
            .await
            .insert_session(&session)
            .expect("insert D00 sandbox row");
        let candidate = cleanup::candidate_from_session(&session);
        (session, allocation, candidate)
    }

