    #[tokio::test]
    async fn build_cache_reclaim_preview_excludes_external_hard_link_from_low_watermark_claim() {
        let _isolation = reclaim_test_isolation();
        let (manager, _db, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo dir");
        init_d00_git_repo(repo.path());
        let (session, cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            chrono::Utc::now() - chrono::Duration::hours(8),
        )
        .await;
        std::fs::remove_dir_all(cache.join("debug")).unwrap();
        let file = cache.join("externally-retained");
        std::fs::write(&file, vec![5_u8; 8 * 1024 * 1024]).unwrap();
        std::fs::File::open(&file).unwrap().sync_all().unwrap();
        let external = sandbox_base.path().join("external-hard-link");
        std::fs::hard_link(&file, &external).unwrap();
        let allocated = std::fs::metadata(&file).unwrap().blocks() * 512;
        let pinned = crate::sandbox::target_reclaim::PinnedSandboxRoot::open(
            sandbox_base.path(),
            cache.parent().unwrap(),
            session.id,
        )
        .unwrap();
        let footprint = pinned.inspect_target().bytes;
        manager.persistence.barrier().await.unwrap();

        let preview = run_build_cache_reclaim_fixture(&manager, true).await;
        assert_eq!(preview.eligible_candidates, 1);
        assert_eq!(preview.would_reclaim_bytes, 0);
        assert!(footprint >= allocated);
        assert!(!preview.stopped_at_low_watermark);
        assert_eq!(
            preview.filesystem_after,
            simulated_filesystem_after(preview.filesystem_before, preview.would_reclaim_bytes)
        );

        let before = sandbox_filesystem_stats(sandbox_base.path()).unwrap();
        let actual = run_build_cache_reclaim_fixture(&manager, false).await;
        let after = sandbox_filesystem_stats(sandbox_base.path()).unwrap();
        assert_eq!(actual.fully_removed_count, 1);
        assert!(external.exists());
        assert_eq!(
            std::fs::metadata(&external).unwrap().blocks() * 512,
            allocated
        );
        assert!(
            after.available_bytes.saturating_sub(before.available_bytes) < allocated,
            "actual statvfs must not free externally retained data blocks"
        );
    }

    #[tokio::test]
    async fn build_cache_reclaim_post_sizing_hard_link_race_claims_no_future_capacity() {
        let _isolation = reclaim_test_isolation();
        let db_dir = disk_backed_tempdir("reclaim-hard-link-race-db");
        let sandbox_base = disk_backed_tempdir("reclaim-hard-link-race-sandbox");
        let manager = manager_for_disk_fixture(db_dir.path(), sandbox_base.path());
        let repo = TempDir::new().expect("repo dir");
        init_d00_git_repo(repo.path());
        let (session, cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            chrono::Utc::now() - chrono::Duration::hours(8),
        )
        .await;
        std::fs::remove_dir_all(cache.join("debug")).unwrap();
        let file = cache.join("post-sizing-race");
        std::fs::write(&file, vec![7_u8; 8 * 1024 * 1024]).unwrap();
        std::fs::File::open(&file).unwrap().sync_all().unwrap();
        let allocated = std::fs::metadata(&file).unwrap().blocks() * 512;
        let external = sandbox_base.path().join("post-sizing-retaining-link");
        manager.persistence.barrier().await.unwrap();
        let custody_id = manager
            .store
            .lock()
            .await
            .preview_terminal_reclaim_page(64)
            .unwrap()
            .candidates
            .into_iter()
            .find(|candidate| candidate.session_id == session.id)
            .expect("candidate custody")
            .custody_id;
        manager
            .runtime_config
            .update_field(
                "sandbox_build_cache_reclaim_low_watermark_pct",
                &serde_json::json!(1),
            )
            .unwrap();
        manager
            .runtime_config
            .sandbox_build_cache_pressure_active
            .store(true, Ordering::Relaxed);

        let (reached_tx, reached_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        crate::sandbox::target_reclaim::set_post_authentication_signal_for_test(
            custody_id, reached_tx, release_rx,
        );
        let raced_file = file.clone();
        let raced_external = external.clone();
        let attacker = std::thread::spawn(move || {
            reached_rx
                .recv_timeout(Duration::from_secs(2))
                .expect("post-authentication reclaim seam");
            std::fs::hard_link(raced_file, raced_external).expect("create retaining hard link");
            release_tx
                .send(())
                .expect("release post-authentication reclaim seam");
        });

        let report = run_build_cache_reclaim_fixture(&manager, false).await;
        attacker.join().unwrap();
        assert_eq!(report.fully_removed_count, 1, "{report:?}");
        assert_eq!(report.would_reclaim_bytes, 0);
        assert_eq!(report.would_reclaim_count, 0);
        assert!(!report.stopped_at_low_watermark);
        assert!(external.exists(), "external retaining link must survive");
        assert_eq!(
            std::fs::metadata(&external).unwrap().blocks() * 512,
            allocated
        );
        assert!(!cache.exists());
    }

    #[tokio::test]
    async fn build_cache_reclaim_preview_counts_cross_candidate_hard_link_once() {
        let _isolation = reclaim_test_isolation();
        let (manager, _db, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo dir");
        init_d00_git_repo(repo.path());
        let stale = chrono::Utc::now() - chrono::Duration::hours(8);
        let (first_session, first_cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        let (second_session, second_cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        std::fs::remove_dir_all(first_cache.join("debug")).unwrap();
        std::fs::remove_dir_all(second_cache.join("debug")).unwrap();
        let first_file = first_cache.join("shared");
        let second_file = second_cache.join("shared");
        std::fs::write(&first_file, vec![6_u8; 8 * 1024 * 1024]).unwrap();
        std::fs::File::open(&first_file)
            .unwrap()
            .sync_all()
            .unwrap();
        std::fs::hard_link(&first_file, &second_file).unwrap();
        let allocated = std::fs::metadata(&first_file).unwrap().blocks() * 512;
        let first = crate::sandbox::target_reclaim::PinnedSandboxRoot::open(
            sandbox_base.path(),
            first_cache.parent().unwrap(),
            first_session.id,
        )
        .unwrap();
        let second = crate::sandbox::target_reclaim::PinnedSandboxRoot::open(
            sandbox_base.path(),
            second_cache.parent().unwrap(),
            second_session.id,
        )
        .unwrap();
        let first_footprint = first.inspect_target().bytes;
        let second_footprint = second.inspect_target().bytes;
        manager.persistence.barrier().await.unwrap();

        let mut preview = None;
        for _ in 0..5 {
            manager.persistence.barrier().await.unwrap();
            let report = manager
                .run_sandbox_build_cache_reclaim(true)
                .await
                .expect("cross-candidate preview");
            if report.eligible_candidates == 2 {
                preview = Some(report);
                break;
            }
            assert!(
                report
                    .skip_counts
                    .contains_key(&ReclaimSkipReason::StoreBusy),
                "only typed transient Store contention may defer the exact preview: {report:?}"
            );
        }
        let preview = preview.expect("both hard-linked candidates share one preview pass");
        assert_eq!(preview.eligible_candidates, 2, "{preview:?}");
        assert!(first_footprint.saturating_add(second_footprint) >= allocated);
        assert_eq!(preview.would_reclaim_bytes, 0);
        assert_eq!(preview.would_reclaim_count, 0);
        assert!(!preview.stopped_at_low_watermark);
        let before = sandbox_filesystem_stats(sandbox_base.path()).unwrap();
        let mut fully_removed = 0;
        for _ in 0..5 {
            manager.persistence.barrier().await.unwrap();
            let report = manager
                .run_sandbox_build_cache_reclaim(false)
                .await
                .expect("cross-candidate actual pass");
            fully_removed += report.fully_removed_count;
            if !first_file.exists() && !second_file.exists() {
                break;
            }
        }
        let after = sandbox_filesystem_stats(sandbox_base.path()).unwrap();
        assert_eq!(fully_removed, 2);
        assert!(!first_file.exists() && !second_file.exists());
        assert!(after.available_bytes >= before.available_bytes);
    }

