    #[tokio::test]
    async fn build_cache_reclaim_pages_past_absent_equal_timestamp_targets() {
        let _isolation = reclaim_test_isolation();
        let db_dir = disk_backed_tempdir("reclaim-paging-db");
        let sandbox_base = disk_backed_tempdir("reclaim-paging-sandbox");
        let manager = manager_for_disk_fixture(db_dir.path(), sandbox_base.path());
        let repo = TempDir::new().expect("repo dir");
        init_d00_git_repo(repo.path());
        let stale = chrono::Utc::now() - chrono::Duration::hours(9);
        let mut rows = Vec::new();
        for _ in 0..3 {
            rows.push(
                build_cache_row(
                    &manager,
                    repo.path(),
                    sandbox_base.path(),
                    SessionStatus::Completed,
                    stale,
                )
                .await,
            );
        }
        rows.sort_by_key(|(session, _cache)| session.id);
        for (_session, cache) in rows.iter().take(2) {
            std::fs::remove_dir_all(cache).expect("remove stale target cache");
        }
        let reclaimable_cache = rows[2].1.clone();
        manager.persistence.barrier().await.unwrap();
        manager
            .runtime_config
            .update_field(
                "sandbox_build_cache_reclaim_max_candidates",
                &serde_json::json!(2),
            )
            .unwrap();

        let first = run_build_cache_reclaim_fixture(&manager, false).await;
        assert_eq!(first.candidates_considered, 2, "{first:?}");
        assert_eq!(
            first.skip_counts.get(&ReclaimSkipReason::TargetAbsent),
            Some(&2),
            "{first:?}"
        );
        assert!(first.candidate_budget_exhausted, "{first:?}");
        assert!(reclaimable_cache.exists());
        let cursor_after_absent_page = manager
            .store
            .lock()
            .await
            .preview_terminal_reclaim_page(2)
            .unwrap()
            .evidence
            .cursor_before
            .expect("full absent page advances the cursor");
        assert_eq!(cursor_after_absent_page.updated_at, stale.to_rfc3339());
        assert_eq!(cursor_after_absent_page.session_id, rows[1].0.id);

        let preview = run_build_cache_reclaim_fixture(&manager, true).await;
        assert_eq!(preview.candidates_considered, 1, "{preview:?}");
        assert_eq!(preview.eligible_candidates, 1, "{preview:?}");
        assert!(reclaimable_cache.exists(), "dry-run must retain the cache");
        assert_eq!(
            manager
                .store
                .lock()
                .await
                .preview_terminal_reclaim_page(2)
                .unwrap()
                .evidence
                .cursor_before,
            Some(cursor_after_absent_page),
            "dry-run must not mutate durable cursor"
        );

        let second = run_build_cache_reclaim_fixture(&manager, false).await;
        assert_eq!(second.candidates_considered, 1, "{second:?}");
        assert_eq!(second.fully_removed_count, 1, "{second:?}");
        assert!(!reclaimable_cache.exists());
        assert!(
            manager
                .store
                .lock()
                .await
                .preview_terminal_reclaim_page(2)
                .unwrap()
                .evidence
                .cursor_before
                .is_some(),
            "last candidate remains the durable end marker until wrap"
        );

        let wrap = run_build_cache_reclaim_fixture(&manager, false).await;
        assert_eq!(wrap.candidates_considered, 0, "{wrap:?}");
        assert_eq!(wrap.stop_reason, ReclaimStopReason::NoCandidates);
        let wrapped = run_build_cache_reclaim_fixture(&manager, false).await;
        assert_eq!(wrapped.candidates_considered, 2, "{wrapped:?}");
        assert_eq!(
            wrapped.skip_counts.get(&ReclaimSkipReason::TargetAbsent),
            Some(&2),
            "the next pass must wrap and revisit transiently refused rows"
        );
    }

