    #[tokio::test]
    async fn sandbox_build_cache_reclaim_waits_for_store_before_candidate_effect() {
        let _isolation = reclaim_test_isolation();
        let db_dir = disk_backed_tempdir("effect-store-busy-db-");
        let sandbox_base = disk_backed_tempdir("effect-store-busy-sandboxes-");
        let repo = disk_backed_tempdir("effect-store-busy-repo-");
        init_d00_git_repo(repo.path());
        let manager = manager_for_disk_fixture(db_dir.path(), sandbox_base.path());
        let stale = chrono::Utc::now() - chrono::Duration::hours(8);
        let mut caches = HashMap::new();
        for _ in 0..2 {
            let (session, cache) = build_cache_row(
                &manager,
                repo.path(),
                sandbox_base.path(),
                SessionStatus::Completed,
                stale,
            )
            .await;
            caches.insert(session.id, cache);
        }
        manager.persistence.barrier().await.unwrap();
        manager
            .runtime_config
            .update_field(
                "sandbox_build_cache_reclaim_max_candidates",
                &serde_json::json!(2),
            )
            .unwrap();
        let page_reached = Arc::new(Barrier::new(2));
        let page_release = Arc::new(Barrier::new(2));
        let attempt_reached = Arc::new(Barrier::new(2));
        let attempt_release = Arc::new(Barrier::new(2));
        *reclaim_contention_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ReclaimContentionHook {
            base: sandbox_base.path().to_path_buf(),
            page_reached: Arc::clone(&page_reached),
            page_release: Arc::clone(&page_release),
            attempt_reached: Arc::clone(&attempt_reached),
            attempt_release: Arc::clone(&attempt_release),
        });
        let store = Arc::clone(&manager.store);
        let controller = std::thread::spawn(move || {
            page_reached.wait();
            let guard = store.blocking_lock();
            page_release.wait();
            std::thread::sleep(Duration::from_millis(100));
            drop(guard);
            for _ in 0..2 {
                attempt_reached.wait();
                attempt_release.wait();
            }
        });

        let first = manager
            .run_sandbox_build_cache_reclaim_with_evidence_for_trigger(false, "store_busy_test")
            .await
            .expect("contended pass waits for store");
        controller.join().unwrap();
        *reclaim_contention_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        assert_eq!(first.report.candidates_considered, 2, "{first:?}");
        assert_eq!(first.report.fully_removed_count, 2, "{first:?}");
        assert_eq!(first.evidence.pass_contention, None);
        for cache in caches.values() {
            assert!(!cache.exists(), "each authenticated target is reclaimed");
        }
    }

    #[tokio::test]
    async fn sandbox_build_cache_reclaim_releases_store_during_target_deletion() {
        let _isolation = reclaim_test_isolation();
        let db_dir = disk_backed_tempdir("reclaim-unlocked-db-");
        let sandbox_base = disk_backed_tempdir("reclaim-unlocked-sandboxes-");
        let repo = disk_backed_tempdir("reclaim-unlocked-repo-");
        init_d00_git_repo(repo.path());
        let manager = manager_for_disk_fixture(db_dir.path(), sandbox_base.path());
        let (session, cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            chrono::Utc::now() - chrono::Duration::hours(8),
        )
        .await;
        manager.persistence.barrier().await.unwrap();

        let reached = Arc::new(Barrier::new(2));
        let release = Arc::new(Barrier::new(2));
        crate::sandbox::custody::set_reclaim_before_delete_hook(Some((
            sandbox_base.path().to_path_buf(),
            Arc::clone(&reached),
            Arc::clone(&release),
        )));
        let store = Arc::clone(&manager.store);
        let custody_id = manager
            .store
            .lock()
            .await
            .live_custody_for_session(session.id)
            .expect("fixture custody")
            .custody_id;
        let observer = std::thread::spawn(move || {
            reached.wait();
            let deadline = Instant::now() + Duration::from_millis(500);
            let acquired = loop {
                if let Ok(guard) = store.try_lock() {
                    let root = crate::store::sandbox_custody::try_lock_custody_root(custody_id);
                    drop(guard);
                    break root.is_some();
                }
                if Instant::now() >= deadline {
                    break false;
                }
                std::thread::sleep(Duration::from_millis(1));
            };
            release.wait();
            acquired
        });
        let report = manager
            .run_sandbox_build_cache_reclaim(false)
            .await
            .unwrap();
        let store_available = observer.join().unwrap();
        crate::sandbox::custody::set_reclaim_before_delete_hook(None);

        assert!(
            store_available,
            "Store and the root stripe remain available while target deletion waits"
        );
        assert_eq!(report.fully_removed_count, 1, "{report:?}");
        assert!(!cache.exists(), "the authenticated target is reclaimed");
    }

    #[tokio::test]
    async fn sandbox_build_cache_reclaim_candidate_store_timeout_is_bounded_and_retryable() {
        let _isolation = reclaim_test_isolation();
        let db_dir = disk_backed_tempdir("reclaim-timeout-db-");
        let sandbox_base = disk_backed_tempdir("reclaim-timeout-sandboxes-");
        let repo = disk_backed_tempdir("reclaim-timeout-repo-");
        init_d00_git_repo(repo.path());
        let manager = manager_for_disk_fixture(db_dir.path(), sandbox_base.path());
        let (_session, cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            chrono::Utc::now() - chrono::Duration::hours(8),
        )
        .await;
        manager.persistence.barrier().await.unwrap();
        let manager_key = sandbox_reclaim_manager_key(&manager.store);
        reclaim_pass_state_overrides()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(
                manager_key,
                crate::sandbox::target_reclaim::ReclaimPassState::for_test(
                    crate::sandbox::target_reclaim::ReclaimWorkLimits {
                        recovery_entries: 10_000,
                        filesystem_entries: 10_000,
                        allocated_bytes: u64::MAX,
                        duration: Duration::from_millis(500),
                        depth: 32,
                    },
                ),
            );
        let page_reached = Arc::new(Barrier::new(2));
        let page_release = Arc::new(Barrier::new(2));
        *reclaim_contention_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ReclaimContentionHook {
            base: sandbox_base.path().to_path_buf(),
            page_reached: Arc::clone(&page_reached),
            page_release: Arc::clone(&page_release),
            attempt_reached: Arc::new(Barrier::new(1)),
            attempt_release: Arc::new(Barrier::new(1)),
        });
        let store = Arc::clone(&manager.store);
        let controller = std::thread::spawn(move || {
            page_reached.wait();
            let guard = store.blocking_lock();
            page_release.wait();
            std::thread::sleep(Duration::from_millis(700));
            drop(guard);
        });

        let started = Instant::now();
        let first = manager
            .run_sandbox_build_cache_reclaim_with_evidence_for_trigger(false, "store_busy_test")
            .await
            .unwrap();
        controller.join().unwrap();
        *reclaim_contention_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        assert!(
            started.elapsed() < Duration::from_secs(4),
            "candidate wait is bounded"
        );
        assert_eq!(first.report.candidates_considered, 1, "{first:?}");
        assert_eq!(first.report.stop_reason, ReclaimStopReason::DurationBudget);
        assert_eq!(
            first
                .report
                .skip_counts
                .get(&ReclaimSkipReason::DurationBudget),
            Some(&1),
            "{first:?}"
        );
        assert!(cache.exists(), "a timed-out candidate keeps its target");

        let mut removed = false;
        for _ in 0..3 {
            let next = manager
                .run_sandbox_build_cache_reclaim(false)
                .await
                .unwrap();
            if next.fully_removed_count == 1 {
                removed = true;
                break;
            }
        }
        assert!(removed, "a later sweep cycle reclaims the retained target");
        assert!(!cache.exists());
    }

    #[derive(Default)]
    struct ReclaimLogVisitor(Vec<String>);

    impl tracing::field::Visit for ReclaimLogVisitor {
        fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn std::fmt::Debug) {
            self.0.push(format!("{}={value:?}", field.name()));
        }

        fn record_str(&mut self, field: &tracing::field::Field, value: &str) {
            self.0.push(format!("{}={value}", field.name()));
        }

        fn record_bool(&mut self, field: &tracing::field::Field, value: bool) {
            self.0.push(format!("{}={value}", field.name()));
        }

        fn record_u64(&mut self, field: &tracing::field::Field, value: u64) {
            self.0.push(format!("{}={value}", field.name()));
        }
    }

    struct ReclaimLogLayer {
        events: Arc<Mutex<Vec<String>>>,
    }

    impl<S: tracing::Subscriber> tracing_subscriber::Layer<S> for ReclaimLogLayer {
        fn on_event(
            &self,
            event: &tracing::Event<'_>,
            _ctx: tracing_subscriber::layer::Context<'_, S>,
        ) {
            if !matches!(
                *event.metadata().level(),
                tracing::Level::INFO | tracing::Level::WARN
            ) {
                return;
            }
            let mut visitor = ReclaimLogVisitor::default();
            event.record(&mut visitor);
            self.events.lock().unwrap().push(visitor.0.join(" "));
        }
    }

    #[tokio::test]
    async fn build_cache_reclaim_logs_zero_startup_and_periodic_summaries() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, _sandbox_base) = manager();
        let report = manager
            .run_sandbox_build_cache_reclaim(true)
            .await
            .expect("empty report");
        let run = SandboxReclaimRun::without_candidate_sweep(report);
        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        tracing::subscriber::with_default(subscriber, || {
            log_sandbox_build_cache_reclaim_terminal("startup", &run, false, 7, 11);
            log_sandbox_build_cache_reclaim_terminal("periodic", &run, false, 13, 17);
        });
        let events = events.lock().unwrap();
        assert_eq!(events.len(), 2);
        assert!(events[0].contains("trigger=startup"), "{:?}", *events);
        assert!(events[1].contains("trigger=periodic"), "{:?}", *events);
        for event in events.iter() {
            assert!(event.contains("considered=0"), "{event}");
            assert!(event.contains("NoCandidates"), "{event}");
            assert!(event.contains("reclaimed_bytes=0"), "{event}");
            assert!(event.contains("recovery_cycle_before=0"), "{event}");
            assert!(event.contains("recovery_cycle_after=0"), "{event}");
            assert!(event.contains("recovery_cursor_reserved=false"), "{event}");
            assert!(event.contains("recovery_entries_deleted=0"), "{event}");
            assert!(event.contains("recovery_legacy_migrated=0"), "{event}");
            assert!(event.contains("recovery_nonprogress_count=0"), "{event}");
            assert!(event.contains("run_duration_ms="), "{event}");
            assert!(event.contains("total_elapsed_ms="), "{event}");
        }
    }

    #[tokio::test]
    async fn build_cache_reclaim_reports_consecutive_store_pressure_stalls() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, _sandbox_base) = manager();
        let report = manager.run_sandbox_build_cache_reclaim(true).await.unwrap();
        let mut run = SandboxReclaimRun::without_candidate_sweep(report);
        run.report.dry_run = false;
        run.report.pressure_active_after = true;
        run.report
            .skip_counts
            .insert(ReclaimSkipReason::StoreBusy, 2);
        let state = SandboxReclaimWorkerState::default();
        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        tracing::subscriber::with_default(subscriber, || {
            log_reclaim_pressure_health("periodic", &run, &state);
            log_reclaim_pressure_health("periodic", &run, &state);
            assert_eq!(
                state
                    .consecutive_store_busy_pressure_passes
                    .load(Ordering::Acquire),
                2
            );
            run.report.reclaimed_bytes = 1;
            log_reclaim_pressure_health("periodic", &run, &state);
        });
        assert_eq!(
            state
                .consecutive_store_busy_pressure_passes
                .load(Ordering::Acquire),
            0
        );
        let events = events.lock().unwrap();
        assert_eq!(events.len(), 2);
        assert!(events[0].contains("consecutive_store_busy_pressure_passes=1"));
        assert!(events[1].contains("consecutive_store_busy_pressure_passes=2"));
        assert!(
            events
                .iter()
                .all(|event| event.contains("store_busy_skips=2"))
        );
    }

    #[tokio::test]
    async fn build_cache_reclaim_routes_injected_startup_preaccept_failures() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        for (fault, expected_error) in [
            (
                SandboxReclaimPreacceptFault::Construction,
                "injected sandbox reclaim coordinator construction failure",
            ),
            (
                SandboxReclaimPreacceptFault::Submission,
                "injected sandbox reclaim coordinator submission failure",
            ),
        ] {
            let (manager, _db, _sandbox_base) = manager();
            let manager_key = sandbox_reclaim_manager_key(&manager.store);
            let _fault = install_sandbox_reclaim_preaccept_fault_for_test(manager_key, fault);
            let events = Arc::new(Mutex::new(Vec::new()));
            let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
                events: Arc::clone(&events),
            });
            let _subscriber = tracing::subscriber::set_default(subscriber);

            let error = manager
                .run_sandbox_build_cache_reclaim_for_trigger(false, "startup")
                .await
                .expect_err("injected pre-accept failure");
            match error {
                DaemonError::Process(actual) => assert_eq!(actual, expected_error),
                other => panic!("unexpected error: {other:?}"),
            }
            assert!(
                !sandbox_reclaim_preaccept_faults()
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .contains_key(&manager_key),
                "{fault:?} injection must be consumed once"
            );

            let events = events.lock().unwrap();
            assert_eq!(events.len(), 1, "{fault:?}: {events:?}");
            let warning = &events[0];
            assert!(warning.contains("trigger=startup"), "{fault:?}: {events:?}");
            assert!(warning.contains("dry_run=false"), "{fault:?}: {events:?}");
            assert!(
                warning.contains("lifecycle_phase=error"),
                "{fault:?}: {events:?}"
            );
            assert!(
                warning.contains("request_cancelled=false"),
                "{fault:?}: {events:?}"
            );
            assert!(warning.contains(expected_error), "{fault:?}: {events:?}");
            assert!(
                events
                    .iter()
                    .all(|event| !event.contains("lifecycle_phase=started")
                        && !event.contains("lifecycle_phase=completed")),
                "{fault:?}: {events:?}"
            );
        }
    }

    #[tokio::test]
    async fn build_cache_reclaim_startup_submission_returns_while_owned_monitor_waits() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, _sandbox_base) = manager();
        let manager_key = sandbox_reclaim_manager_key(&manager.store);
        let entered = Arc::new(tokio::sync::Semaphore::new(0));
        let release = Arc::new(tokio::sync::Semaphore::new(0));
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ReclaimSingleFlightHook {
            manager_key,
            entered: Arc::clone(&entered),
            release: Arc::clone(&release),
        });
        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        let _subscriber = tracing::subscriber::set_default(subscriber);

        let submitted_at = Instant::now();
        manager
            .submit_sandbox_build_cache_reclaim_startup()
            .expect("startup submission is accepted");
        assert!(
            submitted_at.elapsed() < Duration::from_millis(75),
            "startup submission must not await the held lifecycle"
        );
        tokio::time::timeout(Duration::from_secs(1), entered.acquire())
            .await
            .expect("startup pass reaches the held worker")
            .expect("startup hold remains open")
            .forget();
        let coordinator = SandboxReclaimCoordinator::process_wide().unwrap();
        assert_eq!(coordinator.state.active.load(Ordering::Acquire), 1);
        assert_eq!(coordinator.state.queued.load(Ordering::Acquire), 0);

        release.add_permits(1);
        tokio::time::timeout(Duration::from_secs(1), async {
            while coordinator.state.active.load(Ordering::Acquire) != 0 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("startup pass settles");
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;

        let events = events.lock().unwrap();
        let startup: Vec<_> = events
            .iter()
            .filter(|event| event.contains("trigger=startup"))
            .collect();
        assert_eq!(
            startup
                .iter()
                .filter(|event| event.contains("lifecycle_phase=accepted"))
                .count(),
            1,
            "{events:?}"
        );
        assert_eq!(
            startup
                .iter()
                .filter(|event| event.contains("lifecycle_phase=started"))
                .count(),
            1,
            "{events:?}"
        );
        let terminal: Vec<_> = startup
            .iter()
            .filter(|event| event.contains("lifecycle_phase=completed"))
            .collect();
        assert_eq!(terminal.len(), 1, "{events:?}");
        assert!(
            terminal[0].contains("request_cancelled=false"),
            "{events:?}"
        );
        assert!(
            startup.iter().any(|event| event.contains("queue_wait_ms=")),
            "{events:?}"
        );
        assert!(terminal[0].contains("run_duration_ms="), "{events:?}");
        assert!(terminal[0].contains("total_elapsed_ms="), "{events:?}");
    }

    #[tokio::test]
    async fn build_cache_reclaim_startup_restore_logs_bounded_monotonic_authority_phases() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, _sandbox_base) = manager();
        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        let _subscriber = tracing::subscriber::set_default(subscriber);

        manager.restore_sessions().await.expect("restore sessions");

        let events = events.lock().unwrap();
        let expected_phases = [
            "stale_effect_and_settlement_recovery",
            "custody_classification",
            "controller_and_invocation_reconciliation",
            "session_rows_and_metrics",
            "lead_and_retry_reconciliation",
            "orphan_classification",
        ];
        let mut previous_index = None;
        for phase in expected_phases {
            let (index, event) = events
                .iter()
                .enumerate()
                .find(|(_, event)| event.contains(&format!("phase={phase}")))
                .unwrap_or_else(|| panic!("missing restore phase {phase}: {events:?}"));
            if let Some(previous_index) = previous_index {
                assert!(
                    previous_index < index,
                    "restore phases are ordered: {events:?}"
                );
            }
            previous_index = Some(index);
            assert!(event.contains("phase_duration_ms="), "{event}");
            assert!(event.contains("total_elapsed_ms="), "{event}");
        }
        let total = events
            .iter()
            .position(|event| event.contains("startup_milestone=authority_restore_complete"))
            .unwrap_or_else(|| panic!("missing total authority restore milestone: {events:?}"));
        assert!(previous_index.is_some_and(|last_phase| last_phase < total));
        assert!(
            events[total].contains("total_elapsed_ms="),
            "{:?}",
            events[total]
        );
    }

