    #[tokio::test]
    async fn build_cache_reclaim_supervises_outer_panic_and_continues_in_order() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, _sandbox_base) = manager();
        let manager_key = sandbox_reclaim_manager_key(&manager.store);
        *reclaim_outer_panic_manager_for_test()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(manager_key);
        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        let _subscriber = tracing::subscriber::set_default(subscriber);

        let error = manager
            .run_sandbox_build_cache_reclaim_for_trigger(true, "outer_panic")
            .await
            .expect_err("supervised panic must become a typed error");
        assert!(error.to_string().contains("coordinator job panicked"));
        manager
            .run_sandbox_build_cache_reclaim_for_trigger(true, "after_outer_panic")
            .await
            .expect("worker must continue after a supervised panic");

        let events = events.lock().unwrap();
        let panic_started = events
            .iter()
            .position(|event| {
                event.contains("trigger=outer_panic") && event.contains("lifecycle_phase=started")
            })
            .expect("panic job start");
        let panic_error = events
            .iter()
            .position(|event| {
                event.contains("trigger=outer_panic") && event.contains("lifecycle_phase=error")
            })
            .expect("panic job terminal error");
        let successor_started = events
            .iter()
            .position(|event| {
                event.contains("trigger=after_outer_panic")
                    && event.contains("lifecycle_phase=started")
            })
            .expect("successor start");
        let successor_completed = events
            .iter()
            .position(|event| {
                event.contains("trigger=after_outer_panic")
                    && event.contains("lifecycle_phase=completed")
            })
            .expect("successor completion");
        assert!(
            panic_started < panic_error
                && panic_error < successor_started
                && successor_started < successor_completed,
            "{events:?}"
        );
    }

