    async fn stage_pending_cache_for_contention(
        manager: &SessionManager,
        sandbox_base: &std::path::Path,
        session: &Session,
        generation: u64,
    ) -> Uuid {
        let root = sandbox_base.join(session.id.to_string());
        let pinned = crate::sandbox::target_reclaim::PinnedSandboxRoot::open(
            sandbox_base,
            &root,
            session.id,
        )
        .expect("pin cache root for registered recovery fixture");
        let identity = pinned
            .registered_target_identity()
            .expect("authenticate registered fixture target");
        let store = manager.store.lock().await;
        let custody_id: String = store
            .conn
            .query_row(
                "SELECT sandbox_custody_id FROM sessions WHERE id=?1",
                [session.id.to_string()],
                |row| row.get(0),
            )
            .expect("fixture custody id");
        let custody_id = Uuid::parse_str(&custody_id).expect("valid fixture custody id");
        let prepared = match store
            .prepare_target_reclaim_intent(custody_id, generation, identity.device, identity.inode)
            .expect("prepare registered recovery fixture")
        {
            crate::store::target_reclaim_sweep::PrepareTargetReclaimIntentResult::Active(
                intent,
            ) => intent,
            other => panic!("expected active registered fixture intent, got {other:?}"),
        };
        let intent = registered_filesystem_intent(&prepared);
        drop(store);
        assert_eq!(pinned.stage_registered_target(&intent).reason, None);
        let store = manager.store.lock().await;
        let staged = store
            .mark_target_reclaim_staged(&prepared)
            .expect("mark registered fixture staged");
        store
            .mark_target_reclaim_deleting(&staged)
            .expect("mark registered fixture deleting");
        drop(store);
        assert_eq!(
            crate::sandbox::target_reclaim::probe_registered_target(sandbox_base, &intent)
                .destination,
            crate::sandbox::target_reclaim::RegisteredNamespaceState::Expected
        );
        custody_id
    }

    async fn reclaim_candidate_custody_id(manager: &SessionManager, session_id: Uuid) -> Uuid {
        manager
            .store
            .lock()
            .await
            .preview_terminal_reclaim_page(64)
            .expect("preview reclaim fixture")
            .candidates
            .into_iter()
            .find(|candidate| candidate.session_id == session_id)
            .expect("fixture reclaim candidate")
            .custody_id
    }

    async fn run_contended_reclaim_pair(
        manager: Arc<SessionManager>,
        first_dry_run: bool,
        second_dry_run: bool,
    ) -> (
        SandboxBuildCacheReclaimReport,
        SandboxBuildCacheReclaimReport,
    ) {
        let manager_key = sandbox_reclaim_manager_key(&manager.store);
        let entered = Arc::new(tokio::sync::Semaphore::new(0));
        let release = Arc::new(tokio::sync::Semaphore::new(0));
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ReclaimSingleFlightHook {
            manager_key,
            entered: Arc::clone(&entered),
            release: Arc::clone(&release),
        });

        let first = {
            let manager = Arc::clone(&manager);
            tokio::spawn(
                async move { manager.run_sandbox_build_cache_reclaim(first_dry_run).await },
            )
        };
        entered
            .acquire()
            .await
            .expect("first pass reaches guarded transition")
            .forget();
        let second = {
            let manager = Arc::clone(&manager);
            tokio::spawn(async move {
                manager
                    .run_sandbox_build_cache_reclaim(second_dry_run)
                    .await
            })
        };
        assert!(
            tokio::time::timeout(Duration::from_millis(75), entered.acquire())
                .await
                .is_err(),
            "second pass must not touch the transition while the first owns it"
        );

        release.add_permits(1);
        let first_report = first
            .await
            .expect("first pass task")
            .expect("first pass report");
        entered
            .acquire()
            .await
            .expect("second pass enters only after first completion")
            .forget();
        release.add_permits(1);
        let second_report = second
            .await
            .expect("second pass task")
            .expect("second pass report");
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        (first_report, second_report)
    }

    #[tokio::test]
    async fn build_cache_reclaim_single_flight_serializes_dry_actual_and_actual_actual() {
        let _isolation = reclaim_test_isolation();
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, sandbox_base) = manager();
        let manager = Arc::new(manager);
        let repo = TempDir::new().expect("repo dir");
        init_d00_git_repo(repo.path());
        let stale = chrono::Utc::now() - chrono::Duration::hours(8);

        let (recovery, _recovery_cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        let (_candidate, candidate_cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        manager.persistence.barrier().await.unwrap();
        stage_pending_cache_for_contention(&manager, sandbox_base.path(), &recovery, 1).await;

        let pressure_before = manager
            .runtime_config
            .sandbox_build_cache_pressure_active
            .load(Ordering::Relaxed);
        let (preview, actual) = run_contended_reclaim_pair(Arc::clone(&manager), true, false).await;
        assert!(preview.dry_run);
        assert!(preview.staged_count >= 1 && preview.eligible_candidates >= 1);
        assert_eq!(preview.reclaimed_bytes, 0);
        assert_eq!(
            manager
                .runtime_config
                .sandbox_build_cache_pressure_active
                .load(Ordering::Relaxed),
            actual.pressure_active_after
        );
        assert_eq!(preview.pressure_active_before, pressure_before);
        assert!(!actual.dry_run);
        assert!(actual.recovered_count >= 1 && actual.newly_staged_count >= 1);
        assert!(!candidate_cache.exists());

        // The first pair can leave an already-reserved intent sweep upper
        // watermark. Close that empty suffix before creating the second
        // registered fixture so the next pair observes its own durable row.
        manager
            .run_sandbox_build_cache_reclaim(false)
            .await
            .expect("close prior registered intent sweep");

        let (recovery, _recovery_cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        let (_candidate, candidate_cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        manager.persistence.barrier().await.unwrap();
        stage_pending_cache_for_contention(&manager, sandbox_base.path(), &recovery, 1).await;
        let (first_actual, second_actual) =
            run_contended_reclaim_pair(Arc::clone(&manager), false, false).await;
        assert!(first_actual.recovered_count >= 1 && first_actual.newly_staged_count >= 1);
        assert!(!candidate_cache.exists());
        assert_eq!(second_actual.staged_count, 0);
        assert_eq!(second_actual.fully_removed_count, 0);
        assert_eq!(
            first_actual.pressure_active_after,
            second_actual.pressure_active_before
        );

        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        tracing::subscriber::with_default(subscriber, || {
            for report in [&preview, &actual, &first_actual, &second_actual] {
                let run = SandboxReclaimRun::without_candidate_sweep((*report).clone());
                log_sandbox_build_cache_reclaim_terminal("contention", &run, false, 1, 2);
            }
        });
        let events = events.lock().unwrap();
        assert_eq!(events.len(), 4);
        assert!(events.iter().all(|event| {
            event.contains("trigger=contention")
                && event.contains("pressure_before=")
                && event.contains("pressure_after=")
        }));
    }

    async fn assert_abort_keeps_reclaim_lease(recovered: bool, second_dry_run: bool) {
        use tracing_subscriber::layer::SubscriberExt;

        let (manager, _db, sandbox_base) = manager();
        let manager = Arc::new(manager);
        let repo = TempDir::new().expect("repo dir");
        init_d00_git_repo(repo.path());
        let stale = chrono::Utc::now() - chrono::Duration::hours(8);
        let (session, _cache) = build_cache_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Completed,
            stale,
        )
        .await;
        manager.persistence.barrier().await.unwrap();
        let barrier_custody_id = if recovered {
            stage_pending_cache_for_contention(&manager, sandbox_base.path(), &session, 1).await
        } else {
            reclaim_candidate_custody_id(&manager, session.id).await
        };

        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        let _subscriber = tracing::subscriber::set_default(subscriber);
        let (reached_tx, reached_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        crate::sandbox::target_reclaim::set_target_deletion_signal_for_test(
            barrier_custody_id,
            reached_tx,
            release_rx,
        );
        let first_trigger = if recovered {
            "abort_recovery_first"
        } else {
            "abort_candidate_first"
        };
        let second_trigger = if recovered {
            "abort_recovery_second"
        } else {
            "abort_candidate_second"
        };
        let first = {
            let manager = Arc::clone(&manager);
            tokio::spawn(async move {
                run_build_cache_reclaim_trigger_fixture(&manager, false, first_trigger, true).await
            })
        };
        tokio::task::spawn_blocking(move || reached_rx.recv_timeout(Duration::from_secs(2)))
            .await
            .expect("target deletion signal waiter")
            .expect("first request reaches the custody-owned deletion seam");
        first.abort();
        assert!(first.await.unwrap_err().is_cancelled());

        let manager_key = sandbox_reclaim_manager_key(&manager.store);
        let entered = Arc::new(tokio::sync::Semaphore::new(0));
        let enter_release = Arc::new(tokio::sync::Semaphore::new(0));
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ReclaimSingleFlightHook {
            manager_key,
            entered: Arc::clone(&entered),
            release: Arc::clone(&enter_release),
        });
        let second = {
            let manager = Arc::clone(&manager);
            tokio::spawn(async move {
                run_build_cache_reclaim_trigger_fixture(
                    &manager,
                    second_dry_run,
                    second_trigger,
                    true,
                )
                .await
            })
        };
        assert!(
            tokio::time::timeout(Duration::from_millis(75), entered.acquire())
                .await
                .is_err(),
            "cancelled caller must not release daemon-owned lifecycle lease"
        );

        release_tx
            .send(())
            .expect("release blocked first reclaim worker");
        tokio::time::timeout(Duration::from_secs(2), entered.acquire())
            .await
            .expect("second pass enters after bounded worker release")
            .expect("second pass enters after first terminal log")
            .forget();
        {
            let events = events.lock().unwrap();
            let first_terminal = events
                .iter()
                .position(|event| {
                    event.contains(first_trigger)
                        && event.contains("lifecycle_phase=completed")
                        && event.contains("request_cancelled=true")
                })
                .expect("cancelled first request has terminal lifecycle log");
            let second_started = events
                .iter()
                .position(|event| {
                    event.contains(second_trigger) && event.contains("lifecycle_phase=started")
                })
                .expect("second request start log");
            assert!(
                first_terminal < second_started,
                "ordered lifecycle logs: {events:?}"
            );
        }
        enter_release.add_permits(1);
        second.await.expect("second request task");
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
    }

