    fn assert_request_runtime_shutdown_keeps_reclaim_job(recovered: bool, second_dry_run: bool) {
        use tracing_subscriber::layer::SubscriberExt;

        let events = Arc::new(Mutex::new(Vec::new()));
        let subscriber = tracing_subscriber::registry().with(ReclaimLogLayer {
            events: Arc::clone(&events),
        });
        let _subscriber = tracing::subscriber::set_default(subscriber);
        let request_runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let (manager, _db, sandbox_base, release_tx) = request_runtime.block_on(async {
            let (manager, db, sandbox_base) = manager();
            let manager = Arc::new(manager);
            let repo = TempDir::new().expect("repo dir");
            init_d00_git_repo(repo.path());
            let stale = chrono::Utc::now() - chrono::Duration::hours(8);
            let (session, _cache) = build_cache_row(
                &manager,
                repo.path(),
                sandbox_base.path(),
                SessionStatus::Completed,
                stale,
            )
            .await;
            manager.persistence.barrier().await.unwrap();
            let barrier_custody_id = if recovered {
                stage_pending_cache_for_contention(&manager, sandbox_base.path(), &session, 1).await
            } else {
                reclaim_candidate_custody_id(&manager, session.id).await
            };
            let (reached_tx, reached_rx) = std::sync::mpsc::channel();
            let (release_tx, release_rx) = std::sync::mpsc::channel();
            crate::sandbox::target_reclaim::set_target_deletion_signal_for_test(
                barrier_custody_id,
                reached_tx,
                release_rx,
            );
            let first_trigger = if recovered {
                "shutdown_recovery_first"
            } else {
                "shutdown_candidate_first"
            };
            let request_manager = Arc::clone(&manager);
            tokio::spawn(async move {
                run_build_cache_reclaim_trigger_fixture(
                    &request_manager,
                    false,
                    first_trigger,
                    true,
                )
                .await
            });
            tokio::task::spawn_blocking(move || reached_rx.recv_timeout(Duration::from_secs(2)))
                .await
                .expect("target deletion signal waiter")
                .expect("request runtime reaches the custody-owned deletion seam");
            (manager, db, sandbox_base, release_tx)
        });
        drop(request_runtime);

        let manager_key = sandbox_reclaim_manager_key(&manager.store);
        let entered = Arc::new(tokio::sync::Semaphore::new(0));
        let enter_release = Arc::new(tokio::sync::Semaphore::new(0));
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ReclaimSingleFlightHook {
            manager_key,
            entered: Arc::clone(&entered),
            release: Arc::clone(&enter_release),
        });
        let successor_runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let second_trigger = if recovered {
            "shutdown_recovery_second"
        } else {
            "shutdown_candidate_second"
        };
        let successor = {
            let manager = Arc::clone(&manager);
            successor_runtime.spawn(async move {
                run_build_cache_reclaim_trigger_fixture(
                    &manager,
                    second_dry_run,
                    second_trigger,
                    false,
                )
                .await
            })
        };
        assert!(
            successor_runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_millis(75), entered.acquire()).await
                })
                .is_err(),
            "request runtime shutdown must not admit a successor while worker I/O is active"
        );

        release_tx
            .send(())
            .expect("release blocked reclaim worker before dropping request runtime");
        successor_runtime
            .block_on(async {
                tokio::time::timeout(Duration::from_secs(2), entered.acquire()).await
            })
            .expect("successor enters after bounded worker release")
            .expect("successor enters after worker terminal log")
            .forget();
        {
            let events = events.lock().unwrap();
            let first_terminal = events
                .iter()
                .position(|event| {
                    event.contains(if recovered {
                        "trigger=shutdown_recovery_first"
                    } else {
                        "trigger=shutdown_candidate_first"
                    }) && event.contains("lifecycle_phase=completed")
                        && event.contains("request_cancelled=true")
                })
                .expect("shutdown request has one cancellation-aware terminal log");
            let second_started = events
                .iter()
                .position(|event| {
                    event.contains(if recovered {
                        "trigger=shutdown_recovery_second"
                    } else {
                        "trigger=shutdown_candidate_second"
                    }) && event.contains("lifecycle_phase=started")
                })
                .expect("successor start log");
            assert!(first_terminal < second_started, "{events:?}");
        }
        enter_release.add_permits(1);
        successor_runtime
            .block_on(successor)
            .expect("successor request task");
        *reclaim_single_flight_hook()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        drop(sandbox_base);
        drop(_db);
    }

