    async fn all_active_reservations(store: &Arc<tokio::sync::Mutex<Store>>) -> i64 {
        let store = store.lock().await;
        store
            .conn
            .query_row(
                "SELECT COALESCE(SUM(active_count), 0) FROM model_budget_counters",
                [],
                |row| row.get(0),
            )
            .expect("sum model-control active reservations")
    }

    async fn scheduled_job_active_reservations(
        store: &Arc<tokio::sync::Mutex<Store>>,
        scheduled_job_id: Uuid,
    ) -> i64 {
        let store = store.lock().await;
        store
            .conn
            .query_row(
                "SELECT COALESCE(SUM(active_count), 0)
                 FROM model_budget_counters
                 WHERE scope_kind = 'scheduled_job' AND scope_id = ?1",
                rusqlite::params![scheduled_job_id.to_string()],
                |row| row.get(0),
            )
            .expect("sum scheduled-job model-control reservations")
    }

    async fn spawn_blocking_local_test_provider()
    -> (tokio::task::JoinHandle<()>, String, Arc<AtomicUsize>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind deterministic local test provider");
        let address = listener
            .local_addr()
            .expect("read local test provider address");
        let dispatches = Arc::new(AtomicUsize::new(0));
        let dispatches_for_server = Arc::clone(&dispatches);
        let server = tokio::spawn(async move {
            let (_stream, _) = listener
                .accept()
                .await
                .expect("accept one local provider request");
            dispatches_for_server.fetch_add(1, Ordering::SeqCst);
            std::future::pending::<()>().await;
        });
        (server, format!("http://{address}/v1"), dispatches)
    }

    async fn wait_for_backend_dispatch(dispatches: &AtomicUsize) {
        tokio::time::timeout(Duration::from_secs(1), async {
            while dispatches.load(Ordering::SeqCst) == 0 {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("local provider must receive exactly one backend dispatch");
    }

    async fn cleanup_active_test_session(
        manager: &SessionManager,
        session_id: Uuid,
        invocation_id: Uuid,
    ) {
        let tracked = manager
            .active
            .write()
            .await
            .remove(&session_id)
            .expect("remove deterministic test session from active map");
        if let Some(mut process) = tracked.process {
            process
                .kill()
                .await
                .expect("stop deterministic local test provider");
        }
        crate::model_control::complete_invocation_by_id(
            &manager.store,
            invocation_id,
            InvocationCompletion::default(),
            manager.event_bus(),
        )
        .await
        .expect("settle deterministic test admission");
        manager.revoke_agent_token_for_session(session_id).await;
    }

