    #[tokio::test]
    async fn agent_fresh_exact_replay_uses_one_reservation_and_backend_dispatch() {
        let (manager, _dir, _sandbox) = manager();
        let (server, base_url, dispatches) = spawn_blocking_local_test_provider().await;
        let scheduled_job_id = Uuid::new_v4();
        let mut config = scheduled_fresh_test_config(
            ModelInvocationPurpose::AgentScheduleWakeFresh,
            SessionProvider::Local,
            std::env::current_dir().expect("current working directory"),
            None,
            scheduled_job_id,
        );
        config.openai_base_url = Some(base_url);

        let first_session_id = manager
            .launch_scheduled_fresh(config.clone(), true)
            .await
            .expect("first AgentFresh launch");
        wait_for_backend_dispatch(&dispatches).await;
        let reservation_after_first =
            scheduled_job_active_reservations(&manager.store, scheduled_job_id).await;
        assert!(reservation_after_first > 0);
        assert_eq!(manager.agent_tokens.read().await.len(), 1);

        let duplicate = manager
            .launch_scheduled_fresh(config, true)
            .await
            .expect_err("same scheduled job and due slot must replay the existing admission");
        assert!(matches!(duplicate, DaemonError::PolicyDenied(_)));
        assert_eq!(manager.agent_tokens.read().await.len(), 1);
        assert_eq!(manager.active.read().await.len(), 1);
        assert_eq!(dispatches.load(Ordering::SeqCst), 1);
        assert_eq!(
            scheduled_job_active_reservations(&manager.store, scheduled_job_id).await,
            reservation_after_first
        );

        let (row_count, invocation_id) = {
            let store = manager.store.lock().await;
            let row_count: i64 = store
                .conn
                .query_row(
                    "SELECT COUNT(*) FROM model_invocations WHERE scheduled_job_id = ?1",
                    rusqlite::params![scheduled_job_id.to_string()],
                    |row| row.get(0),
                )
                .expect("count one replay-owned invocation");
            let invocation_id = store
                .session_model_invocation_id(first_session_id)
                .expect("load first scheduled Fresh binding")
                .expect("first scheduled Fresh binding exists");
            (row_count, invocation_id)
        };
        assert_eq!(row_count, 1);

        cleanup_active_test_session(&manager, first_session_id, invocation_id).await;
        assert_eq!(
            scheduled_job_active_reservations(&manager.store, scheduled_job_id).await,
            0
        );
        server.abort();
    }

    #[test]
    fn developer_instruction_pipeline_covers_every_supported_non_codex_provider() {
        for provider in [
            SessionProvider::Claude,
            SessionProvider::Local,
            SessionProvider::Antigravity,
            SessionProvider::Harness,
            SessionProvider::CodexAppServer,
        ] {
            assert!(
                provider_uses_launch_system_prompt(provider),
                "{provider:?} must receive the shared worker contract"
            );
        }

        // Codex CLI providers receive the same contract through their first-turn
        // stdin payload; see `codex::stdin_payload_prepends_nudge_first_turn_only`.
        for provider in [
            SessionProvider::Codex,
            SessionProvider::Pioneer,
            SessionProvider::OpenRouter,
        ] {
            assert!(!provider_uses_launch_system_prompt(provider));
        }
    }

