    #[tokio::test]
    async fn restore_then_reconcile_repairs_witnessed_completed_and_failed_owners() {
        use rsi_common::agent_coordination::AgentSpawnChildRequestV1;

        let (manager, _database_directory, _sandbox) = manager();
        let mut cases = Vec::new();
        {
            let store = manager.store.lock().await;
            for (label, owner_status, witness) in [
                ("idle-completed", SessionStatus::Completed, true),
                ("restore-failed", SessionStatus::Running, true),
                ("archived", SessionStatus::Archived, true),
                ("deleted", SessionStatus::Deleted, true),
                ("legacy", SessionStatus::Completed, false),
            ] {
                let owner_id = Uuid::new_v4();
                let epic_id = Uuid::new_v4();
                let child_id = Uuid::new_v4();
                let request_id = Uuid::new_v4();
                let mut owner = test_session(owner_id);
                owner.status = owner_status;
                let mut epic = test_session(epic_id);
                epic.session_kind = SessionKind::Epic;
                epic.status = SessionStatus::Completed;
                epic.lead_session_id = Some(owner_id);
                let mut child = test_session(child_id);
                child.status = SessionStatus::Completed;
                child.parent_id = Some(epic_id);
                store.insert_session(&owner).expect("insert owner");
                store.insert_session(&epic).expect("insert epic");
                store.insert_session(&child).expect("insert child");
                let request = AgentSpawnChildRequestV1 {
                    kind: SessionKind::Task,
                    provider: None,
                    model: None,
                    effort: None,
                    query: "watch repair".into(),
                    agent_role: None,
                    topology_node: None,
                    iteration: None,
                    tags: None,
                    idempotency_key: label.into(),
                };
                store
                    .reserve_agent_spawn_request(
                        owner_id,
                        &crate::model_control::hash_request_fingerprint(&["watch-key", label]),
                        &crate::model_control::hash_request_fingerprint(&["watch-request", label]),
                        &request,
                        epic_id,
                        request_id,
                        child_id,
                    )
                    .expect("reserve child");
                store
                    .mark_agent_spawn_queued(request_id)
                    .expect("queue child");
                store
                    .mark_agent_spawn_launching(request_id)
                    .expect("launch child");
                let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
                store.conn.execute(
                    "UPDATE agent_spawn_requests SET state='launched',updated_at=?1,launched_at=?1 WHERE spawn_request_id=?2",
                    rusqlite::params![now, request_id.to_string()],
                ).expect("settle launched child");
                if witness {
                    store.conn.execute(
                        "INSERT INTO agent_child_watch_witness (owner_session_id,child_session_id,job_id,state,updated_at) VALUES (?1,?2,NULL,'pending',?3)",
                        rusqlite::params![owner_id.to_string(), child_id.to_string(), now],
                    ).expect("record V123 arm intent");
                }
                cases.push((label, owner_id, child_id));
            }
        }

        // This is the daemon's startup order: restore first changes Running
        // owners to Failed, then the child-watch repair reads durable state.
        manager.restore_sessions().await.expect("restore sessions");
        {
            let store = manager.store.lock().await;
            assert_eq!(
                store
                    .get_session(cases[1].1)
                    .expect("load owner")
                    .expect("owner")
                    .status,
                SessionStatus::Failed,
            );
        }
        manager
            .agent_control()
            .reconcile_automatic_child_watches()
            .await
            .expect("repair watches");
        let jobs = manager
            .store
            .lock()
            .await
            .list_scheduled_jobs()
            .expect("load watches");
        for (label, owner_id, child_id) in cases {
            let count = jobs
                .iter()
                .filter(|job| {
                    job.enabled
                        && job.wake_session_id == Some(owner_id)
                        && job.wake_mode == WakeMode::OnTerminal(child_id)
                })
                .count();
            let expected = usize::from(matches!(label, "idle-completed" | "restore-failed"));
            assert_eq!(count, expected, "watch repair eligibility for {label}");
        }
    }

    #[tokio::test]
    async fn restore_pending_archive_uses_acknowledged_marker_settlement() {
        let (manager, _dir, _sandbox) = manager();
        let session_id = Uuid::new_v4();
        let mut session = test_session(session_id);
        session.pending_archive = true;
        session.status = SessionStatus::Failed;
        {
            let store = manager.store.lock().await;
            store
                .insert_session(&session)
                .expect("insert pending archive row");
            store
                .update_failed_and_stage_c5_autofile(
                    session_id,
                    crate::store::daemon_settings::AutofileCause::ProcessDied,
                )
                .expect("stage marker");
        }

        manager.restore_sessions().await.expect("restore sessions");

        let store = manager.store.lock().await;
        let row = store
            .get_session(session_id)
            .expect("load session")
            .expect("session exists");
        assert_eq!(row.status, SessionStatus::Archived);
        assert!(!row.pending_archive);
        assert!(
            store
                .get_daemon_setting(&crate::store::daemon_settings::c5_autofile_pending_key(
                    session_id
                ),)
                .expect("load marker")
                .is_none(),
            "restore archive must acknowledge marker resolution before publishing archive"
        );
    }

    #[tokio::test]
    async fn restore_pending_archive_captures_terminal_notice_before_pointer_clear() {
        let (manager, database_directory, _sandbox) = manager();
        let (manager_id, epic_id, lead_id) = pending_archive_manager_fixture(&manager).await;

        manager.restore_sessions().await.unwrap();

        {
            let store = manager.store.lock().await;
            assert_eq!(
                store.get_session(lead_id).unwrap().unwrap().status,
                SessionStatus::Archived
            );
            assert_eq!(
                store.get_session(epic_id).unwrap().unwrap().lead_session_id,
                None
            );
            assert!(
                store
                    .get_daemon_setting(&crate::store::daemon_settings::c5_autofile_pending_key(
                        lead_id
                    ),)
                    .unwrap()
                    .is_none(),
                "pending archive recovery must not expose an autofile replay marker"
            );
        }
        drop(manager);

        let reopened = Store::open(&database_directory.path().join("rsi.db")).unwrap();
        let job: String = reopened
            .conn
            .query_row(
                "SELECT job_id FROM harness_manager_notices
                 WHERE source_session_id=?1 AND kind='session_state'",
                [lead_id.to_string()],
                |row| row.get(0),
            )
            .unwrap();
        let job = Uuid::parse_str(&job).unwrap();
        assert!(reopened.get_scheduled_job(&job).unwrap().unwrap().enabled);
        let inbox = reopened
            .manager_inbox(manager_id, &AgentManagerInboxRequestV1::default())
            .unwrap();
        let notice = inbox
            .notices
            .iter()
            .find(|notice| notice.source_session_id == Some(lead_id))
            .unwrap();
        assert_eq!(notice.state["status"], "Failed");
        assert_eq!(notice.epic_id, Some(epic_id));
        assert_eq!(notice.retrieved_at, notice.settled_at);
    }

