    #[tokio::test]
    async fn restore_running_pending_archive_terminalization_failure_keeps_route_retryable() {
        let (manager, _database_directory, _sandbox) = manager();
        let (_manager_id, epic_id, lead_id) =
            pending_archive_manager_fixture_with_status(&manager, SessionStatus::Running).await;
        {
            let store = manager.store.lock().await;
            store
                .conn
                .execute_batch(&format!(
                    "CREATE TRIGGER fail_restore_pending_archive_terminalization
                     BEFORE UPDATE OF status ON sessions
                     WHEN OLD.id='{lead_id}' AND NEW.status='Failed'
                     BEGIN SELECT RAISE(ABORT,'injected-crash-terminalization'); END;"
                ))
                .unwrap();
        }

        manager.restore_sessions().await.unwrap();

        {
            let store = manager.store.lock().await;
            let lead = store.get_session(lead_id).unwrap().unwrap();
            assert_eq!(lead.status, SessionStatus::Running);
            assert!(lead.pending_archive);
            assert_eq!(
                store.get_session(epic_id).unwrap().unwrap().lead_session_id,
                Some(lead_id)
            );
            assert!(
                store
                    .get_daemon_setting(&crate::store::daemon_settings::c5_autofile_pending_key(
                        lead_id
                    ),)
                    .unwrap()
                    .is_none(),
                "failed terminalization must not create an autofile replay marker"
            );
            let notice_count: i64 = store
                .conn
                .query_row(
                    "SELECT count(*) FROM harness_manager_notices
                     WHERE source_session_id=?1 AND kind='session_state'",
                    [lead_id.to_string()],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(notice_count, 0);
            store
                .conn
                .execute_batch("DROP TRIGGER fail_restore_pending_archive_terminalization;")
                .unwrap();
        }

        manager.restore_sessions().await.unwrap();

        let store = manager.store.lock().await;
        let lead = store.get_session(lead_id).unwrap().unwrap();
        assert_eq!(lead.status, SessionStatus::Archived);
        assert!(!lead.pending_archive);
        assert_eq!(
            store.get_session(epic_id).unwrap().unwrap().lead_session_id,
            None
        );
        let notice_state: String = store
            .conn
            .query_row(
                "SELECT state_json FROM harness_manager_notices
                 WHERE source_session_id=?1 AND kind='session_state'",
                [lead_id.to_string()],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&notice_state).unwrap()["status"],
            "Failed"
        );
    }

