    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn restore_pending_archive_commits_metadata_without_sandbox_cleanup() {
        let (manager, _db_dir, sandbox_base) = manager();
        let repo = TempDir::new().expect("repo tempdir");
        init_d00_git_repo(repo.path());
        let (mut session, allocation, _) = d00_sandbox_row(
            &manager,
            repo.path(),
            sandbox_base.path(),
            SessionStatus::Failed,
        )
        .await;
        session.pending_archive = true;
        {
            let store = manager.store.lock().await;
            store
                .update_pending_archive(session.id, true)
                .expect("set durable pending archive");
            store
                .update_failed_and_stage_c5_autofile(
                    session.id,
                    crate::store::daemon_settings::AutofileCause::ProcessDied,
                )
                .expect("stage C5 marker");
        }
        std::fs::write(allocation.root.join("recoverable.txt"), "retain\n")
            .expect("write recoverable sandbox content");
        let before =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        let mut events = manager.event_bus().subscribe();

        manager
            .restore_sessions()
            .await
            .expect("restore pending archive");

        let after =
            d00_durable_evidence(&manager, repo.path(), &allocation.root, &[session.id]).await;
        assert_eq!(after.tree, before.tree);
        assert_eq!(after.refs, before.refs);
        assert_eq!(after.worktrees, before.worktrees);
        assert_eq!(after.index, before.index);
        let before_row = before.rows[0].1.as_ref().expect("before row");
        let after_row = after.rows[0].1.as_ref().expect("after row");
        for field in [
            "sandbox_kind",
            "sandbox_root",
            "sandbox_branch",
            "sandbox_cleanup_state",
            "parent_id",
            "lead_session_id",
        ] {
            assert_eq!(after_row.get(field), before_row.get(field), "{field}");
        }
        assert_eq!(
            after_row.get("status").and_then(serde_json::Value::as_str),
            Some("Archived")
        );
        assert_eq!(
            after_row
                .get("pending_archive")
                .and_then(serde_json::Value::as_bool),
            Some(false)
        );
        assert!(
            manager
                .store
                .lock()
                .await
                .get_daemon_setting(&crate::store::daemon_settings::c5_autofile_pending_key(
                    session.id
                ),)
                .expect("load C5 marker")
                .is_none(),
            "restore archive must acknowledge C5 only after durable metadata archive"
        );
        let archived = std::iter::from_fn(|| events.try_recv().ok())
            .any(|event| matches!(event.as_ref(), DaemonEvent::SessionArchived { .. }));
        assert!(archived, "restore archive must emit metadata success");
        manager.event_bus().unsubscribe();
    }

    async fn wait_for_retry_state(
        manager: &SessionManager,
        session_id: Uuid,
        retry_attempt: Option<u8>,
        max_retries: Option<u8>,
    ) -> Session {
        let deadline = tokio::time::Instant::now() + Duration::from_millis(500);
        loop {
            let row = manager
                .store
                .lock()
                .await
                .get_session(session_id)
                .expect("load session")
                .expect("session row");
            if row.retry_attempt == retry_attempt && row.max_retries == max_retries {
                return row;
            }
            assert!(
                tokio::time::Instant::now() < deadline,
                "timed out waiting for retry state {:?}/{:?}; last row had {:?}/{:?}",
                retry_attempt,
                max_retries,
                row.retry_attempt,
                row.max_retries
            );
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
    }

