    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn restore_requeues_persisted_retry_budgets_only_when_runtime_policy_is_enabled() {
        let (mut manager, _dir, _sandbox) = manager_with_smoke_suppress_retry_restore(false);
        manager
            .runtime_config
            .retry_enabled
            .store(true, Ordering::Relaxed);
        let mut retry_rx = manager.take_retry_rx().expect("retry rx");
        let story_id = Uuid::new_v4();
        let task_id = Uuid::new_v4();
        insert_failed_session(&manager, story_id, SessionKind::Story, 0, 2).await;
        insert_failed_session(&manager, task_id, SessionKind::Task, 0, 2).await;

        manager.restore_sessions().await.expect("restore sessions");

        assert_eq!(
            manager
                .completed
                .read()
                .await
                .get(&story_id)
                .expect("story restored")
                .session
                .retry_attempt,
            Some(1),
            "Persisted retry budgets must re-arm once the runtime policy is explicitly enabled"
        );
        let first = tokio::time::timeout(Duration::from_millis(100), retry_rx.recv())
            .await
            .expect("first persisted retry should be queued")
            .expect("retry channel open");
        let second = tokio::time::timeout(Duration::from_millis(100), retry_rx.recv())
            .await
            .expect("second persisted retry should be queued")
            .expect("retry channel open");
        let queued: std::collections::HashSet<Uuid> = [first, second].into_iter().collect();
        let expected: std::collections::HashSet<Uuid> = [story_id, task_id].into_iter().collect();
        assert_eq!(queued, expected);
    }

