    async fn arm_c5_pending_retry(manager: &SessionManager, session_id: Uuid) {
        let mut session = test_session(session_id);
        session.status = SessionStatus::Failed;
        session.retry_attempt = Some(1);
        session.max_retries = Some(2);
        {
            let store = manager.store.lock().await;
            store
                .insert_session(&session)
                .expect("insert failed retry row");
            store
                .update_failed_and_stage_c5_autofile(
                    session_id,
                    crate::store::daemon_settings::AutofileCause::ProcessDied,
                )
                .expect("stage pending marker");
        }
        let (cancel_tx, _cancel_rx) = tokio::sync::oneshot::channel();
        manager.completed.write().await.insert(
            session_id,
            super::super::types::CompletedSession {
                session,
                events: Vec::new(),
                turn_metrics: Vec::new(),
                retry_cancel: Some(cancel_tx),
                retry_fired_at: None,
                superseded_by_retry: None,
                events_hydrated: true,
            },
        );
    }

    async fn failed_c5_retry_admission(
        manager: &SessionManager,
        session_id: Uuid,
    ) -> super::super::types::RetryAdmission {
        {
            let mut completed = manager.completed.write().await;
            let owner = completed
                .get_mut(&session_id)
                .expect("completed retry owner exists");
            owner.retry_cancel = None;
            owner.retry_fired_at = Some(std::time::Instant::now());
        }
        let marker = manager
            .store
            .lock()
            .await
            .get_c5_autofile_pending(&crate::store::daemon_settings::c5_autofile_pending_key(
                session_id,
            ))
            .expect("read retry marker")
            .expect("retry marker exists");
        let source = manager
            .store
            .lock()
            .await
            .get_session(session_id)
            .expect("read retry source")
            .expect("retry source exists");
        let candidate = manager
            .custody_execution_runtime()
            .prepare_retry_successor(&source)
            .await
            .expect("prepare ordinary retry custody");
        let admission =
            super::super::types::RetryAdmission::new(session_id, 1, 2, marker, source, candidate);
        admission.mark_attempted();
        admission.mark_failed(true);
        admission
    }

    #[tokio::test]
    async fn c5_retryable_admission_failure_rearms_only_with_the_live_durable_owner() {
        let (manager, _dir, _sandbox) = manager();
        let session_id = Uuid::new_v4();
        arm_c5_pending_retry(&manager, session_id).await;
        let admission = failed_c5_retry_admission(&manager, session_id).await;

        manager
            .rearm_retry_after_retryable_admission(&admission)
            .await;
        let completed = manager.completed.read().await;
        let owner = completed.get(&session_id).expect("retry owner retained");
        assert!(owner.retry_cancel.is_some(), "guarded rearm installs owner");
        assert!(owner.retry_fired_at.is_none(), "rearm clears fired marker");
        drop(completed);

        assert!(manager.cancel_retry(session_id).await.unwrap());
        let key = crate::store::daemon_settings::c5_autofile_pending_key(session_id);
        assert!(
            manager
                .store
                .lock()
                .await
                .get_c5_autofile_pending(&key)
                .unwrap()
                .is_none()
        );
        assert!(
            manager
                .completed
                .read()
                .await
                .get(&session_id)
                .expect("parent remains observable")
                .retry_cancel
                .is_none()
        );
    }

