    #[tokio::test]
    async fn c5_cancel_retry_race_has_one_truthful_committed_winner() {
        let (manager, _dir, _sandbox) = manager();
        let session_id = Uuid::new_v4();
        arm_c5_pending_retry(&manager, session_id).await;
        let barrier = Arc::new(tokio::sync::Barrier::new(2));
        let first_barrier = Arc::clone(&barrier);
        let second_barrier = Arc::clone(&barrier);
        let first = async {
            first_barrier.wait().await;
            manager.cancel_retry(session_id).await.unwrap()
        };
        let second = async {
            second_barrier.wait().await;
            manager.cancel_retry(session_id).await.unwrap()
        };
        let (first, second) = tokio::join!(first, second);

        assert_ne!(
            first, second,
            "only the Store-committed cancellation reports success"
        );
        let key = crate::store::daemon_settings::c5_autofile_pending_key(session_id);
        assert!(
            manager
                .store
                .lock()
                .await
                .get_daemon_setting(&key)
                .unwrap()
                .is_none()
        );
    }

