    #[tokio::test]
    async fn scheduled_fresh_explicit_rotation_input_isolates_concurrent_and_nested_calls() {
        use super::super::rotation_coordinator::{RotationAction, RotationEvent};

        let scheduled = tokio::spawn(async {
            let mut session = test_session(Uuid::new_v4());
            let mut coordinator = initialize_session_rotation(&mut session, true, true);
            (
                session.rotation_disabled_at.is_some(),
                matches!(
                    coordinator.advance(RotationEvent::ThresholdCheck { pct: 90.0 }),
                    RotationAction::NoOp
                ),
            )
        });
        let normal = tokio::spawn(async {
            let mut session = test_session(Uuid::new_v4());
            let mut coordinator = initialize_session_rotation(&mut session, false, true);
            (
                session.rotation_disabled_at.is_none(),
                matches!(
                    coordinator.advance(RotationEvent::ThresholdCheck { pct: 90.0 }),
                    RotationAction::InterruptForRotation
                ),
            )
        });
        assert_eq!(scheduled.await.expect("scheduled task"), (true, true));
        assert_eq!(normal.await.expect("normal task"), (true, true));

        let mut scheduled_child = test_session(Uuid::new_v4());
        initialize_session_rotation(&mut scheduled_child, true, true);
        let mut nested_normal_child = test_session(Uuid::new_v4());
        let mut nested_retry_child = test_session(Uuid::new_v4());
        initialize_session_rotation(&mut nested_normal_child, false, true);
        initialize_session_rotation(&mut nested_retry_child, false, true);
        assert!(scheduled_child.rotation_disabled_at.is_some());
        assert!(nested_normal_child.rotation_disabled_at.is_none());
        assert!(nested_retry_child.rotation_disabled_at.is_none());

        let source = include_str!("launch.rs");
        let production_source = &source[..source.find("\nmod tests {").expect("test module")];
        assert!(production_source.contains(
            "config,\n            None,\n            false,\n            LaunchPurpose::Interactive,\n            None,"
        ));
        assert!(production_source.contains(
            "Some(admission),\n            false,\n            LaunchPurpose::Interactive,\n            None,"
        ));
        assert!(production_source.contains(
            "None,\n            initial_rotation_disabled,\n            LaunchPurpose::Interactive,\n            None,"
        ));
        assert!(!production_source.contains("SCHEDULED_FRESH_INITIAL_ROTATION_DISABLED"));
    }

