    #[derive(Debug, PartialEq, Eq)]
    struct H1RetryRootSnapshot {
        state: String,
        owner: Option<String>,
        generation: i64,
        event_sequence: i64,
        validation_state: String,
        validated_generation: Option<i64>,
        validation_error: Option<String>,
        canonical_repo: String,
        sandbox_root: String,
        sandbox_branch: String,
        repository_identity: String,
        source_commit: String,
        reserved_effects: i64,
        active_effects: i64,
        event_count: i64,
    }

    fn h1_retry_root_snapshot(store: &Store, custody_id: Uuid) -> H1RetryRootSnapshot {
        store
            .conn
            .query_row(
                "SELECT state,owner_session_id,generation,event_sequence,validation_state,
                        validated_generation,validation_error_code,canonical_repo_dir,
                        sandbox_root,sandbox_branch,repository_identity,source_commit,
                        reserved_effects,active_effects,
                        (SELECT COUNT(*) FROM sandbox_custody_events WHERE custody_id=?1)
                 FROM sandbox_custody_roots WHERE custody_id=?1",
                [custody_id.to_string()],
                |row| {
                    Ok(H1RetryRootSnapshot {
                        state: row.get(0)?,
                        owner: row.get(1)?,
                        generation: row.get(2)?,
                        event_sequence: row.get(3)?,
                        validation_state: row.get(4)?,
                        validated_generation: row.get(5)?,
                        validation_error: row.get(6)?,
                        canonical_repo: row.get(7)?,
                        sandbox_root: row.get(8)?,
                        sandbox_branch: row.get(9)?,
                        repository_identity: row.get(10)?,
                        source_commit: row.get(11)?,
                        reserved_effects: row.get(12)?,
                        active_effects: row.get(13)?,
                        event_count: row.get(14)?,
                    })
                },
            )
            .expect("retry custody root snapshot")
    }

    async fn h1_bind_d03_retry_source_live(
        manager: &SessionManager,
        source_id: Uuid,
        repo: &std::path::Path,
    ) -> (SandboxAllocation, Uuid) {
        let allocation = manager
            .sandbox_allocator
            .allocate(source_id, repo, SandboxKind::GitWorktree, "HEAD", None)
            .expect("allocate live controller retry source");
        let mut store = manager.store.lock().await;
        let mut source = store
            .get_session(source_id)
            .expect("read D03 retry source")
            .expect("D03 retry source exists");
        source.working_dir = std::fs::canonicalize(repo).expect("canonical D03 retry repo");
        let binding = h1_retry_live_binding(&mut source, &allocation);
        store
            .conn
            .execute(
                "UPDATE sessions
                 SET working_dir=?2,sandbox_kind='GitWorktree',sandbox_root=?3,
                     sandbox_branch=?4,sandbox_cleanup_state='Live'
                 WHERE id=?1",
                rusqlite::params![
                    source_id.to_string(),
                    source.working_dir.display().to_string(),
                    source.sandbox_root.as_ref().unwrap().display().to_string(),
                    source.sandbox_branch.as_deref().unwrap(),
                ],
            )
            .expect("stage D03 live retry tuple");
        store
            .conn
            .execute(
                "UPDATE session_execution_projections
                 SET execution_state='live_sandboxed',freshness='unverified',
                     canonical_repo_dir=?2,effective_cwd=NULL,custody_id=NULL,
                     custody_generation=NULL,validated_at=NULL,error_code=NULL
                 WHERE session_id=?1",
                rusqlite::params![
                    source_id.to_string(),
                    source.working_dir.display().to_string()
                ],
            )
            .expect("stage D03 live retry projection");
        store
            .bind_reserved_session_custody(source_id, binding)
            .expect("bind D03 live retry source");
        let custody_id = store
            .live_custody_for_session(source_id)
            .expect("authenticate D03 live retry source")
            .custody_id;
        (allocation, custody_id)
    }

