    #[tokio::test]
    async fn agent_child_execution_scratch_failure_uses_post_bind_settlement_and_retains_root() {
        let (manager, _dir, _sandbox) = manager();
        let repo = tempfile::tempdir().expect("canonical repo");
        init_d00_git_repo(repo.path());
        let canonical = std::fs::canonicalize(repo.path()).expect("canonical path");
        let emitter = h1_7g_ordinary_emitter(&canonical);
        manager
            .store
            .lock()
            .await
            .insert_session(&emitter)
            .expect("insert ordinary emitter");
        let (child_server, child_base_url, child_dispatches) =
            spawn_blocking_local_test_provider().await;
        let request =
            h1_7g_reserve_spawn_request(&manager, emitter.id, canonical, child_base_url).await;
        let spawn_request_id = request.spawn_request_id;
        let child_id = request.child_session_id;
        let control_key = request
            .config
            .model_invocation_dedup_key
            .clone()
            .expect("agent child control key");
        fail_next_direct_launch_execution_scratch_for_test(&control_key);

        let error = manager
            .launch_agent_child(request)
            .await
            .expect_err("agent child target symlink must fail closed");
        assert!(
            error.to_string().contains("execution scratch rejected"),
            "unexpected agent child descriptor failure: {error}"
        );
        assert_eq!(child_dispatches.load(Ordering::SeqCst), 0);
        assert!(!manager.active.read().await.contains_key(&child_id));
        assert!(
            !manager
                .agent_tokens
                .read()
                .await
                .values()
                .any(|session_id| *session_id == child_id)
        );

        let store = manager.store.lock().await;
        let (spawn_state, safe_error_class) = h1_7g_spawn_row(&store, spawn_request_id);
        assert_eq!(spawn_state, "failed");
        assert_eq!(
            safe_error_class.as_deref(),
            Some("execution_scratch_unavailable")
        );
        let child = store
            .get_session(child_id)
            .expect("load descriptor-failed child")
            .expect("descriptor-failed child exists");
        assert_eq!(child.status, SessionStatus::Failed);
        assert_eq!(
            child.stop_reason.as_deref(),
            Some("sandbox_custody:execution_scratch_unavailable")
        );
        assert_eq!(child.sandbox_cleanup_state, Some(SandboxCleanupState::Live));
        let root = child.sandbox_root.expect("retained child root");
        let projection: (String, String, Option<String>, Option<String>, Option<i64>, String) =
            store.conn.query_row(
                "SELECT execution_state,freshness,effective_cwd,custody_id,custody_generation,error_code
                 FROM session_execution_projections WHERE session_id=?1",
                [child_id.to_string()],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                        row.get(5)?,
                    ))
                },
            )
            .expect("load failed child projection");
        assert_eq!(projection.0, "invalid");
        assert_eq!(projection.1, "invalid");
        assert_eq!(projection.2, None);
        assert!(
            projection.3.is_some(),
            "failed child retains its custody link"
        );
        assert_eq!(projection.4, Some(1));
        assert_eq!(projection.5, "execution_scratch_unavailable");
        let (_, _, generation, owner, root_state) = h1_7g_child_custody_root(&store, child_id);
        assert_eq!(generation, 1);
        assert_eq!(owner, child_id.to_string());
        assert_eq!(root_state, "live");
        let invocation_id = store
            .session_model_invocation_id(child_id)
            .expect("load child invocation")
            .expect("child invocation exists");
        let invocation: (String, Option<String>) = store
            .conn
            .query_row(
                "SELECT status,error_class FROM model_invocations WHERE id=?1",
                [invocation_id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("load failed child invocation");
        assert_eq!(
            invocation,
            (
                "failed".into(),
                Some("execution_scratch_unavailable".into())
            )
        );
        drop(store);
        assert!(
            std::fs::symlink_metadata(root.join("target"))
                .expect("target symlink remains descriptor failure evidence")
                .file_type()
                .is_symlink()
        );
        assert!(!root.join(".rsi-tmp").exists());
        child_server.abort();
    }

    async fn assert_agent_child_final_scratch_failure_state(
        manager: &SessionManager,
        spawn_request_id: Uuid,
        child_id: Uuid,
    ) {
        let settled = tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let failed = manager
                    .store
                    .lock()
                    .await
                    .get_session(child_id)
                    .expect("load post-preparation child")
                    .is_some_and(|child| child.status == SessionStatus::Failed);
                if failed {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await;
        if settled.is_err() {
            let active_generation = manager
                .active
                .read()
                .await
                .get(&child_id)
                .map(|tracked| tracked.spawn_generation);
            let token_present = manager
                .agent_tokens
                .read()
                .await
                .token_for_session(child_id)
                .is_some();
            let store = manager.store.lock().await;
            let child = store.get_session(child_id).expect("load timed-out child");
            let request = h1_7g_spawn_row(&store, spawn_request_id);
            let invocation = store
                .session_model_invocation_id(child_id)
                .expect("load timed-out invocation")
                .and_then(|id| {
                    store
                        .load_model_invocation_record(id)
                        .expect("load timed-out invocation record")
                });
            panic!(
                "post-preparation scratch failure did not settle: active_generation={active_generation:?} token_present={token_present} child={child:?} request={request:?} invocation={invocation:?}"
            );
        }

        assert!(
            !manager.active.read().await.contains_key(&child_id),
            "only the failed active incarnation is removed"
        );
        assert!(
            manager
                .agent_tokens
                .read()
                .await
                .token_for_session(child_id)
                .is_none(),
            "the exact failed launch token is revoked"
        );
        let store = manager.store.lock().await;
        let (request_state, request_error) = h1_7g_spawn_row(&store, spawn_request_id);
        assert_eq!(request_state, "failed");
        assert_eq!(
            request_error.as_deref(),
            Some("execution_scratch_unavailable")
        );
        let child = store
            .get_session(child_id)
            .expect("load failed post-preparation child")
            .expect("failed post-preparation child exists");
        assert_eq!(child.status, SessionStatus::Failed);
        assert_eq!(
            child.stop_reason.as_deref(),
            Some("sandbox_custody:execution_scratch_unavailable")
        );
        assert_eq!(child.sandbox_cleanup_state, Some(SandboxCleanupState::Live));
        let invocation_id = store
            .session_model_invocation_id(child_id)
            .expect("load post-preparation invocation")
            .expect("post-preparation invocation exists");
        let invocation: (String, Option<String>) = store
            .conn
            .query_row(
                "SELECT status,error_class FROM model_invocations WHERE id=?1",
                [invocation_id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("load post-preparation invocation state");
        assert_eq!(
            invocation,
            (
                "failed".into(),
                Some("execution_scratch_unavailable".into())
            )
        );
        let projection: (String, String, Option<String>, String) = store
            .conn
            .query_row(
                "SELECT execution_state,freshness,effective_cwd,error_code
                 FROM session_execution_projections WHERE session_id=?1",
                [child_id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .expect("load post-preparation projection state");
        assert_eq!(
            projection,
            (
                "invalid".into(),
                "invalid".into(),
                None,
                "execution_scratch_unavailable".into()
            )
        );
        let (_, _, generation, owner, root_state) = h1_7g_child_custody_root(&store, child_id);
        assert_eq!(generation, 1);
        assert_eq!(owner, child_id.to_string());
        assert_eq!(root_state, "live");
    }

