    async fn h1_7g_assert_custody_refusal(
        manager: &SessionManager,
        error: &DaemonError,
        spawn_request_id: Uuid,
        child_session_id: Uuid,
        sandbox_base: &std::path::Path,
        code: rsi_common::types::SandboxCustodyErrorCodeV1,
    ) {
        assert_eq!(
            crate::sandbox::custody::custody_error_code(error),
            Some(code),
            "refusal must carry the bounded custody code, got: {error}"
        );
        let store = manager.store.lock().await;
        let (state, safe_error_class) = h1_7g_spawn_row(&store, spawn_request_id);
        assert_eq!(state, "failed");
        assert_eq!(
            safe_error_class.as_deref(),
            Some(format!("sandbox_custody.{}", code.as_str()).as_str())
        );
        let child = store
            .get_session(child_session_id)
            .expect("load settled child")
            .expect("settled child row durable");
        assert_eq!(child.status, SessionStatus::Failed);
        assert_eq!(
            child.stop_reason.as_deref(),
            Some(format!("sandbox_custody:{}", code.as_str()).as_str())
        );
        assert!(child.sandbox_kind.is_none());
        assert!(child.sandbox_root.is_none());
        assert!(child.sandbox_branch.is_none());
        assert!(child.sandbox_cleanup_state.is_none());
        let projection: (String, String, Option<String>, Option<String>) = store
            .conn
            .query_row(
                "SELECT execution_state,freshness,effective_cwd,error_code FROM session_execution_projections WHERE session_id=?1",
                [child_session_id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .expect("load settled child projection");
        assert_eq!(projection.0, "invalid");
        assert_eq!(projection.1, "invalid");
        assert_eq!(projection.2, None);
        assert_eq!(projection.3, Some(code.as_str().to_string()));
        // Zero child-side filesystem effect: no allocated root for the child.
        assert!(
            !sandbox_base.join(child_session_id.to_string()).exists(),
            "refused fork must not leave a child sandbox root"
        );
    }

    #[tokio::test]
    async fn h1_v83_spawn_child_fork_custody_dirty_live_emitter_refuses_before_any_child_side_effect()
     {
        let (manager, _dir, sandbox_base) = manager();
        let repo = tempfile::tempdir().expect("canonical repo");
        init_d00_git_repo(repo.path());
        let canonical = std::fs::canonicalize(repo.path()).expect("canonical path");
        let (emitter_id, emitter_root, emitter_server) =
            h1_7g_launch_live_emitter(&manager, &canonical).await;
        std::fs::write(emitter_root.join("uncommitted.txt"), "dirty\n").expect("dirty emitter");
        let (child_server, child_base_url, child_dispatches) =
            spawn_blocking_local_test_provider().await;
        let request =
            h1_7g_reserve_spawn_request(&manager, emitter_id, canonical.clone(), child_base_url)
                .await;
        let spawn_request_id = request.spawn_request_id;
        let child_session_id = request.child_session_id;

        let error = manager
            .launch_agent_child(request)
            .await
            .expect_err("dirty live emitter must refuse the fork");
        h1_7g_assert_custody_refusal(
            &manager,
            &error,
            spawn_request_id,
            child_session_id,
            sandbox_base.path(),
            rsi_common::types::SandboxCustodyErrorCodeV1::SourceWorktreeDirty,
        )
        .await;
        // No provider dispatch ever reached the child backend.
        assert_eq!(child_dispatches.load(Ordering::SeqCst), 0);
        assert!(manager.active.read().await.get(&child_session_id).is_none());
        {
            // Emitter custody, root, and generation are untouched.
            let store = manager.store.lock().await;
            let (_, _, generation, owner, state) = h1_7g_child_custody_root(&store, emitter_id);
            assert_eq!(generation, 1);
            assert_eq!(owner, emitter_id.to_string());
            assert_eq!(state, "live");
        }
        assert!(emitter_root.join("uncommitted.txt").exists());
        h1_7g_cleanup_child(&manager, emitter_id).await;
        child_server.abort();
        emitter_server.abort();
    }

