    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn agent_successor_execution_scratch_failure_settles_exact_bound_candidate() {
        let (manager, dir, _sandbox) = manager();
        init_d00_git_repo(dir.path());
        let (epic_id, predecessor_id, receipt) = successor_launch_fixture(
            &manager,
            dir.path(),
            "successor-execution-scratch-failure",
            SessionProvider::Claude,
        )
        .await;
        manager
            .store
            .lock()
            .await
            .update_session_status(predecessor_id, SessionStatus::Completed)
            .expect("settle predecessor");
        let scripted = install_controller_candidate_test_process(receipt.candidate_session_id);
        let (reached, resume) = install_controller_candidate_test_pause(
            receipt.candidate_session_id,
            ControllerCandidateTestPhase::SuccessorAfterDurablePreEffect,
        );
        let mut reconcile = Box::pin(manager.reconcile_agent_successor(receipt.reservation_id));
        tokio::select! {
            result = &mut reconcile => panic!("successor crossed descriptor-failure pause: {result:?}"),
            reached = reached => reached.expect("successor reached durable pre-effect boundary"),
        }
        let invocation_id = assert_successor_pre_effect_boundary(
            &manager,
            epic_id,
            predecessor_id,
            &receipt,
            false,
        )
        .await;
        let root = manager
            .store
            .lock()
            .await
            .get_session(receipt.candidate_session_id)
            .expect("load bound successor")
            .expect("bound successor exists")
            .sandbox_root
            .expect("bound successor root");
        std::os::unix::fs::symlink(&root, root.join("target"))
            .expect("install target symlink after ContextRead boundary bind");
        resume.send(()).expect("resume descriptor-failure launch");
        let error = reconcile
            .await
            .expect_err("successor scratch preparation must fail closed");
        assert!(error.to_string().contains("execution scratch rejected"));
        assert_eq!(scripted.productive_start_count.load(Ordering::SeqCst), 0);

        let store = manager.store.lock().await;
        let failed = store
            .get_agent_successor(receipt.reservation_id)
            .expect("load failed successor reservation")
            .expect("failed successor reservation exists");
        assert_eq!(
            failed.state,
            rsi_common::agent_coordination::AgentSuccessorStateV1::Failed
        );
        assert_eq!(
            failed.safe_error_class.as_deref(),
            Some("execution_scratch_unavailable")
        );
        let candidate = store
            .get_session(receipt.candidate_session_id)
            .expect("load failed successor candidate")
            .expect("failed successor candidate exists");
        assert_eq!(candidate.status, SessionStatus::Failed);
        assert_eq!(
            candidate.stop_reason.as_deref(),
            Some("authenticated execution scratch preparation failed")
        );
        assert_eq!(
            candidate.sandbox_cleanup_state,
            Some(SandboxCleanupState::Live)
        );
        assert_eq!(
            store
                .get_session(epic_id)
                .expect("load successor Epic")
                .expect("successor Epic exists")
                .lead_session_id,
            Some(predecessor_id)
        );
        let invocation = store
            .load_model_invocation_record(invocation_id)
            .expect("load failed successor invocation")
            .expect("failed successor invocation exists");
        assert_eq!(
            invocation.status,
            rsi_common::model_control::ModelInvocationStatus::Failed
        );
        assert_eq!(
            invocation.error_class.as_deref(),
            Some("execution_scratch_unavailable")
        );
        let custody = store
            .live_custody_for_session(receipt.candidate_session_id)
            .expect("failed successor retains its owned root");
        assert_eq!(custody.owner_session_id, receipt.candidate_session_id);
        assert_eq!(custody.generation, 1);
        drop(store);
        assert!(
            manager
                .agent_tokens
                .read()
                .await
                .token_for_session(receipt.candidate_session_id)
                .is_none()
        );
        assert!(
            std::fs::symlink_metadata(root.join("target"))
                .expect("target symlink remains descriptor failure evidence")
                .file_type()
                .is_symlink()
        );
        assert!(!root.join(".rsi-tmp").exists());
        drop_controller_candidate_test_process(receipt.candidate_session_id);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn agent_successor_sync_effect_fence_rejects_post_bind_topology_corruption() {
        for provider in [
            SessionProvider::Claude,
            SessionProvider::Codex,
            SessionProvider::Antigravity,
            SessionProvider::Local,
            SessionProvider::Harness,
        ] {
            let (manager, dir, _sandbox) = manager();
            init_d00_git_repo(dir.path());
            let (epic_id, predecessor_id, receipt) = successor_launch_fixture(
                &manager,
                dir.path(),
                &format!("{provider:?}-post-bind-topology-corruption"),
                provider,
            )
            .await;
            let predecessor_token =
                crate::session::remint_agent_token(&manager.agent_tokens, predecessor_id).await;
            manager
                .store
                .lock()
                .await
                .update_session_status(predecessor_id, SessionStatus::Completed)
                .expect("settle predecessor");
            let scripted = install_controller_candidate_test_process(receipt.candidate_session_id);
            let (reached, resume) = install_controller_candidate_test_pause(
                receipt.candidate_session_id,
                ControllerCandidateTestPhase::SuccessorAfterDurablePreEffect,
            );
            let mut reconcile = Box::pin(manager.reconcile_agent_successor(receipt.reservation_id));
            tokio::select! {
                result = &mut reconcile => panic!("{provider:?} successor crossed post-bind corruption pause: {result:?}"),
                reached = reached => reached.expect("successor reached post-bind corruption pause"),
            }
            let invocation_id = assert_successor_pre_effect_boundary(
                &manager,
                epic_id,
                predecessor_id,
                &receipt,
                false,
            )
            .await;

            let other_epic_id = Uuid::new_v4();
            let mut other_epic = test_session(other_epic_id);
            other_epic.session_kind = SessionKind::Epic;
            other_epic.status = SessionStatus::Completed;
            other_epic.parent_id = None;
            other_epic.lead_session_id = None;
            manager
                .store
                .lock()
                .await
                .insert_session(&other_epic)
                .expect("insert empty reparent target Epic");

            assert!(
                manager
                    .set_session_parent(receipt.candidate_session_id, Some(other_epic_id))
                    .await
                    .expect_err("ordinary reparent must not mutate a reserved successor")
                    .to_string()
                    .contains("agent_successor_candidate_topology_locked")
            );
            assert!(
                manager
                    .set_epic_lead(epic_id, Some(receipt.candidate_session_id))
                    .await
                    .expect_err("ordinary lead assignment must not promote a reserved successor")
                    .to_string()
                    .contains("agent_successor_epic_lead_locked")
            );
            {
                let store = manager.store.lock().await;
                assert_eq!(
                    store
                        .get_session(other_epic_id)
                        .expect("load empty reparent target Epic")
                        .expect("empty reparent target Epic exists")
                        .lead_session_id,
                    None
                );
                store
                    .conn
                    .execute(
                        "UPDATE sessions SET parent_id=?1,updated_at=?2 WHERE id=?3",
                        rusqlite::params![
                            other_epic_id.to_string(),
                            chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true),
                            receipt.candidate_session_id.to_string()
                        ],
                    )
                    .expect("inject durable post-bind topology corruption");
            }
            resume
                .send(())
                .expect("release corrupted provider-effect fence");
            assert!(
                reconcile
                    .await
                    .expect_err("corrupted provider-effect fence must reject launch")
                    .to_string()
                    .contains("agent_successor_provider_effect_candidate_mismatch")
            );
            manager
                .reconcile_agent_successor(receipt.reservation_id)
                .await
                .expect("terminal rejected successor replay is inert");

            assert_eq!(scripted.productive_start_count.load(Ordering::SeqCst), 0);
            let store = manager.store.lock().await;
            let failed = store
                .get_agent_successor(receipt.reservation_id)
                .expect("load rejected successor reservation")
                .expect("rejected successor reservation exists");
            assert_eq!(
                failed.state,
                rsi_common::agent_coordination::AgentSuccessorStateV1::Failed
            );
            assert_eq!(
                failed.safe_error_class.as_deref(),
                Some("agent_successor_provider_effect_fence_rejected")
            );
            let candidate = store
                .get_session(receipt.candidate_session_id)
                .expect("load rejected successor candidate")
                .expect("rejected successor candidate exists");
            assert_eq!(candidate.status, SessionStatus::Failed);
            assert_eq!(candidate.parent_id, Some(epic_id));
            assert_eq!(candidate.continued_from, Some(predecessor_id));
            assert_eq!(
                store
                    .get_session(epic_id)
                    .expect("load predecessor Epic")
                    .expect("predecessor Epic exists")
                    .lead_session_id,
                Some(predecessor_id)
            );
            assert_eq!(
                store
                    .get_session(other_epic_id)
                    .expect("reload empty reparent target Epic")
                    .expect("empty reparent target Epic remains")
                    .lead_session_id,
                None
            );
            assert_eq!(
                store
                    .load_model_invocation_record(invocation_id)
                    .expect("load rejected successor invocation")
                    .expect("rejected successor invocation exists")
                    .status,
                rsi_common::model_control::ModelInvocationStatus::Failed
            );
            drop(store);
            let tokens = manager.agent_tokens.read().await;
            assert!(
                tokens
                    .token_for_session(receipt.candidate_session_id)
                    .is_none()
            );
            assert_eq!(tokens.get(&predecessor_token), Some(&predecessor_id));
            drop(tokens);
            drop_controller_candidate_test_process(receipt.candidate_session_id);
        }
    }

